/**
 * @module
 * Leaf of the http tier: the one shared axios instance, configured but otherwise inert — no
 * interceptors, no imports of this app. `index.ts` wires the interceptors onto it.
 */

import axiosClient from 'axios';

/**
 * The shared axios instance every generated client goes through.
 *
 * Deliberately imports nothing of this app: it is the leaf of the http tier, so importing it can
 * never re-enter `index.ts` mid-evaluation.
 *
 * `withCredentials` is what carries the httpOnly refresh cookie, so the refresh flow works
 * without the token ever being readable from JS.
 */
export const instance = axiosClient.create({
    headers: {
        Accept: 'application/json',
        'Content-Type': 'application/json; charset=utf-8'
    },
    withCredentials: true,
    timeout: Number.parseInt(import.meta.env.VITE_AXIOS_TIMEOUT ?? '10000')
});

/**
 * Prefix of every relative call; an absolute URL ignores it. `__E2E_API_URL` is the e2e shard
 * runner's runtime override — each shard owns its own demo backend, and one built bundle cannot
 * bake four URLs — set on the window before the app boots (see tests/support/e2e/commands.ts'
 * `visit` overwrite). Nothing else ever defines it.
 */
instance.defaults.baseURL =
    (globalThis as { __E2E_API_URL?: string }).__E2E_API_URL ?? import.meta.env.VITE_API_URL ?? '';

src/infrastructure/http/envelope.ts.source:
/**
 * @module
 * Type-guard based readers for the two envelopes the API answers in: the `{ data }` wrapper around
 * a payload, and the `{ errors: [...] }` list a rejection carries. Both narrow to a plain object
 * first and check the key, so nothing here trusts a declared type past the wire.
 *
 * Here rather than in a store because the envelope is a property of the transport: a login
 * response and a product list arrive in the same wrapper, and neither is the session's business.
 */

/**
 * One structured error as the reject envelope carries it. Both fields stay `unknown`: the shape
 * is asserted by the generated types, never verified, so the reader narrows and the caller checks.
 */
export interface ApiErrorItem {
    /** Machine-readable reason, e.g. `REAUTH_REQUIRED`. */
    code?: unknown;
    /** Per-code extra payload, e.g. `retryAfter` on a rate-limit refusal. */
    details?: unknown;
}

/**
 * Narrows any value to a plain keyed object.
 *
 * @param value - Value to test.
 * @returns `true` when `value` is a non-null object.
 */
const isObjectRecord = (value: unknown): value is Record<string, unknown> =>
    typeof value === 'object' && value !== null;

/**
 * Detects the `{ data }` envelope.
 *
 * @param response - Raw API response.
 * @returns `true` when the value carries a `data` property.
 */
// eslint-disable-next-line @typescript-eslint/no-unnecessary-type-parameters -- the type parameter names the caller's payload in the predicate; without it the narrowing is to `unknown`
const isWrappedResponse = <T>(response: unknown): response is { data?: T } =>
    isObjectRecord(response) && 'data' in response;

/**
 * Reads the access token out of a login or refresh response.
 *
 * @param response - Raw API response.
 * @returns The token, or `undefined` when the response carries none.
 */
export const getTokenFromResponse = (response?: unknown): string | undefined =>
    isWrappedResponse<{ token?: string }>(response) ? response.data?.token : undefined;

/**
 * Extracts the payload from both wrapped (`{ data }`) and direct responses.
 *
 * @typeParam T - Expected payload type.
 * @param response - Raw API response.
 * @returns The unwrapped payload, or `undefined` when absent.
 */
export const getPayloadFromResponse = <T>(response?: { data?: T } | T): T | undefined =>
    isWrappedResponse<T>(response) ? response.data : response;

/**
 * Reads `errors[0]` off a rejection — the envelope `onResponseReject` builds, or an axios error's
 * own `response.data`. An empty `errors` array is legal at the type level, so nothing here may
 * assume there is a first entry.
 *
 * @param value - The rejected value, or the raw error body; still unknown at this boundary.
 * @returns The first structured error, or `undefined` when the shape does not match.
 */
export const getFirstApiError = (value: unknown): ApiErrorItem | undefined => {
    if (!isObjectRecord(value)) return undefined;
    const items = value.errors;
    if (!Array.isArray(items)) return undefined;
    const [item] = items as unknown[];
    return isObjectRecord(item) ? item : undefined;
};

src/infrastructure/http/index.ts.source:
/**
 * @module
 * Composition root of the http tier: imports the leaf modules, wires the interceptors onto the
 * shared axios instance, and exposes `orvalMutator` as the one function every generated client
 * call goes through.
 *
 * This file is the tier's public surface — `orval.config.ts` points every generated client at
 * `orvalMutator` here, and the request interceptors are re-exported beside it because their specs
 * exercise them through this module. Everything else is imported from its own leaf file.
 */
import { instance } from './client.ts';
import { onRequest, onRequestReject } from './interceptors.ts';
import { onResponseRejectWithStepUp } from './step-up.ts';
import { shouldValidateResponses, validateResponseAgainstContract } from './validate.ts';
import type { AxiosRequestConfig } from 'axios';

instance.interceptors.request.use(onRequest, onRequestReject);
// Step-up wraps refresh: a `REAUTH_REQUIRED` 401 has to be caught before the refresh branch would
// "fix" it by renewing a cookie that was never the problem — see `step-up.ts`'s own module doc.
instance.interceptors.response.use(undefined, onResponseRejectWithStepUp);

/**
 * Custom orval mutator: the *only* function allowed to call the shared axios instance directly.
 * Anything that needs the API — generated or hand-written — goes through here, so there is
 * exactly one place that unwraps a response and one place behaviour is configured.
 *
 * The second parameter is what orval calls the mutator's "second arg": declaring it gives every
 * generated function an `options?` argument, which is the supported way to pass per-call axios
 * config (`onUploadProgress` for uploads, `signal` for cancellation) without reaching for
 * `orvalMutator` directly. `config` comes from codegen and wins on conflict.
 *
 * `headers` merge one level deeper on purpose: every generated call with a body sets
 * `Content-Type`, so a top-level merge would drop the caller's headers on exactly the requests
 * most likely to need one — including the multipart boundary.
 *
 * @typeParam T - Response payload type expected by the caller.
 * @param config - Request config, built by the generated client.
 * @param options - Per-call axios overrides supplied by the caller.
 * @returns A promise resolving with the unwrapped response body (`response.data`).
 */
export const orvalMutator = <T>(
    config: AxiosRequestConfig,
    options?: AxiosRequestConfig
): Promise<T> => {
    const request: AxiosRequestConfig = {
        ...options,
        ...config,
        // eslint-disable-next-line @typescript-eslint/no-misused-spread -- AxiosHeaders' own enumerable entries are exactly what an object spread copies; axios documents this merge
        headers: { ...options?.headers, ...config.headers }
    };
    return instance.request<T>(request).then((response) => {
        if (shouldValidateResponses()) validateResponseAgainstContract(request, response.data);
        return response.data;
    });
};

export { onRequest, onRequestReject, onResponseReject } from './interceptors.ts';

