/**
 * @module
 * Route table for the inventory domain — one entry, lazy-loaded so the ledger's bundle only
 * loads when the page is actually navigated to.
 */
import type { RouteRecordRaw } from 'vue-router';

/**
 * Inventory routes: one admin page — the stock board, the ledger behind it, and the receipt form.
 */
export default [
    {
        path: 'inventory',
        name: 'InventoryLedger',
        component: () => import('./views/InventoryLedger.vue'),
        meta: { access: 'admin', title: 'inventory-page.page-title' }
    }
] satisfies RouteRecordRaw[];

src/modules/inventory/store.ts.source:
/**
 * @module
 * Pinia store for the inventory domain. Wraps `useStructureRestApi` for its shared loading
 * bookkeeping; the two reads are whole-list replacement and the three writes reload both views
 * before resolving, so no caller ever observes a counter the views have not caught up with.
 */
import { ref } from 'vue';
import { defineStore } from 'pinia';
import { useCoreStore, useStructureRestApi } from '@guebbit/vue-toolkit';
import {
    adjustStock,
    listInventoryLevels,
    listStockMovements,
    receiveStock,
    sweepReservations
} from '@api';
import type {
    InventoryLevel,
    StockMovement,
    ListInventoryLevelsParams,
    ListStockMovementsParams
} from '@types';

/**
 * The stock board and the ledger behind it.
 *
 * Two reads and three writes, and the split between the writes is the domain's, not this store's:
 *
 * - a RECEIPT is stock arriving. `onHand` rises, `reserved` does not, so the delivery is available
 *   immediately. Strictly positive — a delivery that removes units is not a delivery.
 * - an ADJUSTMENT is a stocktake correction, and it is SIGNED, because shrinkage is the common
 *   case and it is negative. The API refuses to take `onHand` below what is already reserved.
 * - the SWEEP releases every hold whose window has closed. A job behind an admin endpoint — the
 *   API ships no scheduler, so the tick is driven from outside, and this store is one of the
 *   outsides. Idempotent; running it twice releases nothing the first run already released.
 *
 * All three answer with (or change) the counters, and all three reload the views they touched:
 * the row worth rendering is the API's, never a local guess. That is also why nothing here does
 * arithmetic on a count — `available` is derived server-side from `onHand` and `reserved`, and a
 * second implementation of that subtraction is a second thing that can be wrong.
 *
 * Both reads keep their `meta.totalItems`, because both are paginated server-side and the ledger
 * especially is the record an audit works through — a bare row count would misreport history as
 * complete.
 */
export const useInventoryStore = defineStore('inventory', () => {
    /**
     * This store's slice of the app-wide loading registry.
     */
    const { getLoading, setLoading } = useCoreStore();

    /**
     * Shared loading flag plus the request runner every read/write below goes through.
     */
    const { loading, fetchAny } = useStructureRestApi<StockMovement, string>({
        getLoading,
        setLoading
    });

    /**
     * The latest movements, as last fetched.
     */
    const movements = ref<StockMovement[]>([]);

    /**
     * How many movements match the last filters, across every page.
     */
    const movementsTotal = ref(0);

    /**
     * The last movements query, so a write can reload the page being looked at.
     */
    let movementsQuery: ListStockMovementsParams = {};

    /**
     * The current shelf counts, one row per product on the current page.
     */
    const levels = ref<InventoryLevel[]>([]);

    /**
     * How many products the board holds, across every page.
     */
    const levelsTotal = ref(0);

    /**
     * The last levels query, for the same reload-what-is-shown reason.
     */
    let levelsQuery: ListInventoryLevelsParams = {};

    /**
     * Loads a page of the ledger.
     *
     * @param query - Page, size, and the two narrowings: one product's story, one kind of
     *  transition. Omitted, the last query is repeated — which is what a reload after a write
     *  wants, since the visitor is still looking at the same page.
     * @returns A promise resolving with the movements.
     */
    const fetchMovements = (query?: ListStockMovementsParams) =>
        fetchAny(() => {
            if (query) movementsQuery = query;
            return listStockMovements(movementsQuery).then((response) => {
                movements.value = response.data.items;
                movementsTotal.value = response.data.meta.totalItems;
                return movements.value;
            });
        });

    /**
     * Loads a page of the stock board, most scarce first.
     *
     * @param query - Page, size, and `lowOnly` — only products at or under the server's
     *  low-availability threshold. Omitted, the last query is repeated.
     * @returns A promise resolving with the levels.
     */
    const fetchLevels = (query?: ListInventoryLevelsParams) =>
        fetchAny(() => {
            if (query) levelsQuery = query;
            return listInventoryLevels(levelsQuery).then((response) => {
                levels.value = response.data.items;
                levelsTotal.value = response.data.meta.totalItems;
                return levels.value;
            });
        });

    /**
     * Receives a delivery, then reloads what it changed.
     *
     * @param productId - The product the units arrived for.
     * @param quantity - How many arrived. Strictly positive.
     * @param note - The supplier, the delivery note number — whatever belongs on the row.
     * @returns A promise resolving with the counters after the delivery.
     */
    const receive = (productId: string, quantity: number, note?: string) =>
        fetchAny(() =>
            receiveStock({ productId, quantity, note }).then((response) =>
                reloadAfterWrite(response.data)
            )
        );

    /**
     * Corrects the count after a stocktake, then reloads what it changed.
     *
     * @param productId - The product being corrected.
     * @param delta - Signed: negative for shrinkage, which is the common case.
     * @param note - Why. An unexplained correction is the thing an audit is looking for.
     * @returns A promise resolving with the counters after the correction.
     */
    const adjust = (productId: string, delta: number, note?: string) =>
        fetchAny(() =>
            adjustStock({ productId, delta, note }).then((response) =>
                reloadAfterWrite(response.data)
            )
        );

    /**
     * Expires every stale reservation, then reloads both views — released holds moved `reserved`.
     *
     * @returns A promise resolving with how many holds this run released.
     */
    const sweep = () =>
        fetchAny(() =>
            sweepReservations().then((response) =>
                fetchMovements()
                    .then(() => fetchLevels())
                    .then(() => response.data.expired)
            )
        );

    /**
     * Both counter writes change the same two things, so they refresh the same two things.
     *
     * Sequential rather than concurrent: the ledger explains the board, and a board that arrived
     * before the movement that justifies it reads as a number nobody wrote.
     *
     * @param level - The counters the write answered with.
     * @returns A promise resolving with those counters, once the views agree with them.
     */
    const reloadAfterWrite = (level: InventoryLevel | undefined) =>
        fetchMovements()
            .then(() => fetchLevels())
            .then(() => level);

    return {
        loading,
        movements,
        movementsTotal,
        levels,
        levelsTotal,
        fetchMovements,
        fetchLevels,
        receive,
        adjust,
        sweep
    };
});

src/modules/locales/composables/use-dict.source:
/**
 * @module
 * Composable owning the dictionary board's three-source read model: entries, the API baseline,
 * the bundled baseline and pending keys, merged into per-cell lookups the board and the cell
 * editor both read through rather than touching the sources directly.
 */
import { computed, ref, type Ref } from 'vue';
import { storeToRefs } from 'pinia';
import { useNotificationsStore } from '@guebbit/vue-toolkit';
import { useLocalesStore } from '@/modules/locales/store.ts';
import { updateLocale as applyDictionary } from '@/infrastructure/i18n';
import { fetchLocaleOverrides } from '@/infrastructure/i18n/locale-overrides.ts';
import { notifyErrorMessages } from '@/infrastructure/utils/errors.ts';
import { LocaleTenantKind } from '@types';
import type { LocaleEntry } from '@types';

/**
 * Refreshes the running app's copy of one language after a write, so the edit is visible now.
 *
 * Resolves regardless: the board's own state is already correct, and the live refresh is a
 * courtesy that must never turn a saved edit into an error toast.
 */
const applyLiveOverrides = (tag: string) =>
    fetchLocaleOverrides(tag)
        .then((messages) => applyDictionary(tag, messages))
        .catch(() => undefined);

/**
 * The dictionary board's three-source aggregation: stored entries, the API's deployed baseline,
 * this build's bundled baseline, and keys added on the page but not yet backed by an entry
 * anywhere. Every other concern on the board — filtering, pagination, per-cell writes — asks a
 * cell's state through this rather than reading the three sources directly, so "what is this
 * cell" has exactly one answer regardless of who is asking.
 *
 * @param tenant - Whose dictionary is on the board; a key lives in exactly one tenant. Owned by
 *  the caller, not here — switching it is a page-level action with page-level side effects
 *  (resetting the current page, drafts) beyond what this aggregation is responsible for.
 */
export function useDictionaryAggregation(tenant: Ref<string>) {
    const { addMessage } = useNotificationsStore();
    const localesStore = useLocalesStore();
    const { capabilities, tenants, loading } = storeToRefs(localesStore);

    /**
     * What kind of tenant is on the board — decides which baseline, if any, the cells show.
     */
    const tenantKind = computed(
        () => tenants.value.find(({ id }) => id === tenant.value)?.kind ?? LocaleTenantKind.frontend
    );

    /**
     * Whether the shown tenant has a baseline this build can read: its own bundle, or the API's files.
     */
    const hasBaseline = computed(
        () =>
            tenant.value === localesStore.ownTenant || tenantKind.value === LocaleTenantKind.backend
    );

    /**
     * Languages the board can write to: the ones with a dynamic record behind them.
     *
     * A `static`-only language exists as deployed files alone; there is no entries collection to put
     * a cell into, so it is not a column.
     */
    const languages = computed(() =>
        capabilities.value.filter((language) => language.source !== 'static')
    );

    /**
     * The tenant select's options, from the registry.
     */
    const tenantOptions = computed(() =>
        tenants.value.map(({ id, label }) => ({ value: id, title: `${label} (${id})` }))
    );

    /**
     * Every entry of every language, every tenant, by language tag.
     */
    const entriesByTag = ref<Partial<Record<string, LocaleEntry[]>>>({});

    /**
     * The API's deployed dictionary by language tag — the backend tenant's baseline.
     */
    const apiBaselines = ref<Partial<Record<string, Partial<Record<string, string>>>>>({});

    /**
     * This build's bundled dictionary by language tag — its own tenant's baseline.
     */
    const appBaselines = ref<Partial<Record<string, Partial<Record<string, string>>>>>({});

    /**
     * Keys added on this page that have no entry in any language yet.
     */
    const pendingKeys = ref<string[]>([]);

    /**
     * One language's entries of the shown tenant, by key.
     */
    const entriesIndex = computed(() => {
        const index: Partial<Record<string, Map<string, LocaleEntry>>> = {};
        for (const [tag, entries] of Object.entries(entriesByTag.value))
            index[tag] = new Map(
                (entries ?? [])
                    .filter((entry) => entry.tenant === tenant.value)
                    .map((entry) => [entry.key, entry])
            );
        return index;
    });

    /**
     * The shown tenant's baselines, by language tag — none for a tenant this build cannot read.
     */
    const baselines = computed<Partial<Record<string, Partial<Record<string, string>>>>>(() => {
        if (tenant.value === localesStore.ownTenant) return appBaselines.value;
        if (tenantKind.value === LocaleTenantKind.backend) return apiBaselines.value;
        return {};
    });

    /**
     * The stored entry for one cell, when there is one.
     */
    const entryAt = (tag: string, key: string): LocaleEntry | undefined =>
        entriesIndex.value[tag]?.get(key);

    /**
     * The baseline text for one cell, when the shown tenant has one.
     */
    const baselineAt = (tag: string, key: string): string | undefined =>
        baselines.value[tag]?.[key];

    /**
     * A cell with neither an entry nor a baseline: the gap the board exists to show.
     */
    const isMissing = (tag: string, key: string) =>
        entryAt(tag, key) === undefined && baselineAt(tag, key) === undefined;

    /**
     * The cell's state, for its look and its title.
     */
    const cellState = (tag: string, key: string): 'entry' | 'baseline' | 'missing' => {
        if (entryAt(tag, key)) return 'entry';
        return baselineAt(tag, key) === undefined ? 'missing' : 'baseline';
    };

    /**
     * Every key on the board: the union, across languages, of the shown tenant's baseline keys and
     * entry keys, plus what was added here and not yet saved anywhere, sorted so related keys sit
     * together.
     */
    const allKeys = computed(() => {
        const keys = new Set<string>(pendingKeys.value);
        for (const index of Object.values(entriesIndex.value))
            for (const key of index?.keys() ?? []) keys.add(key);
        for (const baseline of Object.values(baselines.value))
            for (const key of Object.keys(baseline ?? {})) keys.add(key);
        return [...keys].toSorted();
    });

    /**
     * Per language: how many of the board's keys it is missing.
     */
    const missingByTag = computed<Partial<Record<string, number>>>(() =>
        Object.fromEntries(
            languages.value.map((language) => [
                language.tag,
                allKeys.value.filter((key) => isMissing(language.tag, key)).length
            ])
        )
    );

    /**
     * Reloads one language's column: its rows and both baselines.
     */
    const loadLanguage = (tag: string) =>
        Promise.all([
            localesStore.fetchAllEntries(tag),
            localesStore.fetchApiDictionary(tag),
            localesStore.fetchBundledDictionary(tag)
        ]).then(([entries, apiBaseline, appBaseline]) => {
            entriesByTag.value[tag] = entries ?? [];
            apiBaselines.value[tag] = apiBaseline;
            appBaselines.value[tag] = appBaseline;
        });

    /**
     * Loads the registry and the manifest, then every writable language's column.
     */
    const loadBoard = () =>
        Promise.all([localesStore.fetchTenants(), localesStore.fetchLanguages()])
            .then(() => Promise.all(languages.value.map((language) => loadLanguage(language.tag))))
            .catch((error: unknown) => notifyErrorMessages(addMessage, error));

    /**
     * What every write does afterwards: the column, the manifest's counts, the running app.
     */
    const afterWrite = (tag: string) =>
        Promise.all([loadLanguage(tag), localesStore.fetchLanguages(), applyLiveOverrides(tag)]);

    /**
     * Records a key added here, not yet backed by an entry anywhere — see `allKeys`.
     */
    const addPendingKey = (key: string) => {
        pendingKeys.value.push(key);
    };

    /**
     * Forgets this tenant's added-but-unsaved keys — a tenant switch is a different board.
     */
    const resetPendingKeys = () => {
        pendingKeys.value = [];
    };

    return {
        loading,
        tenantKind,
        hasBaseline,
        languages,
        tenantOptions,
        allKeys,
        missingByTag,
        entryAt,
        baselineAt,
        isMissing,
        cellState,
        loadBoard,
        loadLanguage,
        afterWrite,
        addPendingKey,
        resetPendingKeys
    };
}

/**
 * @module
 * Composable owning per-cell writes on the dictionary board: a local draft keyed by `cellId` so a
 * blur can tell "changed" from "clicked through", the save/clear/enter handlers that call into the
 * locales store, and the transient saved-mark/error state each cell shows for its own last write.
 */
import { ref, type Ref } from 'vue';
import { useI18n } from 'vue-i18n';
import { omit } from 'lodash-es';
import { useNotificationsStore } from '@guebbit/vue-toolkit';
import { useDialogStore } from '@/ui/dialog.ts';
import { useLocalesStore } from '@/modules/locales/store.ts';
import { notifyErrorMessages } from '@/infrastructure/utils/errors.ts';
import type { LocaleCapability, LocaleEntry } from '@types';

/**
 * How long the "saved" mark stays on a cell, in milliseconds.
 */
const SAVED_MARK_MS = 1500;

/**
 * The cell's draft key: tag and key joined by a separator no BCP 47 tag can contain.
 */
const cellId = (tag: string, key: string) => `${tag}|${key}`;

/**
 * Per-cell writes on the dictionary board: the draft that lets a blur tell "changed" from
 * "clicked through", the save/clear/enter handlers, and the transient saved-mark and error state
 * a cell shows for its own last write.
 *
 * @param tenant - Whose dictionary a NEW entry is created in; an edit or removal targets the
 *  entry's own id instead and never reads this.
 * @param entryAt - The aggregation's current entry lookup, so a write reads the record it is
 *  about to replace rather than a stale one.
 * @param baselineAt - The aggregation's current baseline lookup, for the cell's accessible label.
 * @param afterWrite - What runs once a write settles: reload the column, the manifest, the live app.
 */
export function useDictionaryCellEditor(
    tenant: Ref<string>,
    entryAt: (tag: string, key: string) => LocaleEntry | undefined,
    baselineAt: (tag: string, key: string) => string | undefined,
    afterWrite: (tag: string) => Promise<unknown>
) {
    const { t } = useI18n();
    const { addMessage } = useNotificationsStore();
    const dialogStore = useDialogStore();
    const localesStore = useLocalesStore();

    /**
     * Local draft per cell, so a blur can tell "changed" from "clicked through".
     */
    const drafts = ref<Partial<Record<string, string>>>({});

    /**
     * Cells whose last save just landed; the check mark inside the field, cleared after a beat.
     */
    const savedCells = ref<Partial<Record<string, true>>>({});

    /**
     * Cells whose last write failed; the message stays under the field until the cell is edited.
     */
    const cellErrors = ref<Partial<Record<string, string>>>({});

    /**
     * The board's element, so a new row's cell can be found and focused without a global query.
     */
    const boardElement = ref<HTMLElement>();

    /**
     * Drops one cell's draft, so the cell reads the stored value again.
     */
    const forgetDraft = (id: string) => {
        drafts.value = omit(drafts.value, id);
    };

    /**
     * Drops one cell's error, so a fresh attempt starts clean.
     */
    const forgetError = (id: string) => {
        cellErrors.value = omit(cellErrors.value, id);
    };

    /**
     * Shows the saved mark on one cell, then takes it away.
     */
    const markSaved = (id: string) => {
        savedCells.value = { ...savedCells.value, [id]: true };
        setTimeout(() => {
            savedCells.value = omit(savedCells.value, id);
        }, SAVED_MARK_MS);
    };

    /**
     * The `<input>` a cell event came from, whether the key landed on it or its clear button.
     */
    const inputOf = (event: Event): HTMLElement | null =>
        (event.target as HTMLElement | null)?.closest('.v-field')?.querySelector('input') ?? null;

    /**
     * What every cell write ends with: the draft gone, the column reloaded, a failure on the cell.
     */
    const settleWrite = (language: LocaleCapability, id: string, request: Promise<unknown>) =>
        request
            .then(() => {
                forgetDraft(id);
                return afterWrite(language.tag);
            })
            .catch((error: unknown) => {
                // On the cell as well as the toast: the toast is gone in seconds, the cell is not.
                cellErrors.value = {
                    ...cellErrors.value,
                    [id]: t('locales-dictionary-page.error-save')
                };
                notifyErrorMessages(addMessage, error);
            });

    /**
     * Saves one cell on blur — if it actually changed.
     *
     * Two of the three outcomes live here, decided by what the cell held and what it holds now: a new
     * value over an empty cell CREATES the entry, a different value EDITS it. The third — an emptied
     * cell REMOVING its entry — is {@link handleCellClear}, and it is deliberately NOT reached from a
     * blur: a confirmation that opens because focus moved on is a dialog nobody asked for, and it
     * steals the focus it then has to give back. An emptied cell left by blur just reads its stored
     * value again.
     *
     * @param language - The column.
     * @param key - The row.
     * @returns Nothing; success is shown on the cell, failure on the cell and as a toast.
     */
    const handleCellBlur = (language: LocaleCapability, key: string) => {
        const id = cellId(language.tag, key);
        const draft = drafts.value[id];
        const current = entryAt(language.tag, key);
        if (draft === undefined || draft === (current?.value ?? '')) return;
        if (draft === '') {
            forgetDraft(id);
            return;
        }
        const request = current
            ? localesStore.editEntry(language.tag, current.id, draft)
            : localesStore.addEntry(language.tag, { tenant: tenant.value, key, value: draft });
        return settleWrite(
            language,
            id,
            request.then(() => markSaved(id))
        );
    };

    /**
     * Removes one cell's entry, on an explicit action: Enter on an emptied cell, or the clear button.
     *
     * Confirmed first, because an accidental select-all-and-delete must cost a click, not a
     * translation. A cancel puts the stored value and the focus back where they were. Removing an
     * entry uncovers the baseline again; it never deletes the bundled text.
     *
     * @param language - The column.
     * @param key - The row.
     * @param event - The keystroke or click, so a cancel can focus the cell it came from.
     * @returns Nothing; the outcome is reported as a toast naming the cell.
     */
    const handleCellClear = (language: LocaleCapability, key: string, event: Event) => {
        const id = cellId(language.tag, key);
        const current = entryAt(language.tag, key);
        if (!current) {
            forgetDraft(id);
            return;
        }
        const origin = inputOf(event);
        return dialogStore
            .confirm({
                message: t('locales-dictionary-page.confirm-clear', {
                    key,
                    language: language.nativeName
                }),
                color: 'error'
            })
            .then((accepted) => {
                if (!accepted) {
                    forgetDraft(id);
                    origin?.focus();
                    return;
                }
                return settleWrite(
                    language,
                    id,
                    localesStore.removeEntry(language.tag, current.id).then(() =>
                        addMessage(
                            t('locales-dictionary-page.success-remove-named', {
                                key,
                                language: language.nativeName
                            })
                        )
                    )
                );
            });
    };

    /**
     * Enter on a cell: a removal when the cell was emptied, a save otherwise — the same save a blur
     * would do, one keystroke sooner.
     */
    const handleCellEnter = (language: LocaleCapability, key: string, event: Event) => {
        const draft = drafts.value[cellId(language.tag, key)];
        return draft === '' ? handleCellClear(language, key, event) : handleCellBlur(language, key);
    };

    /**
     * Records a keystroke in the cell's draft; a cell being typed into is no longer in error.
     */
    const handleCellInput = (language: LocaleCapability, key: string, draft: string) => {
        const id = cellId(language.tag, key);
        drafts.value[id] = draft;
        if (cellErrors.value[id]) forgetError(id);
    };

    /**
     * The cell's accessible name: the key, the language, and the baseline it would be replacing.
     */
    const cellLabel = (language: LocaleCapability, key: string) => {
        const baseline = baselineAt(language.tag, key);
        return baseline === undefined || entryAt(language.tag, key)
            ? t('locales-dictionary-page.cell-label', { key, language: language.nativeName })
            : t('locales-dictionary-page.cell-label-baseline', {
                  key,
                  language: language.nativeName,
                  baseline
              });
    };

    return {
        drafts,
        savedCells,
        cellErrors,
        boardElement,
        cellId,
        handleCellBlur,
        handleCellClear,
        handleCellEnter,
        handleCellInput,
        cellLabel
    };
}

