/**
 * @module
 * Pinia store implementing `globalThis.confirm()` as an async, themeable, queued promise: callers
 * push a request and await the resolution; `DialogHost` renders the queue's head and answers it.
 */

import { ref } from 'vue';
import { defineStore } from 'pinia';

/**
 * What a confirmation asks, and how it is dressed.
 *
 * Copy only — every string arrives already translated, because this store is design-system code
 * and owns no dictionary. The caller has `t()`; the store has a promise.
 */
export interface DialogRequest {
    /**
     * Optional heading. Omitted, the message stands alone.
     */
    title?: string;
    /**
     * The question. Required: a confirmation with nothing to confirm is a bug.
     */
    message: string;
    /**
     * Label of the button that resolves `true`. The host falls back to its generic label.
     */
    confirmLabel?: string;
    /**
     * Label of the button that resolves `false`. The host falls back to its generic label.
     */
    cancelLabel?: string;
    /**
     * Colour of the confirming button — `error` for a destructive action, the default otherwise.
     */
    color?: 'primary' | 'error' | 'warning';
}

/**
 * One pending question: what was asked, plus how to answer it.
 */
export interface DialogEntry extends DialogRequest {
    /**
     * Monotonically increasing id, oldest-first ordering key.
     */
    id: number;
    /**
     * Settles the caller's promise with the viewer's answer.
     */
    resolve: (answer: boolean) => void;
}

/**
 * The app's one modal confirmation, as a promise.
 *
 * `globalThis.confirm()` is synchronous, un-themed, unreachable by the design tokens and the
 * translation tier, and it blocks the event loop — a half-typed cell loses its focus behind it.
 * This is the same contract made asynchronous: `confirm(request)` resolves `true` when the viewer
 * accepts and `false` when they decline, close the dialog, or press Escape — so a caller writes
 * `.then((accepted) => { if (!accepted) return; ... })` and nothing else changes.
 *
 * Questions QUEUE rather than replace: two components asking at once — a row delete racing a
 * navigation guard — each get their answer in order, and neither resolves on the other's click.
 *
 * The rendering lives in `ui/organisms/DialogHost.vue`, mounted once by the layout. This
 * store neither imports Vuetify nor knows what a dialog looks like; it holds the queue and the
 * promises, which is what makes it testable in jsdom without a component tree.
 */
export const useDialogStore = defineStore('dialog', () => {
    /**
     * Pending questions, oldest first. The host renders the first one.
     */
    const queue = ref<DialogEntry[]>([]);

    /**
     * Source of {@link DialogEntry.id}; increments once per {@link confirm} call.
     */
    let nextId = 1;

    /**
     * Asks the viewer. Resolves with their answer once they give one.
     *
     * @param request - What to ask, already translated.
     * @returns A promise resolving `true` on accept, `false` on decline or dismiss. Never rejects.
     */
    const confirm = (request: DialogRequest): Promise<boolean> =>
        new Promise<boolean>((resolve) => {
            queue.value.push({ ...request, id: nextId++, resolve });
        });

    /**
     * Answers the question at the front of the queue. Called by the host, once per click.
     *
     * @param answer - `true` for the confirming button, `false` for anything else.
     */
    const answer = (answer: boolean) => {
        const entry = queue.value.shift();
        entry?.resolve(answer);
    };

    return { queue, confirm, answer };
});

tests/unit/app/router/router.spec.ts.source:
/**
 * Router wiring.
 *
 * `tests/unit/app/guards/authentications.spec.ts` proves `canAccess` decides correctly. This
 * proves the enforcement is actually *attached*, and that every route declares the requirement it
 * should — a route that quietly loses its `meta.access` is indistinguishable from a public one.
 *
 * Enforcement is therefore mocked here: what is under test is the router's own behaviour (the
 * locale redirect, the 404 catch-alls, the global auth restore, the error → redirect mapping) and
 * the declarations on the route records.
 */
import { afterEach, beforeAll, beforeEach, describe, expect, it, vi } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';
import { signInLocation } from '@/app/router/navigation.ts';

const tryRestoreAuth = vi.fn(() => Promise.resolve());
// Returns nothing, i.e. "let the navigation through".
const enforceRouteAccess = vi.fn();

vi.mock('@/app/guards/authentications.ts', () => ({
    tryRestoreAuth: () => tryRestoreAuth(),
    enforceRouteAccess: (to: unknown) => enforceRouteAccess(to)
}));

vi.mock('@/infrastructure/observability/store.ts', () => ({
    useObservabilityStore: () => ({ captureException: vi.fn() })
}));

/** Fresh router per test: it holds navigation state, and history is global. */
const loadRouter = () => {
    vi.resetModules();
    return import('@/app/router').then(({ default: router }) =>
        router
            .push('/')
            .then(() => router.isReady())
            .then(() => router)
    );
};

/**
 * Pay for the router's module graph once, outside any test's budget.
 *
 * `@/app/router` pulls in every view, and therefore Vuetify — the most expensive import in the suite.
 * `vi.resetModules()` in `loadRouter` clears the module registry but NOT Vite's transform cache,
 * so only the first import in this file actually transpiles anything; the rest are cheap.
 *
 * Left inside the first test, that one-off cost is charged to it, and under `--coverage` the
 * added instrumentation pushed it past the 5s default — a test that passed alone, passed in
 * `test:unit`, and failed only in `test:unit:coverage`. Warming it here keeps every real case on
 * the tight default budget, which is where a genuine hang should still be caught.
 */
beforeAll(async () => {
    await import('@/app/router');
}, 60_000);

beforeEach(() => {
    setActivePinia(createPinia());
    vi.clearAllMocks();
    globalThis.history.replaceState({}, '', '/');
});

afterEach(() => {
    vi.unstubAllEnvs();
});

/**
 * The tab title and the route announcer (WCAG 2.4.2 / 4.1.3), both written by the same
 * `afterEach` from the route's `meta.title`.
 *
 * `Home` is the platform's own route and its key is in the shared dictionary, so the assertion
 * is on a TRANSLATED title. `Playground` is a module route whose dictionary is not registered
 * here, so its key comes back as itself — which still proves the record carries one.
 */
describe('document title and announcer', () => {
    it('sets the tab title to the page title and the app name', () =>
        loadRouter().then(() => {
            expect(document.title).toBe('Home — Guebbit');
        }));

    it('reads the app name from VITE_APP_NAME', () => {
        vi.stubEnv('VITE_APP_NAME', 'Acme Shop');
        return loadRouter().then(() => {
            expect(document.title).toBe('Home — Acme Shop');
        });
    });

    it('follows the route', () =>
        loadRouter().then((router) =>
            router.push('/en/playground').then(() => {
                expect(document.title).toBe('playground-page.page-title — Guebbit');
            })
        ));

    it('tells the announcer the same title', () =>
        loadRouter().then((router) =>
            import('@/app/router/announcer.ts').then(({ routeAnnouncement }) =>
                router.push('/en/playground').then(() => {
                    expect(routeAnnouncement.value).toBe('playground-page.page-title');
                })
            )
        ));

    /**
     * Every route that renders a page declares a title. The shell's own records are the ones
     * a platform spec may name; each module pins its own in `src/modules/<name>/tests/routes.spec.ts`.
     */
    it.each(['Home', 'StaticAbout', 'StaticFaq', 'StaticTerms', 'StaticPrivacy', 'Error'])(
        'declares a title on the %s route',
        (name) =>
            loadRouter().then((router) => {
                expect(
                    router.resolve({ name, params: { locale: 'en', status: '404' } }).meta.title
                ).toBeTruthy();
            })
    );
});

describe('locale handling', () => {
    it('redirects the bare root to the locale-prefixed home', () =>
        loadRouter().then((router) => {
            expect(router.currentRoute.value.name).toBe('Home');
            expect(router.currentRoute.value.params.locale).toBeTruthy();
        }));
});

describe('unknown routes', () => {
    it('sends an unknown path under a locale to the 404 error page, keeping the locale', () =>
        loadRouter().then((router) =>
            router.push('/en/this-does-not-exist').then(() => {
                expect(router.currentRoute.value.name).toBe('Error');
                expect(router.currentRoute.value.params.status).toBe('404');
                expect(router.currentRoute.value.params.locale).toBe('en');
            })
        ));

    // A single unknown segment is indistinguishable from a locale: `/:locale` matches it, the
    // empty child matches the rest, and `localeChoice` then rewrites the unsupported locale to
    // the default one. So `/nonsense` lands on Home, not on the 404 page — the top-level
    // `/:catchAll(.*)` route is only reachable for paths that cannot be read as a locale at all.
    // Asserted here so the behaviour is a decision on record rather than a surprise.
    it('treats a single unknown segment as a locale and lands on home', () =>
        loadRouter().then((router) =>
            router.push('/nonsense').then(() => {
                expect(router.currentRoute.value.name).toBe('Home');
                expect(router.currentRoute.value.params.locale).not.toBe('nonsense');
            })
        ));

    /**
     * A deep unknown path is caught by the LOCALE-scoped catch-all, not the top-level one.
     *
     * `/:locale` matches a single segment, so `/a/b/c` reads as locale `a` with `b/c` left for
     * the children — where `:catchAll(.*)` takes it. Together with the case above, this is what
     * makes the top-level `/:catchAll(.*)` route unreachable: every path is either `/`, or has a
     * first segment that `/:locale` accepts.
     *
     * Recorded rather than deleted, because "unreachable" is a claim about the route table that
     * only holds while `/:locale` stays a single-segment param — and this test is what would fail
     * if that changed.
     */
    it('sends a deep unknown path to the locale-scoped 404', () =>
        loadRouter().then((router) =>
            router.push('/en/nope/nope/nope').then(() => {
                expect(router.currentRoute.value.name).toBe('Error');
                expect(router.currentRoute.value.params.status).toBe('404');
                expect(router.currentRoute.value.params.message).toBe('error-page.not-found');
                expect(router.currentRoute.value.params.locale).toBe('en');
            })
        ));
});

/**
 * The shop's prose pages — four route records, four components, one naming formula.
 *
 * Worth pinning because the NAME is computed (`'Static' + page[0].toUpperCase() + page.slice(1)`)
 * and every navigation to these pages is by name. An off-by-one in that expression produces
 * `StaticAbout` → `Staticbout`, which TypeScript cannot see and which fails only as a dead link.
 */
describe('static prose pages', () => {
    it.each([
        ['about', 'StaticAbout'],
        ['faq', 'StaticFaq']
    ])('serves /%s as the route named %s', (page, name) =>
        loadRouter().then((router) =>
            router.push(`/en/${page}`).then(() => {
                expect(router.currentRoute.value.name).toBe(name);
            })
        )
    );

    it.each([
        ['terms', 'StaticTerms'],
        ['privacy', 'StaticPrivacy']
    ])('serves /%s as the route named %s, with its own component', (page, name) =>
        loadRouter().then((router) =>
            router.push(`/en/${page}`).then(() => {
                expect(router.currentRoute.value.name).toBe(name);
            })
        )
    );
});

describe('global auth restore', () => {
    it('runs on the initial navigation', () =>
        loadRouter().then(() => {
            expect(tryRestoreAuth).toHaveBeenCalled();
        }));

    it('runs again on every subsequent navigation', () =>
        loadRouter().then((router) => {
            const callsAfterBoot = tryRestoreAuth.mock.calls.length;

            return router.push('/en/playground').then(() => {
                expect(tryRestoreAuth.mock.calls.length).toBeGreaterThan(callsAfterBoot);
            });
        }));
});

describe('access enforcement', () => {
    it('runs on every navigation, public routes included', () =>
        loadRouter().then((router) =>
            router.push('/en/playground').then(() => {
                // Enforcement is global, so it is reached even where it has nothing to enforce.
                // That is the point: a route cannot opt out of being checked by omission.
                expect(enforceRouteAccess).toHaveBeenCalled();
            })
        ));

    it('runs only after the auth restore has settled', () =>
        loadRouter().then((router) => {
            const order: string[] = [];
            tryRestoreAuth.mockImplementationOnce(() =>
                Promise.resolve().then(() => {
                    order.push('restore');
                })
            );
            enforceRouteAccess.mockImplementationOnce(() => {
                order.push('enforce');
            });

            // Reversed, an authenticated visitor who reloads is bounced to login on every hit.
            return router.push('/en/playground').then(() => {
                expect(order).toEqual(['restore', 'enforce']);
            });
        }));

    /*
     * The per-route access DECLARATIONS moved to `src/modules/<name>/tests/routes.spec.ts`.
     *
     * They were a table of domain paths here, which meant deleting a domain broke a platform
     * spec about the router shell. What belongs at this level is that enforcement is attached
     * and correctly ordered — asserted above using the two routes the shell owns itself.
     */
});

/**
 * Pushes a route whose guard throws the given error, then lets `onError`'s redirect settle.
 *
 * Waits for the router to actually leave the starting route rather than for a fixed number of
 * ticks: `onError` handles the failure and issues a *second* navigation, which has its own guard
 * chain to run, so how many microtasks that takes is an implementation detail of the guards.
 */
const failNavigationWith = (error: Error) =>
    loadRouter().then((router) =>
        /*
         * Settle somewhere that is NOT Home before failing anything.
         *
         * The wait below is "did we leave `before`", and one of the redirect targets — the 401
         * fallback when this build ships no sign-in route — IS Home. Starting on Home made a
         * correct redirect indistinguishable from no redirect at all, and the helper reported
         * `still on /en` for behaviour that was right.
         */
        router.push('/en/playground').then(() => {
            const before = router.currentRoute.value.fullPath;
            enforceRouteAccess.mockImplementationOnce(() => {
                throw error;
            });
            return router
                .push('/en')
                .catch(() => {})
                .then(() =>
                    // A thrown Error rather than `expect`, so this reads as a wait condition in a
                    // helper rather than as an assertion outside a test block.
                    vi.waitFor(() => {
                        if (router.currentRoute.value.fullPath === before)
                            throw new Error(`still on ${before}`);
                    })
                )
                .then(() => router);
        })
    );

describe('onError redirects', () => {
    it('sends a 401 to the sign-in page, remembering where the user was going', () =>
        failNavigationWith(Object.assign(new Error('nope'), { status: 401 })).then((router) => {
            /*
             * Which route that is belongs to whichever module provides sign-in, so the expectation
             * is computed from `signInLocation` rather than spelled `'Login'` here. What this pins
             * is the WIRING — that a 401 goes through that helper at all — while
             * `navigation.spec.ts` covers both of the helper's own branches directly.
             */
            expect(router.currentRoute.value.name).toBe(
                signInLocation(router, '/en/playground', 'en').name
            );
            // The point of the 401 branch: a recoverable status must not dead-end on the error
            // page, which is where every other status goes.
            expect(router.currentRoute.value.name).not.toBe('Error');
        }));

    it('sends a 403 to the forbidden error page', () =>
        failNavigationWith(Object.assign(new Error('nope'), { status: 403 })).then((router) => {
            expect(router.currentRoute.value.name).toBe('Error');
            expect(router.currentRoute.value.params.status).toBe('403');
            // The reason 403 keeps a branch of its own: "you may not see this" is a different
            // thing to tell someone than whatever `error.message` happened to hold ('nope').
            expect(router.currentRoute.value.params.message).toBe('navigation.error-forbidden');
        }));

    it('shows the error’s own message for other client statuses', () =>
        failNavigationWith(Object.assign(new Error('teapot'), { status: 418 })).then((router) => {
            expect(router.currentRoute.value.params.status).toBe('418');
            expect(router.currentRoute.value.params.message).toBe('teapot');
        }));

    it('collapses a 5xx status to a plain 500', () =>
        /*
         * The `status !== undefined && status < 500` guard needs a DEFINED status at or above 500 to
         * be meaningful: with an absent one both halves are false either way, so 401/403/418 and the
         * no-status case together still cannot tell `&&` from `||`, nor a fixed `true` from the real
         * condition. A 503 is the case that does.
         *
         * Collapsing is deliberate — the flavour of a server-side failure is not the visitor's
         * business, and the error page has one 500 screen.
         */
        failNavigationWith(Object.assign(new Error('gateway'), { status: 503 })).then((router) => {
            expect(router.currentRoute.value.params.status).toBe('500');
        }));

    it('treats an error with no status as a 500', () =>
        failNavigationWith(new Error('boom')).then((router) => {
            expect(router.currentRoute.value.name).toBe('Error');
            expect(router.currentRoute.value.params.status).toBe('500');
        }));
});

/**
 * Navigation tracing, which `utils/logger.ts` gates on the `router` scope.
 *
 * The logger resolves its level and scopes once at module scope, so the environment has to be
 * stubbed BEFORE the import — which is why these cases load the router themselves rather than
 * reusing `loadRouter`.
 *
 * Both directions are asserted. A trace that never appears when asked for is as wrong as one that
 * appears when it was not, and only the second is visible by accident.
 */
/** Loads a fresh router with the log scopes stubbed BEFORE import, since they are read once there. */
const loadRouterWithDebug = (enabled: boolean) => {
    vi.resetModules();
    vi.stubEnv('DEV', true);
    vi.stubEnv('VITE_APP_LOG_LEVEL', 'debug');
    vi.stubEnv('VITE_APP_LOG_SCOPES', enabled ? 'router' : '');
    return import('@/app/router').then(({ default: router }) =>
        router
            .push('/')
            .then(() => router.isReady())
            .then(() => router)
    );
};

/** Every argument of every recorded call, flattened, so a prefixed message still matches. */
const debugText = (spy: { mock: { calls: unknown[][] } }) =>
    spy.mock.calls.map((call) => call.map(String).join(' ')).join('\n');

describe('router navigation tracing', () => {
    it('logs each navigation when the router scope is on', () => {
        const debugSpy = vi.spyOn(console, 'debug').mockImplementation(() => {});

        return loadRouterWithDebug(true)
            .then((router) => router.push('/en/playground'))
            .then(() => {
                // The logger prefixes its own scope, so the assertion is on the whole line rather
                // than on the first argument.
                expect(debugText(debugSpy)).toContain('[router]');
                expect(debugText(debugSpy)).toContain('Navigating');
                debugSpy.mockRestore();
            });
    });

    it('stays silent when the router scope is off', () => {
        const debugSpy = vi.spyOn(console, 'debug').mockImplementation(() => {});

        return loadRouterWithDebug(false)
            .then((router) => router.push('/en/playground'))
            .then(() => {
                // Scoped to the navigation line rather than asserting console silence outright:
                // other modules may log on boot, and a blanket assertion would fail for reasons
                // that say nothing about the router.
                expect(debugText(debugSpy)).not.toContain('Navigating');
                debugSpy.mockRestore();
            });
    });

    it('reports a navigation failure when the router scope is on', () => {
        const debugSpy = vi.spyOn(console, 'debug').mockImplementation(() => {});

        return loadRouterWithDebug(true)
            .then((router) => {
                enforceRouteAccess.mockImplementationOnce(() => {
                    throw new Error('boom');
                });
                return router.push('/en/playground').catch(() => router);
            })
            .then(() =>
                vi.waitFor(() => {
                    if (!debugText(debugSpy).includes('page error'))
                        throw new Error('no page error trace yet');
                })
            )
            .then(() => {
                expect(debugText(debugSpy)).toContain('page error');
                debugSpy.mockRestore();
            });
    });
});

tests/cross-cutting/registry.spec.ts.source:
/**
 * Invariants every enabled module must satisfy, whichever modules those are.
 *
 * This is the shape a cross-cutting spec is allowed to take: it **iterates** the registry and
 * never **names** a domain. Delete `products` and this file keeps passing, testing one module
 * fewer — which is exactly what `docs/theory/modules.md` asks of a spec that lives outside a
 * module.
 *
 * The property is "every menu entry any module contributes points at a route that module
 * declares, and every route it declares is reachable" — not "products is in the menu and is
 * public". A hardcoded phrasing breaks when a domain is removed; this one does not.
 *
 * The failure it exists to catch is a silent one: a `navigation` entry naming a route that does
 * not exist renders a link that resolves to nothing. `vue-router` warns in the console and
 * carries on, so a human clicking around finds it and no gate does.
 */
import { describe, expect, it } from 'vitest';
import type { RouteRecordRaw } from 'vue-router';
import { enabledModules } from '@/modules';
import type { TranslationDictionaries } from '@/infrastructure/i18n';
import { NAVIGATION_SECTIONS } from '@/kernel/registry';

/** Every route name a record tree declares, at any depth. */
const routeNamesOf = (routes: RouteRecordRaw[]): string[] =>
    routes.flatMap((route) => [
        ...(typeof route.name === 'string' ? [route.name] : []),
        ...routeNamesOf(route.children ?? [])
    ]);

const moduleCases = enabledModules.map((appModule) => [appModule.name, appModule] as const);

describe('the enabled registry', () => {
    it('enables at least one module, so the sweeps below are not vacuously true', () => {
        expect(enabledModules.length).toBeGreaterThan(0);
    });
});

describe.each(moduleCases)('module %s', (_name, appModule) => {
    it('contributes navigation entries that point at routes it declares', () => {
        const declared = new Set(routeNamesOf(appModule.routes));

        for (const { name } of appModule.navigation ?? []) expect(declared).toContain(name);
    });

    it('gives every navigation entry an order, so it cannot silently sink to the bottom', () => {
        for (const entry of appModule.navigation ?? []) expect(entry.order).toBeTypeOf('number');
    });

    /**
     * Every place an entry renders leads with its glyph — the bar beside the label, the menus and
     * the drawer before it, a pinned entry as the glyph alone with its count. An entry without one
     * would render a blank slot where every neighbour has a picture.
     */
    it('gives every navigation entry an icon, because every surface leads with one', () => {
        for (const entry of appModule.navigation ?? []) expect(entry.icon).toBeDefined();
    });

    it('places every navigation entry in a section the shell knows how to draw', () => {
        // `undefined` is a valid answer: the shell reads it as `main`.
        for (const entry of appModule.navigation ?? [])
            expect([undefined, ...NAVIGATION_SECTIONS]).toContain(entry.section);
    });

    it('names every route it declares — the navigation and the guards address routes by name', () => {
        for (const route of appModule.routes) expect(typeof route.name).toBe('string');
    });
});

/**
 * Dictionary collisions.
 *
 * Nesting every key under its module (`products.list.page-title` rather than
 * `products-list-page.page-title`) would make a collision impossible by construction, but it
 * touches every `.vue` file and every JSON, and keys already carry a domain prefix by convention.
 * This catches the same failure at roughly none of the cost.
 *
 * The failure: dictionaries are DEEP-MERGED at boot, in registration order. If two modules declare
 * the same top-level key, the later one's entries win and the earlier one's copy vanishes. Nothing
 * throws. The page renders raw keys, and only a human reading the screen in that language notices.
 *
 * `navigation` is the deliberate exception — every module contributes its own `label-*` slice of
 * it, which is exactly why the merge has to be deep. So it is checked one level lower instead:
 * co-owning the namespace is fine, claiming the same entry inside it is not.
 */
const CO_OWNED_NAMESPACE = 'navigation';

/** Locale codes any enabled module ships, deduplicated. */
const localeCodes = [
    ...new Set(enabledModules.flatMap((appModule) => Object.keys(appModule.locales ?? {})))
];

/** Every contributor's dictionary for one locale, the shared one included, labelled by owner. */
const dictionariesFor = (
    locale: string
): Promise<{ owner: string; dictionary: TranslationDictionaries }[]> =>
    Promise.all([
        (import(`@/locales/${locale}.json`) as Promise<{ default: TranslationDictionaries }>).then(
            ({ default: dictionary }) => ({ owner: '<shared>', dictionary })
        ),
        ...enabledModules
            .filter((appModule) => appModule.locales?.[locale])
            .map((appModule) =>
                appModule.locales![locale]().then((dictionary) => ({
                    owner: appModule.name,
                    dictionary
                }))
            )
    ]);

/** key → the contributors that declare it, for anything declared more than once. */
const clashesIn = (entries: { owner: string; keys: string[] }[]): Record<string, string[]> => {
    const owners: Record<string, string[]> = {};

    for (const { owner, keys } of entries) for (const key of keys) (owners[key] ??= []).push(owner);

    return Object.fromEntries(
        Object.entries(owners).filter(([, contributors]) => contributors.length > 1)
    );
};

describe.each(localeCodes)('locale dictionaries — %s', (locale) => {
    it('gives every top-level namespace exactly one owner', () =>
        dictionariesFor(locale).then((loaded) => {
            const clashes = clashesIn(
                loaded.map(({ owner, dictionary }) => ({
                    owner,
                    keys: Object.keys(dictionary).filter((key) => key !== CO_OWNED_NAMESPACE)
                }))
            );

            // Named rather than counted: the message has to say WHICH namespace and WHO, or the
            // failure is a scavenger hunt through seven JSON files.
            expect(clashes).toEqual({});
        }));

    it(`gives every ${CO_OWNED_NAMESPACE} entry exactly one owner, though the namespace is shared`, () =>
        dictionariesFor(locale).then((loaded) => {
            const clashes = clashesIn(
                loaded.map(({ owner, dictionary }) => ({
                    owner,
                    keys: Object.keys(
                        (dictionary[CO_OWNED_NAMESPACE] as TranslationDictionaries | undefined) ??
                            {}
                    )
                }))
            );

            expect(clashes).toEqual({});
        }));

    it('is shipped by every module, so no domain is untranslated in this language', () => {
        const missing = enabledModules
            .filter((appModule) => appModule.locales && !appModule.locales[locale])
            .map(({ name }) => name);

        expect(missing).toEqual([]);
    });
});

