/**
 * @module
 * Mounts the real edit page against a real, memory-history router, proving `OrderEdit.vue` gains
 * `actions` the same way `Order.vue` does: a list-cache arrival — the orders list seeds the store
 * with a summary row carrying no `actions` — must not leave the page offering no moves. Same
 * template as `product-view.spec.ts`/`wishlist-view.spec.ts`: a real router over
 * `collectModuleRoutes(enabledModules)`, the store's own watch stubbed, and the forced re-fetch
 * `useOrderActionsRefetch` performs is exercised for real rather than pre-seeded away.
 *
 * `@/modules/payments` is mocked rather than imported past its barrel — `useOrderRefund` would
 * otherwise fire a real, unmocked HTTP call this suite has nothing to answer, and reaching its
 * store directly is exactly what `eslint-plugin-boundaries` forbids for a sibling module.
 */
import { describe, expect, it, beforeEach, vi } from 'vitest';
import { mount } from '@vue/test-utils';
import { createPinia, setActivePinia } from 'pinia';
import { createRouter, createMemoryHistory, RouterView } from 'vue-router';
import { ref, nextTick } from 'vue';
import OrderEdit from '@/modules/orders/views/OrderEdit.vue';
import { useOrdersStore } from '@/modules/orders/store.ts';
import { useSessionStore } from '@/infrastructure/session.ts';
import { i18n, loadLocale } from '@/infrastructure/i18n';
import vuetify from '@/ui/vuetify';
import { collectModuleRoutes } from '@/kernel/registry';
import { enabledModules } from '@/modules';
import { wireModulesIntoCore } from '../../../../tests/support/unit/wire-modules.ts';
import { OrderStatus } from '@types';
import type { Order } from '@types';

wireModulesIntoCore();

vi.mock('@/modules/payments', () => ({
    useOrderRefund: () => ({ canRefund: ref(false), refund: () => Promise.resolve() })
}));

/**
 * Satisfies `watchOrder`'s `WatchStopHandle` return type without setting up a real watcher.
 */
const noopStopHandle = () => undefined;

/**
 * The real app router, scoped to the modules this test suite enables.
 */
const router = createRouter({
    history: createMemoryHistory(),
    routes: [
        { path: '/:locale', component: RouterView, children: collectModuleRoutes(enabledModules) }
    ]
});

/**
 * A signed-in operator — `OrderEdit`'s route is `access: 'admin'` in the real router, though this
 * spec's bespoke router carries no guard to enforce it.
 */
const signInAsAdmin = () => {
    const session = useSessionStore();
    session.accessToken = 'test-token';
    session.viewer = { id: 'u1', email: 'operator@example.com', admin: true };
};

/**
 * A minimal order, everything but what each case overrides.
 */
const anOrder = (overrides: Partial<Order> = {}): Order => ({
    id: 'o1',
    userId: 'u1',
    email: 'shopper@example.com',
    items: [],
    totalItems: 0,
    totalQuantity: 0,
    totalPrice: 0,
    status: OrderStatus.pending,
    ...overrides
});

/**
 * Mounts the edit page exactly as a list-cache arrival would: the store already holds a SUMMARY
 * row for the id (no `actions`), and the stubbed `fetchOrder` answers what a real forced re-fetch
 * would — the DETAIL row `detailOrder` names. This exercises `useOrderActionsRefetch` for real
 * rather than seeding the answer directly, which is what would let the latch's own removal pass.
 *
 * @param detailOrder - The shape the forced re-fetch resolves to (carrying `actions`).
 * @returns The mounted wrapper.
 */
const mountFromListCache = (detailOrder: Order) => {
    const orders = useOrdersStore();
    vi.spyOn(orders, 'watchOrder').mockImplementation(() => noopStopHandle);
    orders.addOrder({ ...detailOrder, actions: undefined });
    orders.selectedOrderId = detailOrder.id;
    vi.spyOn(orders, 'fetchOrder').mockImplementation(() => {
        orders.addOrder(detailOrder);
        return Promise.resolve(detailOrder);
    });

    return mount(OrderEdit, {
        props: { id: detailOrder.id },
        global: {
            plugins: [router, vuetify, i18n],
            stubs: { LayoutDefault: { template: '<div><slot /></div>' } }
        }
    });
};

beforeEach(() => {
    setActivePinia(createPinia());
    return loadLocale('en').then(() =>
        router.push('/en/orders/o1/edit').then(() => router.isReady())
    );
});

describe('a list-cache arrival gains actions', () => {
    it('offers every reachable status once the forced re-fetch lands', () => {
        signInAsAdmin();
        const detail = anOrder({
            status: OrderStatus.shipped,
            actions: {
                transitions: [OrderStatus.delivered, OrderStatus.cancelled],
                cancel: true,
                pay: false
            }
        });

        const wrapper = mountFromListCache(detail);

        // The mount itself proves nothing yet — `actions` only lands once the forced re-fetch's
        // promise resolves and Vue re-renders on it.
        return nextTick()
            .then(() => nextTick())
            .then(() => {
                const select = wrapper.getComponent({ name: 'VSelect' });
                const values = (select.props('items') as { value: string }[]).map(
                    (item) => item.value
                );

                // Exactly the two reachable statuses plus the current one — never the full
                // six-value enum, which is what a select built from the bare status list would
                // offer instead.
                expect(values.toSorted()).toEqual(['cancelled', 'delivered', 'shipped'].toSorted());
                expect(wrapper.get('[data-test=button-cancel-only]').attributes('disabled')).toBe(
                    undefined
                );
            });
    });

    it('leaves Cancel disabled once actions.cancel answers false', () => {
        signInAsAdmin();
        const detail = anOrder({
            status: OrderStatus.delivered,
            actions: { transitions: [], cancel: false, pay: false }
        });

        const wrapper = mountFromListCache(detail);

        return nextTick()
            .then(() => nextTick())
            .then(() => {
                expect(
                    wrapper.get('[data-test=button-cancel-only]').attributes('disabled')
                ).not.toBe(undefined);
                expect(
                    wrapper.get('[data-test=button-cancel-and-refund]').attributes('disabled')
                ).not.toBe(undefined);
            });
    });
});

src/modules/products/tests/product-view..source:
/**
 * @module
 * Mounts the real detail page against a real, memory-history router — every product SHAPE the API
 * can answer with, rather than the one row a fixture happens to seed.
 *
 * The router is REAL — `createMemoryHistory` over `collectModuleRoutes(enabledModules)`, the same
 * nesting `app/router/index.ts` builds — same template as `wishlist-view.spec.ts`. `watchProduct`
 * is stubbed so the store's own fetch never runs; the shape under test is seeded directly into
 * the dictionary instead, which is what lets one spec exercise every branch in milliseconds.
 */
import { describe, expect, it, beforeEach, vi } from 'vitest';
import { mount } from '@vue/test-utils';
import { createPinia, setActivePinia } from 'pinia';
import { createRouter, createMemoryHistory, RouterView } from 'vue-router';
import Product from '@/modules/products/views/Product.vue';
import { useProductsStore } from '@/modules/products/store';
import { useWishlistStore } from '@/modules/wishlist';
import { useSessionStore } from '@/infrastructure/session.ts';
import { i18n, loadLocale } from '@/infrastructure/i18n';
import vuetify from '@/ui/vuetify';
import { collectModuleRoutes } from '@/kernel/registry';
import { enabledModules } from '@/modules';
import { wireModulesIntoCore } from '../../../../tests/support/unit/wire-modules.ts';
import type { Product as ProductType } from '@types';

wireModulesIntoCore();

/**
 * Satisfies `watchProduct`'s `WatchStopHandle` return type without setting up a real watcher.
 */
const noopStopHandle = () => undefined;

/**
 * The real app router, scoped to the modules this test suite enables.
 */
const router = createRouter({
    history: createMemoryHistory(),
    routes: [
        { path: '/:locale', component: RouterView, children: collectModuleRoutes(enabledModules) }
    ]
});

/**
 * A signed-in visitor, so the add-to-cart button is present rather than hidden behind a login prompt.
 */
const signIn = () => {
    const session = useSessionStore();
    session.accessToken = 'test-token';
    session.viewer = { id: 'u1', email: 'shopper@example.com', admin: false };
};

/**
 * Mounts the detail page with `product` already the store's `currentProduct` — nothing depends on
 * the route's own fetch, which is what lets a single spec cover a shape the demo dataset does not
 * happen to seed today.
 *
 * @param product - The shape under test.
 * @returns The mounted wrapper.
 */
const mountProduct = (product: ProductType) => {
    const products = useProductsStore();
    vi.spyOn(products, 'watchProduct').mockImplementation(() => noopStopHandle);
    products.addProduct(product);
    products.selectedProductId = product.id;

    // Decoration on this page, not what is under test — stubbed so a signed-in mount does not
    // fire a real fetch the mocked transport has nothing to answer.
    vi.spyOn(useWishlistStore(), 'fetchWishlist').mockResolvedValue([]);

    return mount(Product, {
        props: { id: product.id },
        global: {
            plugins: [router, vuetify, i18n],
            stubs: { LayoutDefault: { template: '<div><slot /></div>' } }
        }
    });
};

beforeEach(() => {
    setActivePinia(createPinia());
    return loadLocale('en').then(() =>
        router.push('/en/products/placeholder').then(() => router.isReady())
    );
});

describe('the shelf', () => {
    it('blocks buying what is out of stock', () => {
        signIn();
        const wrapper = mountProduct({
            id: 'p-out-of-stock',
            title: 'Sold out widget',
            price: 9.99,
            onHand: 3,
            reserved: 3,
            available: 0
        });

        expect(wrapper.get('[data-test=add-to-cart]').attributes('disabled')).toBeDefined();
        expect(wrapper.get('[data-test=product-stock]').text()).toContain('Out of stock');
    });

    it('allows buying what is in stock', () => {
        signIn();
        const wrapper = mountProduct({
            id: 'p-in-stock',
            title: 'Available widget',
            price: 9.99,
            onHand: 5,
            reserved: 1,
            available: 4
        });

        expect(wrapper.get('[data-test=add-to-cart]').attributes('disabled')).toBeUndefined();
        expect(wrapper.get('[data-test=product-stock]').text()).not.toContain('Out of stock');
    });
});

describe('a barebones product', () => {
    /*
     * The shape `POST /products` answers with when only the required fields are sent — no
     * description, no categories, no tags. The e2e suite's `ProductRole` had a `minimal` value
     * for this shape with no caller anywhere; asserting it here instead of over a browser and a
     * database is what removed the last reason to keep it.
     */
    it('renders the detail page without a description, falling back to the empty-value glyph', () => {
        const wrapper = mountProduct({
            id: 'p-minimal',
            title: 'Bare widget',
            price: 1
        });

        expect(wrapper.find('[data-test=add-to-cart]').exists()).toBe(true);
        expect(wrapper.text()).toContain('—');
    });

    it('renders the real description when the product has one', () => {
        const wrapper = mountProduct({
            id: 'p-rich',
            title: 'Full widget',
            price: 1,
            description: 'Everything a widget could want',
            categories: ['tools']
        });

        expect(wrapper.text()).toContain('Everything a widget could want');
    });
});

src/modules/wishlist/tests/wishlist-view.source:
/**
 * @module
 * The wishlist page, mounted: the shapes the browser suite pays a database for, and one link
 * whose href has to carry an ID while its text carries a TITLE.
 *
 * The router is REAL — `createMemoryHistory` over the products routes under `/:locale`, the same
 * nesting `app/router/index.ts` builds. A `RouterLink` stub that drops `to` renders an anchor
 * with no href, so it agrees with any location at all; only a resolved href proves
 * `routerLinkI18n` and `ProductTarget` produce a URL the app can actually match.
 *
 * The seeded title differs from the id on purpose. `titleOf` falls back to the id
 * (`cart/store.ts`), so a title left unresolved makes `titleOf(id) === id` and a link built from
 * the title would pass while being wrong.
 */
import { describe, expect, it, beforeEach, vi } from 'vitest';
import { mount } from '@vue/test-utils';
import { createPinia, setActivePinia } from 'pinia';
import { createRouter, createMemoryHistory, RouterView } from 'vue-router';
import Wishlist from '@/modules/wishlist/views/Wishlist.vue';
import { useWishlistStore } from '@/modules/wishlist';
import { useCartStore } from '@/modules/cart';
import { i18n, loadLocale } from '@/infrastructure/i18n';
import vuetify from '@/ui/vuetify';
import { collectModuleRoutes } from '@/kernel/registry';
import { enabledModules } from '@/modules';
import { wireModulesIntoCore } from '../../../../tests/support/unit/wire-modules.ts';

wireModulesIntoCore();

/**
 * The saved product, and the title the cart store resolves for it — deliberately not the id.
 */
const PRODUCT_ID = '01J8ZQ7X4M0000000000000001';
const PRODUCT_TITLE = 'Wireless Headphones';

/*
 * The app's OWN route table, assembled the way `app/router/index.ts` assembles it — every enabled
 * module's routes under one `/:locale` parent. Naming `products`' routes directly would be
 * reaching past a sibling's barrel, and would also be the weaker assertion: a copy of
 * `products/:id` keeps agreeing with itself after the real route moves.
 */
const router = createRouter({
    history: createMemoryHistory(),
    routes: [
        { path: '/:locale', component: RouterView, children: collectModuleRoutes(enabledModules) }
    ]
});

/**
 * Mounts the page with the stores already holding `items`, so nothing depends on `onMounted`'s
 * fetch settling — the view is what is under test, not the transport.
 *
 * @param productIds - The saved lines, in order.
 * @returns The mounted wrapper.
 */
const mountWishlist = (productIds: string[]) => {
    const wishlist = useWishlistStore();
    const cart = useCartStore();

    wishlist.items = productIds.map((productId) => ({ productId }));
    cart.productTitles = { [PRODUCT_ID]: PRODUCT_TITLE };
    // `onMounted` fetches and then resolves titles; both are seeded above, so both are answered
    // from state rather than from a transport this spec does not exercise.
    vi.spyOn(wishlist, 'fetchWishlist').mockResolvedValue(wishlist.items);
    vi.spyOn(cart, 'resolveTitles').mockResolvedValue(cart.productTitles);

    return mount(Wishlist, {
        global: {
            plugins: [router, vuetify, i18n],
            stubs: { LayoutDefault: { template: '<div><slot /></div>' } }
        }
    });
};

beforeEach(() => {
    setActivePinia(createPinia());
    // Without the dictionaries every `t()` renders its own key, and the label cases below would
    // compare one key against another and pass.
    return loadLocale('en').then(() => router.push('/en/wishlist').then(() => router.isReady()));
});

describe('the link on a saved item', () => {
    it('points at the product ID and reads as the product TITLE', () => {
        const wrapper = mountWishlist([PRODUCT_ID]);
        const link = wrapper.get('[data-test=wishlist-item] h2 a');

        expect(link.attributes('href')).toBe(`/en/products/${PRODUCT_ID}`);
        expect(link.text()).toBe(PRODUCT_TITLE);
    });

    it('resolves to ProductTarget carrying the id as its param', () => {
        const wrapper = mountWishlist([PRODUCT_ID]);
        const resolved = router.resolve(
            wrapper.get('[data-test=wishlist-item] h2 a').attributes('href') ?? ''
        );

        // The href above is a string; this is the half that says the app can MATCH it — a link
        // that 404s resolves to the catch-all, not to the product route.
        expect(resolved.name).toBe('ProductTarget');
        expect(resolved.params).toEqual({ locale: 'en', id: PRODUCT_ID });
    });
});

describe('the item list', () => {
    it('renders one card per saved line, keyed by its product', () => {
        const other = '01J8ZQ7X4M0000000000000002';
        const wrapper = mountWishlist([PRODUCT_ID, other]);

        expect(wrapper.findAll('[data-test=wishlist-item]')).toHaveLength(2);
        // The second line has no resolved title, so it reads as its own id — the documented
        // fallback, and the reason the first line's title must differ from its id above.
        expect(wrapper.findAll('[data-test=wishlist-item] h2 a').at(1)?.text()).toBe(other);
    });

    it('names the product in both action labels, by title rather than by id', () => {
        const wrapper = mountWishlist([PRODUCT_ID]);

        // The mirror of the link: these three call sites SHOULD say the human name.
        expect(wrapper.get('[data-test=wishlist-move-to-cart]').attributes('aria-label')).toContain(
            PRODUCT_TITLE
        );
        expect(wrapper.get('[data-test=wishlist-remove]').attributes('aria-label')).toContain(
            PRODUCT_TITLE
        );
    });

    it('renders the empty state and no cards when nothing is saved', () => {
        const wrapper = mountWishlist([]);

        expect(wrapper.findAll('[data-test=wishlist-item]')).toHaveLength(0);
        expect(wrapper.find('.v-empty-state').exists()).toBe(true);
    });
});

tests/unit/app/app-navigation.spec.ts.source:
/**
 * App navigation.
 *
 * Beyond rendering, this pins the property that makes the menu trustworthy: an entry is shown
 * exactly when the router would let the visitor enter the route it points at. The nav reads
 * `meta.access` off the resolved route rather than carrying its own visibility flags, so the two
 * cannot drift — and these cases are what would catch it if someone reintroduced a flag.
 *
 * ── Why the modules here are invented ────────────────────────────────────────────────────────
 * `AppNavigation` builds its list from `collectModuleNavigation(enabledModules)`. Asserting
 * against the REAL registry would mean naming `products`, `cart`, `admin`… in a platform spec —
 * the exact coupling the manifest removed from `src/`, moved into `tests/`. Deleting a domain
 * would then break a test that is not about that domain at all (see `docs/theory/modules.md`,
 * "Deleting a domain").
 *
 * So `@/modules` is mocked with three throwaway domains covering the three visibility classes.
 * What is under test is the mechanism — filter by the resolved route's `meta.access`, order by
 * `order` — and the mechanism is what breaks. That every real module's entry points at a route it
 * actually declares is a separate, registry-driven invariant: `tests/cross-cutting/registry.spec.ts`.
 *
 * The three domains also cover the three SECTIONS — the bar, the account menu, the admin menu —
 * so what folds where on desktop is asserted alongside who sees what. The member domain also
 * contributes a PINNED entry: lifted out of the account menu onto the bar, beside it, with its
 * count and its detail text — the cart's shape, without naming the cart.
 */
import { beforeEach, describe, it, expect, vi } from 'vitest';
import { mount } from '@vue/test-utils';
import { ref } from 'vue';
import { createPinia } from 'pinia';
import AppNavigation from '@/app/components/AppNavigation.vue';
import vuetify from '@/ui/vuetify';
import type { RouteAccess } from '@/app/guards/authentications';

const session = {
    isAuth: ref(false),
    isAdmin: ref(false),
    viewer: ref<{ email: string } | undefined>(undefined)
};

/**
 * Which of the auth routes this build ships.
 *
 * The shell addresses `Login` and `Signup` by name — strings the account module owns and nothing
 * type-checks — so it asks `router.hasRoute` before offering either. Flipping this to `false` is
 * the "no account module in this build" case.
 */
const registeredRoutes = ref<string[]>(['Login', 'Signup']);

/** The route the visitor is currently on, as `useRoute()` reports it. */
const currentRoute = ref<{ name?: string; fullPath: string }>({ fullPath: '/' });

/** Access declared by the routes the invented modules link to, plus the shell's own two. */
const routeAccess: Record<string, RouteAccess | undefined> = {
    Home: undefined,
    Playground: undefined,
    PublicThing: undefined,
    LateThing: undefined,
    MemberThing: 'auth',
    PinnedThing: 'auth',
    StaffThing: 'admin'
};

/** The live count behind the member entry's badge; `0` renders no badge at all. */
const memberCount = ref(0);

/** The live count behind the pinned entry's badge. */
const pinnedCount = ref(0);

/** The live text beside the pinned entry's glyph — a formatted total, in the real thing. */
const pinnedDetail = ref<string | undefined>(undefined);

/**
 * Stands in for a lucide glyph: what matters is that it renders hidden from the reader. Hoisted
 * because the module mock below reads it eagerly, and `vi.mock` runs before this file's body.
 */
const { Glyph } = vi.hoisted(() => ({
    Glyph: { template: '<svg data-test="glyph" aria-hidden="true" />' }
}));

/*
 * Three invented domains, one per visibility class and one per section. `order` is deliberately
 * out of sequence so the sort is exercised rather than accidentally satisfied by declaration order.
 */
vi.mock('@/modules', () => ({
    enabledModules: [
        {
            name: 'staff-domain',
            routes: [],
            navigation: [
                {
                    name: 'StaffThing',
                    label: 'navigation.label-staff',
                    order: 90,
                    section: 'admin',
                    icon: Glyph
                },
                // A public entry from the FIRST registered module, ranked near the end of `main`.
                { name: 'LateThing', label: 'navigation.label-late', order: 95, icon: Glyph }
            ]
        },
        {
            name: 'public-domain',
            routes: [],
            navigation: [
                { name: 'PublicThing', label: 'navigation.label-public', order: 30, icon: Glyph }
            ]
        },
        {
            name: 'member-domain',
            routes: [],
            navigation: [
                {
                    name: 'MemberThing',
                    label: 'navigation.label-member',
                    order: 60,
                    section: 'account',
                    icon: Glyph,
                    badge: () => memberCount
                },
                {
                    name: 'PinnedThing',
                    label: 'navigation.label-pinned',
                    order: 65,
                    section: 'account',
                    pinned: true,
                    icon: Glyph,
                    badge: () => pinnedCount,
                    detail: () => pinnedDetail
                }
            ]
        }
    ]
}));

vi.mock('vue-i18n', async (importOriginal) => {
    const actual = await importOriginal<typeof import('vue-i18n')>();
    return {
        ...actual,
        useI18n: () => ({
            // The plural form is echoed so a label built with `t(key, count)` can be asserted on.
            t: (key: string, count?: number) => (count === undefined ? key : `${key}:${count}`),
            locale: ref('en')
        })
    };
});

vi.mock('vue-router', () => ({
    RouterLink: {
        template: '<a><slot /></a>'
    },
    useRoute: () => ({ ...currentRoute.value, params: {}, query: {} }),
    useRouter: () => ({
        push: vi.fn(),
        replace: vi.fn(),
        resolve: ({ name }: { name: string }) => ({ meta: { access: routeAccess[name] } }),
        hasRoute: (name: string) => registeredRoutes.value.includes(name)
    })
}));

vi.mock('@/infrastructure/session.ts', () => ({
    useSessionStore: () => session
}));

/** Mounts the nav and returns the labels of the entries it rendered. */
const mountNav = () => {
    const wrapper = mount(AppNavigation, {
        global: {
            plugins: [createPinia(), vuetify],
            stubs: {
                // v-app-bar teleports into a v-app layout that does not exist here
                VAppBar: {
                    template:
                        '<header><slot name="prepend" /><slot /><slot name="append" /></header>'
                },
                // `v-model` becomes a plain attribute on a stub; the aside is always rendered.
                VNavigationDrawer: { template: '<aside><slot /></aside>' },
                // Both overlays render their content lazily, on open; here it is always there,
                // so a menu's entries can be asserted without a click.
                VMenu: {
                    template:
                        '<div data-test="menu"><slot name="activator" :props="{}" /><slot /></div>'
                },
                VTooltip: {
                    template: '<div><slot name="activator" :props="{}" /><slot /></div>'
                }
            }
        },
        // In the document, so focus can actually move: jsdom ignores `focus()` on a detached node.
        attachTo: document.body
    });
    return { wrapper, text: wrapper.text() };
};

/**
 * Whether the app bar renders NO control carrying `label`.
 *
 * The auth links are `v-if`-ed, not `v-show`-hidden: a hidden-but-present button is still in
 * the tab order, which is the accessibility defect this helper now guards against. So "hidden"
 * means "absent from the DOM" — an `a` or a `button`, whichever Vuetify renders for a `to`.
 */
const isHidden = (wrapper: ReturnType<typeof mountNav>['wrapper'], label: string) =>
    !wrapper
        .findAll('header a, header button')
        .some((candidate) => candidate.text().includes(label));

describe('Navigation', () => {
    beforeEach(() => {
        session.isAuth.value = false;
        session.isAdmin.value = false;
        session.viewer.value = undefined;
        registeredRoutes.value = ['Login', 'Signup'];
        currentRoute.value = { fullPath: '/' };
        memberCount.value = 0;
        pinnedCount.value = 0;
        pinnedDetail.value = undefined;
        document.body.innerHTML = '';
    });

    it('renders properly', () => {
        expect(mountNav().wrapper).toBeTruthy();
    });

    it('shows a guest only the public entries', () => {
        const { text } = mountNav();

        expect(text).toContain('navigation.label-home');
        expect(text).toContain('navigation.label-public');
        expect(text).not.toContain('navigation.label-member');
        expect(text).not.toContain('navigation.label-staff');
    });

    it('adds the authenticated entries once logged in, but not the admin ones', () => {
        session.isAuth.value = true;

        const { text } = mountNav();

        expect(text).toContain('navigation.label-member');
        // The trap this guards: an admin-only page listed for every logged-in visitor.
        expect(text).not.toContain('navigation.label-staff');
    });

    it('shows the admin entries to an admin', () => {
        session.isAuth.value = true;
        session.isAdmin.value = true;

        const { text } = mountNav();

        expect(text).toContain('navigation.label-staff');
        expect(text).toContain('navigation.label-member');
    });

    it('orders entries within a section by `order`, not by module registration order', () => {
        const { wrapper } = mountNav();

        // staff-domain is registered first, but its public entry is ranked after the shell's.
        expect(wrapper.findAll('header nav a').map((link) => link.text())).toEqual([
            'navigation.label-home:1',
            'navigation.label-public:1',
            'navigation.label-late:1',
            'navigation.label-about:1'
        ]);
    });

    it('lists the drawer sections in kernel order: main, then account, then admin', () => {
        session.isAuth.value = true;
        session.isAdmin.value = true;

        const text = mountNav().wrapper.find('#app-drawer').text();

        expect(text.indexOf('navigation.label-public')).toBeLessThan(
            text.indexOf('navigation.label-member')
        );
        expect(text.indexOf('navigation.label-member')).toBeLessThan(
            text.indexOf('navigation.label-staff')
        );
    });

    it('offers sign-in and sign-up when the account routes are registered', () => {
        const { text } = mountNav();

        expect(text).toContain('navigation.label-login');
        expect(text).toContain('navigation.label-signup');
    });

    /**
     * Hidden by ROUTE NAME, not by a substring of the path: a substring match also fires on
     * `/en/products/login-adapter` and on any `?continue=/en/login`.
     */
    it.each([
        ['Login', 'navigation.label-login'],
        ['Signup', 'navigation.label-signup']
    ])('hides the %s button while the visitor is already on that page', (name, label) => {
        currentRoute.value = { name, fullPath: `/en/${name.toLowerCase()}` };

        expect(isHidden(mountNav().wrapper, label)).toBe(true);
    });

    it('keeps both buttons on a route that merely CONTAINS the word login', () => {
        currentRoute.value = { name: 'ProductTarget', fullPath: '/en/products/login-adapter' };

        const { wrapper } = mountNav();

        expect(isHidden(wrapper, 'navigation.label-login')).toBe(false);
        expect(isHidden(wrapper, 'navigation.label-signup')).toBe(false);
    });

    it('offers neither when this build ships no sign-in route', () => {
        // A build with the account module deleted: the shell must not render a button that
        // navigates nowhere. Route names are strings, so only `hasRoute` can tell.
        registeredRoutes.value = [];

        const { text } = mountNav();

        expect(text).not.toContain('navigation.label-login');
        expect(text).not.toContain('navigation.label-signup');
    });

    it('renders the shell entries when no module contributes anything', () => {
        // The event-portal end state: every domain deleted, the shell still has a menu.
        const { text } = mountNav();

        expect(text).toContain('navigation.label-home');
        expect(text).toContain('navigation.label-about');
    });

    /**
     * Links, not buttons. A screen reader says "link" for something that navigates, and a
     * middle-click opens a tab; the old `@click="router.push(...)"` buttons did neither.
     */
    it('renders sign-in and sign-up as links to their routes', () => {
        const { wrapper } = mountNav();

        // The mocked `RouterLink` resolves no `href`, so the element's kind is what is pinned.
        const login = wrapper
            .findAll('header a')
            .find((candidate) => candidate.text().includes('navigation.label-login'));
        expect(login, 'login is not a link').toBeDefined();
        expect(
            wrapper
                .findAll('header button')
                .some((b) => b.text().includes('navigation.label-login'))
        ).toBe(false);
    });

    /**
     * A badge with no `label` is announced as "Badge" — a number with no subject. The label is
     * the plural form of the count, so "3" reads as "3 items".
     */
    it('names the nav badge after its count, on the menu the entry folds into', () => {
        session.isAuth.value = true;
        session.viewer.value = { email: 'someone@example.com' };
        memberCount.value = 3;

        const { wrapper } = mountNav();

        // `data-test` lands on the wrapper; Vuetify puts the name on the badge element inside.
        const badge = wrapper.find('[data-test="nav-badge"] .v-badge__badge');
        expect(badge.exists()).toBe(true);
        expect(badge.attributes('aria-label')).toBe('navigation.badge-items:3');
    });

    it('renders no badge, and therefore no label, for a zero count', () => {
        session.isAuth.value = true;
        session.viewer.value = { email: 'someone@example.com' };

        const { wrapper } = mountNav();

        expect(wrapper.find('[data-test="nav-badge"]').exists()).toBe(false);
    });

    /**
     * The bar says each page's name in full (WCAG 2.5.3: the visible text IS the accessible
     * name, so no `aria-label` to drift from it), and the glyph beside it is hidden from the
     * reader (WCAG 1.1.1).
     */
    it('shows every bar entry as its label, with the glyph hidden from the reader', () => {
        const { wrapper } = mountNav();

        const links = wrapper.findAll('header nav a');
        expect(links.map((link) => link.text())).toEqual([
            'navigation.label-home:1',
            'navigation.label-public:1',
            'navigation.label-late:1',
            'navigation.label-about:1'
        ]);
        for (const link of links) {
            expect(link.attributes('aria-label')).toBeUndefined();
            expect(link.find('svg').attributes('aria-hidden')).toBe('true');
        }
    });

    /**
     * A pinned entry is its own button on the bar, beside the account menu, and NOT a row in
     * that menu: the count on the glyph, the detail text beside it, and one accessible name
     * that tells the whole story — the detail is hidden on narrow screens, the badge is a bare
     * number, so neither can be relied on for the name.
     */
    it('lifts a pinned entry out of the account menu onto the bar, with its count and detail', () => {
        session.isAuth.value = true;
        session.viewer.value = { email: 'someone@example.com' };
        pinnedCount.value = 3;
        pinnedDetail.value = '€ 59.97';

        const { wrapper } = mountNav();

        const pinned = wrapper.find('header a[data-test="pinned-PinnedThing"]');
        expect(pinned.exists(), 'pinned entry is not a link on the bar').toBe(true);
        expect(pinned.attributes('aria-label')).toBe(
            'navigation.label-pinned:1: navigation.badge-items:3, € 59.97'
        );
        // The badge wraps the link (nested inside the button it would not show), so the count
        // is looked up from the wrapper that contains the link, not inside the link.
        const badge = wrapper
            .findAll('header [data-test="nav-badge"]')
            .find((candidate) => candidate.find('[data-test="pinned-PinnedThing"]').exists());
        expect(badge?.find('.v-badge__badge').text()).toBe('3');
        expect(pinned.find('[data-test="nav-detail"]').text()).toBe('€ 59.97');

        const menuItems = wrapper
            .findAll(
                'header [role="menu"][aria-label="navigation.label-account-menu"] [role="menuitem"]'
            )
            .map((item) => item.text());
        expect(menuItems).not.toContain('navigation.label-pinned:1');
        // The drawer still lists it under its section: on a phone the bar is the drawer.
        expect(wrapper.find('#app-drawer').text()).toContain('navigation.label-pinned:1');
    });

    it('renders a pinned entry with nothing to show as the named glyph alone', () => {
        session.isAuth.value = true;
        session.viewer.value = { email: 'someone@example.com' };

        const { wrapper } = mountNav();
        const pinned = wrapper.find('header [data-test="pinned-PinnedThing"]');

        expect(pinned.attributes('aria-label')).toBe('navigation.label-pinned:1');
        expect(wrapper.find('header [data-test="nav-badge"]').exists()).toBe(false);
        expect(pinned.find('[data-test="nav-detail"]').exists()).toBe(false);
    });

    it('shows no pinned entry to a visitor its route would turn away', () => {
        expect(mountNav().wrapper.find('[data-test="pinned-PinnedThing"]').exists()).toBe(false);
    });

    it('folds the account entries into a user menu named after the signed-in email', () => {
        session.isAuth.value = true;
        session.viewer.value = { email: 'someone@example.com' };

        const { wrapper } = mountNav();

        const menu = wrapper.find('[data-test="user-menu"]');
        expect(menu.attributes('aria-label')).toBe(
            'navigation.label-account-menu: someone@example.com'
        );
        // The member entry sits in the menu, not in the bar.
        expect(wrapper.find('header nav').text()).not.toContain('navigation.label-member');
        const items = wrapper.findAll(
            'header [role="menu"][aria-label="navigation.label-account-menu"] [role="menuitem"]'
        );
        expect(items.map((item) => item.text())).toEqual([
            'navigation.label-member:1',
            'navigation.label-logout'
        ]);
    });

    it('offers no user menu to a guest', () => {
        expect(mountNav().wrapper.find('[data-test="user-menu"]').exists()).toBe(false);
    });

    it('folds the admin entries into an administration menu, for admins only', () => {
        expect(mountNav().wrapper.find('[data-test="admin-menu"]').exists()).toBe(false);

        session.isAuth.value = true;
        session.isAdmin.value = true;
        const { wrapper } = mountNav();

        expect(wrapper.find('[data-test="admin-menu"]').attributes('aria-label')).toBe(
            'navigation.label-admin-menu'
        );
        expect(wrapper.find('header nav').text()).not.toContain('navigation.label-staff');
        expect(
            wrapper
                .findAll(
                    'header [role="menu"][aria-label="navigation.label-admin-menu"] [role="menuitem"]'
                )
                .map((item) => item.text())
        ).toEqual(['navigation.label-staff:1']);
    });

    it('heads each drawer section, and only the sections with something in them', () => {
        const guest = mountNav().wrapper;
        expect(guest.find('[data-test="drawer-section-main"]').exists()).toBe(true);
        expect(guest.find('[data-test="drawer-section-account"]').exists()).toBe(false);
        expect(guest.find('[data-test="drawer-section-admin"]').exists()).toBe(false);

        session.isAuth.value = true;
        session.isAdmin.value = true;
        const admin = mountNav().wrapper;
        expect(admin.findAll('#app-drawer .v-list-subheader').map((h) => h.text())).toEqual([
            'navigation.section-main',
            'navigation.section-account',
            'navigation.section-admin'
        ]);
    });

    /**
     * The hamburger and the drawer are wired to each other (WCAG 4.1.2): `aria-controls` names
     * the drawer, `aria-expanded` follows its state, and the drawer carries a label of its own,
     * distinct from the desktop nav's, so the two landmarks can be told apart.
     */
    it('declares the drawer it controls and whether it is open', () => {
        const { wrapper } = mountNav();

        const hamburger = wrapper.find('header button[aria-controls="app-drawer"]');
        expect(hamburger.exists()).toBe(true);
        expect(hamburger.attributes('aria-expanded')).toBe('false');
        expect(wrapper.find('#app-drawer').attributes('aria-label')).toBe(
            'navigation.label-drawer'
        );
        // Both on the right: the hamburger is the bar's last control, and the drawer it opens
        // slides in from the same edge (the stub keeps the prop as an attribute).
        expect(wrapper.findAll('header button').at(-1)?.attributes('aria-controls')).toBe(
            'app-drawer'
        );
        expect(wrapper.find('#app-drawer').attributes('location')).toBe('end');

        return hamburger.trigger('click').then(() => {
            expect(hamburger.attributes('aria-expanded')).toBe('true');
        });
    });

    it('closes the drawer on Escape and returns focus to the hamburger', () => {
        const { wrapper } = mountNav();
        const hamburger = wrapper.find('header button[aria-controls="app-drawer"]');

        return (
            hamburger
                .trigger('click')
                // Let the drawer take focus first, as it does for a real visitor, so the return
                // trip is what is asserted rather than a focus that never left.
                .then(() =>
                    vi.waitFor(() => expect(document.activeElement).not.toBe(document.body))
                )
                .then(() => wrapper.find('#app-drawer').trigger('keydown', { key: 'Escape' }))
                .then(() =>
                    vi.waitFor(() => expect(hamburger.attributes('aria-expanded')).toBe('false'))
                )
                .then(() =>
                    vi.waitFor(() => expect(document.activeElement).toBe(hamburger.element))
                )
        );
    });
});

tests/unit/infrastructure/http/http-refr.source:
/**
 * The 401 → refresh → replay flow, driven through the real interceptor chain.
 *
 * This is the one piece of client logic where a bug is both invisible to types and invisible to
 * the e2e suite: a broken refresh does not throw, it just logs the user out at some later moment.
 *
 * It is therefore tested against a real HTTP server (MSW's node interceptor) rather than a stubbed
 * axios adapter. The whole point is that `instance.interceptors.response` runs, that the *replay*
 * goes back through the same instance, and that `_dontRetry` actually stops the second round —
 * none of which a hand-rolled adapter would reproduce.
 *
 * `tests/unit/infrastructure/http/http.spec.ts` covers the error-normalisation side of the same
 * module with plain unit stubs; the two are complementary.
 *
 * ── How a case is written ────────────────────────────────────────────────────────────────────
 * The handlers below answer from {@link scenario}, and a case sets the one field it cares about.
 * Everything a case does NOT set is at its default, so what a test changes is exactly what it is
 * about. Assertions read {@link requestLog} — the server's own record of what arrived — because a
 * refresh attempt is not observable from the caller's side without stubbing the code under test.
 */
import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it, vi } from 'vitest';
import { setupServer } from 'msw/node';
import { http, HttpResponse } from 'msw';
import { createPinia, setActivePinia } from 'pinia';
import { useSessionStore } from '@/infrastructure/session.ts';

/** Base URL the axios instance is built against; also what the handlers below are mounted on. */
const API = 'http://api.test';

/** The token a successful refresh hands back, and therefore what the replay must carry. */
const FRESH_TOKEN = 'fresh-token';

/**
 * Endpoints that must never trigger a refresh, mirroring `refreshExcludedPaths` in
 * `src/infrastructure/http/refresh.ts`.
 *
 * A 401 from any of them is a normal business outcome — wrong password, expired reset link, a
 * session already invalidated — so refreshing there turns a clean error message into an extra
 * round trip and, when the refresh also fails, a misleading session-expired state.
 */
const EXCLUDED_PATHS = [
    '/account/login',
    '/account/signup',
    '/account/reset',
    '/account/reset-confirm',
    '/account/logout-all',
    '/account/login/2fa',
    '/account/login/2fa/send'
];

/**
 * The same exclusion spelled absolutely.
 *
 * Generated clients send relative urls, but a caller passing an absolute one must get identical
 * treatment or the exclusion silently stops applying to it.
 */
const ABSOLUTE_EXCLUDED_URL = 'https://api.example.com/account/login';

/** One request as the server saw it. */
interface LoggedRequest {
    /** `METHOD /pathname`, which is what the assertions compare against. */
    route: string;
    /** The `Authorization` header, so the replay can be shown to carry the NEW token. */
    authorization?: string;
}

/** How the server should behave for one test. Reset to these defaults before every case. */
interface Scenario {
    /** How many more times `/account/refresh` may succeed; beyond that it answers 401. */
    refreshBudget: number;
    /** Answer the refresh with `200` and an envelope carrying no token — a failure wearing a success status. */
    refreshOmitsToken: boolean;
    /** Whether the protected route accepts {@link FRESH_TOKEN}; `false` makes the replay 401 too. */
    protectedAccepts: boolean;
}

/** @returns The scenario every case starts from: one refresh available, nothing accepted yet. */
const defaultScenario = (): Scenario => ({
    refreshBudget: 1,
    refreshOmitsToken: false,
    protectedAccepts: false
});

/** Requests seen by the server, in arrival order. Cleared before every case. */
let requestLog: LoggedRequest[] = [];

/** What the handlers answer with for the case currently running. */
let scenario: Scenario = defaultScenario();

/**
 * Builds the envelope the API rejects with, so the handlers and the app agree on one error shape.
 *
 * @param message - Human-readable reason, echoed into `errors[0].message` as the API does.
 * @returns A 401 response carrying the standard reject envelope.
 */
const unauthorized = (message: string) =>
    HttpResponse.json(
        { success: false, status: 401, message, errors: [{ code: 'UNAUTHORIZED', message }] },
        { status: 401 }
    );

const server = setupServer(
    /**
     * `GET /account/refresh` — succeeds while the budget lasts, then answers 401 like an expired
     * refresh cookie would.
     */
    http.get(`${API}/account/refresh`, ({ request }) => {
        requestLog.push({
            route: 'GET /account/refresh',
            authorization: request.headers.get('authorization') ?? undefined
        });

        if (scenario.refreshBudget <= 0) return unauthorized('Unauthorized');
        scenario.refreshBudget -= 1;

        return scenario.refreshOmitsToken
            ? HttpResponse.json({ success: true, status: 200, data: {} })
            : HttpResponse.json({ success: true, status: 200, data: { token: FRESH_TOKEN } });
    }),

    /**
     * `GET /orders` — the protected route the flow is triggered from. It answers 401 until it is
     * both told to accept and given the refreshed token, which is what makes the replay visible.
     */
    http.get(`${API}/orders`, ({ request }) => {
        const authorization = request.headers.get('authorization') ?? undefined;
        requestLog.push({ route: 'GET /orders', authorization });

        return scenario.protectedAccepts && authorization === `Bearer ${FRESH_TOKEN}`
            ? HttpResponse.json({ success: true, status: 200, data: { items: [] } })
            : unauthorized('Unauthorized');
    }),

    /** Every excluded path, each answering 401 as the ordinary outcome the exclusion exists for. */
    ...[...EXCLUDED_PATHS, ABSOLUTE_EXCLUDED_URL].map((path) =>
        http.post(path.startsWith('http') ? path : `${API}${path}`, ({ request }) => {
            requestLog.push({ route: `POST ${new URL(request.url).pathname}` });
            return unauthorized('Bad credentials');
        })
    )
);

/**
 * Imports the http plugin fresh, with the API base URL stubbed.
 *
 * The module builds its axios instance and registers its interceptors at import time, so the env
 * has to be in place first and the registry has to be reset between cases — otherwise the
 * interceptors stack up and one request runs the chain several times.
 *
 * @returns The freshly imported module, with `orvalMutator` on it.
 */
const loadHttp = () => {
    vi.resetModules();
    vi.stubEnv('VITE_API_URL', API);
    return import('@/infrastructure/http');
};

/**
 * Clears the `isAuth` cookie through the prototype setter, the way `stores/session.ts` writes it.
 *
 * @returns Nothing; the cookie is cleared as a side effect.
 */
const clearAuthCookie = () =>
    Object.getOwnPropertyDescriptor(Document.prototype, 'cookie')?.set?.call(
        document,
        'isAuth=; path=/; max-age=0'
    );

/**
 * Every request the server saw, as `METHOD /pathname`.
 *
 * @returns The routes in arrival order — the sequence most assertions here are about.
 */
const routes = () => requestLog.map(({ route }) => route);

/**
 * How many times one route was requested.
 *
 * @param route - The `METHOD /pathname` to count.
 * @returns The number of matching requests the server saw.
 */
const timesRequested = (route: string) =>
    requestLog.filter((request) => request.route === route).length;

beforeAll(() => server.listen({ onUnhandledRequest: 'error' }));
afterEach(() => server.resetHandlers());
afterAll(() => server.close());

beforeEach(() => {
    setActivePinia(createPinia());
    requestLog = [];
    scenario = defaultScenario();
    clearAuthCookie();
    vi.unstubAllEnvs();
});

describe('401 refresh flow', () => {
    describe('when the refresh succeeds', () => {
        beforeEach(() => {
            scenario.protectedAccepts = true;
        });

        it('refreshes once and replays the original request with the new token', () =>
            loadHttp()
                .then(({ orvalMutator }) =>
                    orvalMutator<{ data: { items: unknown[] } }>({ url: '/orders', method: 'GET' })
                )
                .then((result) => {
                    expect(result.data.items).toEqual([]);
                    expect(routes()).toEqual([
                        'GET /orders',
                        'GET /account/refresh',
                        'GET /orders'
                    ]);
                    expect(requestLog.at(-1)?.authorization).toBe(`Bearer ${FRESH_TOKEN}`);
                }));

        it('stores the refreshed token, so later calls carry it', () =>
            loadHttp().then(({ orvalMutator }) =>
                orvalMutator({ url: '/orders', method: 'GET' }).then(() => {
                    expect(useSessionStore().accessToken).toBe(FRESH_TOKEN);
                })
            ));

        /**
         * `setAccessToken` is the only writer of the JS-readable `isAuth` cookie, and
         * `tryRestoreAuth` reads it on the next boot: without it a signed-in visitor looks like a
         * guest after a reload.
         */
        it('restores the isAuth cookie, not just the in-memory token', () =>
            loadHttp()
                .then(({ orvalMutator }) => orvalMutator({ url: '/orders', method: 'GET' }))
                .then(() => {
                    expect(document.cookie).toContain('isAuth=true');
                }));

        /**
         * Single-flight: two 401s in the same tick must not race the refresh cookie against
         * itself with two `GET /account/refresh` calls.
         */
        it('shares one refresh call between two 401s that arrive together', () =>
            loadHttp().then(({ orvalMutator }) =>
                Promise.all([
                    orvalMutator({ url: '/orders', method: 'GET' }),
                    orvalMutator({ url: '/orders', method: 'GET' })
                ]).then(() => {
                    expect(timesRequested('GET /account/refresh')).toBe(1);
                })
            ));
    });

    describe('when the refresh does not produce a usable token', () => {
        /**
         * A 200 whose envelope carries no token is a failed refresh wearing a success status. The
         * caller is owed either a body or a rejection; anything else surfaces as a `TypeError` in
         * whichever store dereferenced it, far from the interceptor that caused it.
         */
        it('rejects with the original error when the refresh answers 200 without a token', () => {
            scenario.refreshOmitsToken = true;

            return loadHttp()
                .then(({ orvalMutator }) =>
                    expect(orvalMutator({ url: '/orders', method: 'GET' })).rejects.toMatchObject({
                        success: false,
                        status: 401
                    })
                )
                .then(() => {
                    // Never replayed: there was no token to replay it with.
                    expect(timesRequested('GET /orders')).toBe(1);
                });
        });

        it('rejects with the original error when the refresh itself fails', () => {
            scenario.refreshBudget = 0;

            return loadHttp()
                .then(({ orvalMutator }) =>
                    expect(orvalMutator({ url: '/orders', method: 'GET' })).rejects.toMatchObject({
                        success: false,
                        status: 401
                    })
                )
                .then(() => {
                    expect(timesRequested('GET /orders')).toBe(1);
                });
        });

        /** `protectedAccepts` stays false, so the replayed request answers 401 as well. */
        it('does not retry a second time when the replay also fails', () =>
            loadHttp()
                .then(({ orvalMutator }) =>
                    expect(orvalMutator({ url: '/orders', method: 'GET' })).rejects.toMatchObject({
                        status: 401
                    })
                )
                .then(() => {
                    // One refresh and two /orders calls — `_dontRetry` stopped the loop.
                    expect(timesRequested('GET /account/refresh')).toBe(1);
                    expect(timesRequested('GET /orders')).toBe(2);
                }));
    });

    /**
     * Driven through `orvalMutator` against the real interceptor chain, and asserted on the
     * server's own request log — the only place a refresh attempt is observable without mocking
     * the very code under test.
     */
    describe('when the 401 comes from an excluded endpoint', () => {
        it.each([
            ...EXCLUDED_PATHS,
            ABSOLUTE_EXCLUDED_URL,
            // With a query string: the exclusion matches a PATHNAME, and `?next=` is the shape a
            // sign-in redirect actually arrives in.
            '/account/login?next=/cart'
        ])('never attempts a refresh for a 401 from %s', (url) =>
            loadHttp()
                .then(({ orvalMutator }) =>
                    expect(orvalMutator({ url, method: 'POST', data: {} })).rejects.toMatchObject({
                        status: 401
                    })
                )
                .then(() => {
                    // The endpoint itself was reached...
                    expect(routes().some((route) => route.startsWith('POST '))).toBe(true);
                    // ...and no refresh was attempted off the back of its 401.
                    expect(timesRequested('GET /account/refresh')).toBe(0);
                })
        );
    });
});

