/**
 * @module
 * Unit tests for the SSE composable behind the observability dashboard, driven by a mocked
 * `createSseClient` rather than a real `EventSource`: what this file owns is the wiring — which
 * url is opened, which store action each event name reaches, and that the module-level singleton
 * is torn down before a second connection replaces it. The transport itself is
 * `tests/unit/infrastructure/create-sse-client.spec.ts`.
 *
 * Every case re-imports the module through `vi.resetModules()`, because `activeClient` lives at
 * module scope — see `loadComposable`: without a fresh module a test would inherit the previous
 * test's open connection and the reconnect assertions would pass for the wrong reason.
 */
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';
import type { SseClientCallbacks } from '@/infrastructure/create-sse-client';
import type { MetricsSnapshotEvent, SseEventName } from '@types';

/**
 * The fake `close` method every mocked SSE client instance shares, so calls on it can be asserted.
 */
const close = vi.fn();

/**
 * The parameters are declared even though the body ignores them: `vi.fn(() => …)` types its
 * `mock.calls` as an empty tuple, so every assertion on what the composable PASSED — the url, the
 * event names, the callbacks — would be a type error rather than a check.
 */
const createSseClient = vi.fn(
    (_url?: string, _eventNames?: readonly SseEventName[], _callbacks?: SseClientCallbacks) => ({
        close
    })
);

vi.mock('@/infrastructure/create-sse-client', () => ({
    createSseClient: (...parameters: unknown[]) =>
        createSseClient(...(parameters as Parameters<typeof createSseClient>))
}));

/**
 * Minimal payload accepted by every metrics event on the stream.
 */
const makeEvent = (timestamp: string): MetricsSnapshotEvent => ({
    timestamp,
    uptimeSeconds: 60,
    memory: { rss: 1, heapUsed: 1, heapTotal: 2, external: 0 },
    http: { totalRequests: 10, totalErrors: 0 },
    realtime: { sseClients: 1 }
});

/**
 * Imports the composable and its store fresh, so the module-level `activeClient` starts undefined.
 *
 * @returns The composable factory and the store hook from the same module graph.
 */
const loadComposable = () => {
    vi.resetModules();
    return Promise.all([
        import('@/modules/realtime/use-realtime-observability'),
        import('@/modules/realtime/store')
    ]).then(([{ useRealtimeObservability }, { useRealtimeObservabilityStore }]) => ({
        useRealtimeObservability,
        useRealtimeObservabilityStore
    }));
};

/**
 * The callbacks handed to the last `createSseClient` call.
 */
const lastCallbacks = () => createSseClient.mock.calls.at(-1)![2]!;

describe('useRealtimeObservability', () => {
    beforeEach(() => {
        setActivePinia(createPinia());
        vi.clearAllMocks();
    });

    afterEach(() => {
        vi.unstubAllEnvs();
    });

    describe('connect', () => {
        it('opens the endpoint from VITE_API_SSE, for every contract event name', () => {
            vi.stubEnv('VITE_API_SSE', 'https://api.example.com/observability/events');
            return loadComposable().then(({ useRealtimeObservability }) => {
                useRealtimeObservability().connect();

                expect(createSseClient).toHaveBeenCalledWith(
                    'https://api.example.com/observability/events',
                    [
                        'observability.heartbeat',
                        'observability.metrics.snapshot',
                        'observability.metrics.updated'
                    ],
                    expect.anything()
                );
            });
        });

        it('falls back to the local dev endpoint when VITE_API_SSE is unset', () => {
            vi.stubEnv('VITE_API_SSE', undefined);
            return loadComposable().then(({ useRealtimeObservability }) => {
                useRealtimeObservability().connect();

                expect(createSseClient.mock.calls[0]?.[0]).toBe(
                    'http://localhost:3000/observability/events'
                );
            });
        });

        it('reports connecting before the transport answers', () =>
            loadComposable().then(({ useRealtimeObservability, useRealtimeObservabilityStore }) => {
                const store = useRealtimeObservabilityStore();

                useRealtimeObservability().connect();

                expect(store.status).toBe('connecting');
            }));

        it('closes the previous client so a second connect cannot leave two streams open', () =>
            loadComposable().then(({ useRealtimeObservability }) => {
                const { connect } = useRealtimeObservability();

                connect();
                expect(close).not.toHaveBeenCalled();

                connect();
                expect(close).toHaveBeenCalledTimes(1);
                expect(createSseClient).toHaveBeenCalledTimes(2);
            }));
    });

    describe('transport callbacks', () => {
        it('reports open once the stream is established', () =>
            loadComposable().then(({ useRealtimeObservability, useRealtimeObservabilityStore }) => {
                const store = useRealtimeObservabilityStore();

                useRealtimeObservability().connect();
                lastCallbacks().onOpen?.();

                expect(store.status).toBe('open');
            }));

        it('records both the error status and a message the dashboard can show', () =>
            loadComposable().then(({ useRealtimeObservability, useRealtimeObservabilityStore }) => {
                const store = useRealtimeObservabilityStore();

                useRealtimeObservability().connect();
                lastCallbacks().onError?.(new Event('error'));

                expect(store.status).toBe('error');
                expect(store.lastError).toBe('SSE connection error');
            }));
    });

    describe('event routing', () => {
        it('sends a snapshot to setSnapshot and appends one snapshot entry', () =>
            loadComposable().then(({ useRealtimeObservability, useRealtimeObservabilityStore }) => {
                const store = useRealtimeObservabilityStore();
                const payload = makeEvent('2026-01-01T00:00:00.000Z');

                useRealtimeObservability().connect();
                lastCallbacks().onEvent?.('observability.metrics.snapshot', payload);

                expect(store.latestSnapshot).toEqual(payload);
                // The early return is what keeps a snapshot out of the heartbeat branch below it
                expect(store.latestHeartbeatAt).toBeUndefined();
                expect(store.latestUpdate).toBeUndefined();
                expect(store.entries).toEqual([
                    {
                        id: 'snapshot-2026-01-01T00:00:00.000Z',
                        kind: 'snapshot',
                        timestamp: '2026-01-01T00:00:00.000Z',
                        payload
                    }
                ]);
            }));

        it('sends an update to setUpdate and appends one update entry', () =>
            loadComposable().then(({ useRealtimeObservability, useRealtimeObservabilityStore }) => {
                const store = useRealtimeObservabilityStore();
                const payload = makeEvent('2026-01-01T00:01:00.000Z');

                useRealtimeObservability().connect();
                lastCallbacks().onEvent?.('observability.metrics.updated', payload);

                expect(store.latestUpdate).toEqual(payload);
                expect(store.latestSnapshot).toBeUndefined();
                expect(store.latestHeartbeatAt).toBeUndefined();
                expect(store.entries).toEqual([
                    {
                        id: 'update-2026-01-01T00:01:00.000Z',
                        kind: 'update',
                        timestamp: '2026-01-01T00:01:00.000Z',
                        payload
                    }
                ]);
            }));

        it('treats anything else as a heartbeat', () =>
            loadComposable().then(({ useRealtimeObservability, useRealtimeObservabilityStore }) => {
                const store = useRealtimeObservabilityStore();
                const payload = makeEvent('2026-01-01T00:02:00.000Z');

                useRealtimeObservability().connect();
                lastCallbacks().onEvent?.('observability.heartbeat', payload);

                expect(store.latestHeartbeatAt).toBe('2026-01-01T00:02:00.000Z');
                expect(store.latestSnapshot).toBeUndefined();
                expect(store.latestUpdate).toBeUndefined();
                expect(store.entries).toEqual([
                    {
                        id: 'heartbeat-2026-01-01T00:02:00.000Z',
                        kind: 'heartbeat',
                        timestamp: '2026-01-01T00:02:00.000Z',
                        payload
                    }
                ]);
            }));

        it('keeps the feed in arrival order across event kinds', () =>
            loadComposable().then(({ useRealtimeObservability, useRealtimeObservabilityStore }) => {
                const store = useRealtimeObservabilityStore();

                useRealtimeObservability().connect();
                const callbacks = lastCallbacks();
                callbacks.onEvent?.(
                    'observability.metrics.snapshot',
                    makeEvent('2026-01-01T00:00:00.000Z')
                );
                callbacks.onEvent?.(
                    'observability.heartbeat',
                    makeEvent('2026-01-01T00:00:30.000Z')
                );
                callbacks.onEvent?.(
                    'observability.metrics.updated',
                    makeEvent('2026-01-01T00:01:00.000Z')
                );

                expect(store.entries.map((entry) => entry.kind)).toEqual([
                    'snapshot',
                    'heartbeat',
                    'update'
                ]);
            }));
    });

    describe('disconnect', () => {
        it('closes the stream and reports closed', () =>
            loadComposable().then(({ useRealtimeObservability, useRealtimeObservabilityStore }) => {
                const store = useRealtimeObservabilityStore();
                const { connect, disconnect } = useRealtimeObservability();

                connect();
                disconnect();

                expect(close).toHaveBeenCalledTimes(1);
                expect(store.status).toBe('closed');
            }));

        it('is safe with no connection open, and does not close a stream twice', () =>
            loadComposable().then(({ useRealtimeObservability, useRealtimeObservabilityStore }) => {
                const store = useRealtimeObservabilityStore();
                const { connect, disconnect } = useRealtimeObservability();

                disconnect();
                expect(close).not.toHaveBeenCalled();
                expect(store.status).toBe('closed');

                connect();
                disconnect();
                disconnect();
                expect(close).toHaveBeenCalledTimes(1);
            }));

        it('reconnects after a disconnect without closing the released client again', () =>
            loadComposable().then(({ useRealtimeObservability }) => {
                const { connect, disconnect } = useRealtimeObservability();

                connect();
                disconnect();
                connect();

                expect(close).toHaveBeenCalledTimes(1);
                expect(createSseClient).toHaveBeenCalledTimes(2);
            }));
    });

    it('exposes the store state alongside the controls', () =>
        loadComposable().then(({ useRealtimeObservability, useRealtimeObservabilityStore }) => {
            const store = useRealtimeObservabilityStore();
            const { status, latestSnapshot, latestUpdate, latestHeartbeatAt, entries, lastError } =
                useRealtimeObservability();

            store.setStatus('open');
            store.setError('nope');

            expect(status.value).toBe('open');
            expect(lastError.value).toBe('nope');
            expect(latestSnapshot.value).toBeUndefined();
            expect(latestUpdate.value).toBeUndefined();
            expect(latestHeartbeatAt.value).toBeUndefined();
            expect(entries.value).toEqual([]);
        }));
});

tests/unit/infrastructure/http/step-up.s.source:
/**
 * The `REAUTH_REQUIRED` step-up flow, driven through the real interceptor chain — the same
 * MSW-against-a-real-server approach `http-refresh.spec.ts` uses, and for the same reason: a
 * broken park-and-retry does not throw, it just leaves a request hanging or an old-password
 * request going through un-stepped-up.
 *
 * `app/components/ReauthDialog.vue` is not mounted here — this is a unit test of the
 * INTERCEPTOR's park/replay mechanics, so the dialog's outcome is driven directly through
 * `useReauthPromptStore()`, exactly as the real component would call it.
 */
import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it, vi } from 'vitest';
import { setupServer } from 'msw/node';
import { http, HttpResponse } from 'msw';
import { createPinia, setActivePinia } from 'pinia';
import { useReauthPromptStore } from '@/infrastructure/http/reauth-prompt.ts';

const API = 'http://api.test';

interface LoggedRequest {
    route: string;
    authorization?: string;
}

/** How the protected route should answer. Reset before every case. */
interface Scenario {
    /** Whether `/checkout` still demands a fresh session. Flipped to `false` mid-test to simulate a successful reauth having rotated the session server-side. */
    requiresReauth: boolean;
}

let requestLog: LoggedRequest[] = [];
let scenario: Scenario = { requiresReauth: true };

/** A `REAUTH_REQUIRED` 401, matching what `requireFreshAuth` actually answers. */
const reauthRequired = () =>
    HttpResponse.json(
        {
            success: false,
            status: 401,
            message: 'Fresh authentication required',
            errors: [{ code: 'REAUTH_REQUIRED', message: 'Fresh authentication required' }]
        },
        { status: 401 }
    );

const server = setupServer(
    http.post(`${API}/checkout`, ({ request }) => {
        const authorization = request.headers.get('authorization') ?? undefined;
        requestLog.push({ route: 'POST /checkout', authorization });
        return scenario.requiresReauth
            ? reauthRequired()
            : HttpResponse.json({ success: true, status: 200, data: { orderId: 'o1' } });
    })
);

const loadHttp = () => {
    vi.resetModules();
    vi.stubEnv('VITE_API_URL', API);
    return import('@/infrastructure/http');
};

const routes = () => requestLog.map(({ route }) => route);
const timesRequested = (route: string) => requestLog.filter((r) => r.route === route).length;

/**
 * Waits until the step-up prompt is open — the interceptor's `requestStepUp()` runs after at
 * least one microtask past the mocked 401, so a bare `Promise.resolve().then()` is not reliably
 * late enough.
 *
 * @returns A promise resolving once `useReauthPromptStore().isOpen` is `true`.
 */
const waitForPrompt = () => vi.waitFor(() => expect(useReauthPromptStore().isOpen).toBe(true));

beforeAll(() => server.listen({ onUnhandledRequest: 'error' }));
afterEach(() => server.resetHandlers());
afterAll(() => server.close());

beforeEach(() => {
    setActivePinia(createPinia());
    requestLog = [];
    scenario = { requiresReauth: true };
    vi.unstubAllEnvs();
});

describe('the REAUTH_REQUIRED step-up flow', () => {
    it('parks the request, opens the prompt, and replays once it resolves', () => {
        // The session is "fresh" again by the time the dialog resolves — a real reauth rotated it.
        return loadHttp().then(({ orvalMutator }) => {
            const pending = orvalMutator({ url: '/checkout', method: 'POST', data: {} });

            return waitForPrompt()
                .then(() => {
                    scenario.requiresReauth = false;
                    useReauthPromptStore().resolveStepUp();
                    return pending;
                })
                .then(() => {
                    expect(routes()).toEqual(['POST /checkout', 'POST /checkout']);
                    expect(useReauthPromptStore().isOpen).toBe(false);
                });
        });
    });

    it('shares one prompt between two REAUTH_REQUIRED 401s that arrive together', () =>
        loadHttp().then(({ orvalMutator }) => {
            const first = orvalMutator({ url: '/checkout', method: 'POST', data: {} });
            const second = orvalMutator({ url: '/checkout', method: 'POST', data: {} });

            return waitForPrompt()
                .then(() => {
                    scenario.requiresReauth = false;
                    useReauthPromptStore().resolveStepUp();
                    return Promise.all([first, second]);
                })
                .then(() => {
                    // Two calls in, one prompt, both replayed: four requests total, never a fifth.
                    expect(timesRequested('POST /checkout')).toBe(4);
                });
        }));

    it('rejects the parked request when the prompt is cancelled', () =>
        loadHttp().then(({ orvalMutator }) => {
            const pending = orvalMutator({ url: '/checkout', method: 'POST', data: {} });

            return waitForPrompt()
                .then(() => {
                    useReauthPromptStore().rejectStepUp(new Error('REAUTH_CANCELLED'));
                    return expect(pending).rejects.toMatchObject({
                        errors: [{ code: 'REAUTH_REQUIRED' }]
                    });
                })
                .then(() => {
                    // Never replayed: the visitor walked away instead of proving their password.
                    expect(timesRequested('POST /checkout')).toBe(1);
                });
        }));

    it('does not retry a second time when the replay still demands a fresh session', () =>
        loadHttp().then(({ orvalMutator }) => {
            // requiresReauth stays true — the replay 401s again too.
            const pending = orvalMutator({ url: '/checkout', method: 'POST', data: {} });

            return waitForPrompt()
                .then(() => {
                    useReauthPromptStore().resolveStepUp();
                    return expect(pending).rejects.toMatchObject({
                        errors: [{ code: 'REAUTH_REQUIRED' }]
                    });
                })
                .then(() => {
                    // `_dontRetry` on the replay stops a second prompt from opening.
                    expect(timesRequested('POST /checkout')).toBe(2);
                });
        }));
});

tests/unit/infrastructure/http/http-vali.source:
/**
 * `orvalMutator`'s contract-validation layer (`VITE_VALIDATE_RESPONSES`), tested against a real
 * HTTP server the same way `http-refresh.spec.ts` tests the refresh flow — a stubbed axios
 * adapter wouldn't exercise the interceptor chain the mutator actually runs through.
 */
import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it, vi } from 'vitest';
import { setupServer } from 'msw/node';
import { http, HttpResponse } from 'msw';
import { createPinia, setActivePinia } from 'pinia';

const API = 'http://api.test';

const server = setupServer();

/**
 * Load a fresh `@/infrastructure/http` and wire the enabled modules' response schemas into it, exactly as
 * `src/main.ts` does at boot.
 *
 * The registration is not optional dressing. Every domain row — `/account` included — lives in
 * `src/modules/<name>/response-schemas.ts` now, and `vi.resetModules()` gives each test a brand new
 * `responseSchemaMap` holding only the handful of core rows. Skip the wiring and
 * `resolveResponseSchema` returns `undefined`, validation quietly no-ops, and the two tests that
 * assert a *throw* fail — which is how this helper earned its existence.
 */
const loadHttp = () => {
    vi.resetModules();
    vi.stubEnv('VITE_API_URL', API);
    return Promise.all([
        import('@/infrastructure/http'),
        import('@/infrastructure/http/response-schema-map'),
        import('@/kernel/registry'),
        import('@/modules')
    ]).then(
        ([
            httpModule,
            { registerResponseSchemas },
            { collectModuleResponseSchemas },
            { enabledModules }
        ]) => {
            registerResponseSchemas(collectModuleResponseSchemas(enabledModules));
            return httpModule;
        }
    );
};

beforeAll(() => server.listen({ onUnhandledRequest: 'error' }));
afterEach(() => server.resetHandlers());
afterAll(() => server.close());

beforeEach(() => {
    setActivePinia(createPinia());
    vi.unstubAllEnvs();
});

describe('orvalMutator contract validation', () => {
    it('is off by default inside Vitest, even though DEV is true (MODE is "test")', () => {
        // A response that violates GetAccountResponse (missing required `email`) — if
        // validation ran, this would throw.
        server.use(
            http.get(`${API}/account`, () =>
                HttpResponse.json({ success: true, status: 200, message: 'ok', data: { id: '1' } })
            )
        );
        return loadHttp().then(({ orvalMutator }) =>
            expect(orvalMutator({ url: '/account', method: 'GET' })).resolves.toMatchObject({
                data: { id: '1' }
            })
        );
    });

    it('is ON by default outside Vitest — a production build validates too (MODE decides)', () => {
        // Same violating response as above; with MODE stubbed away from 'test' and no flag set,
        // the default must validate — this is what lets the stores trust `response.data`.
        server.use(
            http.get(`${API}/account`, () =>
                HttpResponse.json({ success: true, status: 200, message: 'ok', data: { id: '1' } })
            )
        );
        vi.stubEnv('MODE', 'production');
        return loadHttp().then(({ orvalMutator }) =>
            expect(orvalMutator({ url: '/account', method: 'GET' })).rejects.toThrow(/\[contract]/)
        );
    });

    it('resolves normally when VITE_VALIDATE_RESPONSES=true and the response satisfies its schema', () => {
        server.use(
            http.get(`${API}/account`, () =>
                HttpResponse.json({
                    success: true,
                    status: 200,
                    message: 'ok',
                    data: { id: '1', email: 'a@b.com', username: 'alice' }
                })
            )
        );
        vi.stubEnv('VITE_VALIDATE_RESPONSES', 'true');
        return loadHttp().then(({ orvalMutator }) =>
            expect(orvalMutator({ url: '/account', method: 'GET' })).resolves.toMatchObject({
                data: { id: '1', email: 'a@b.com', username: 'alice' }
            })
        );
    });

    it('throws a contract error when VITE_VALIDATE_RESPONSES=true and a required field is missing', () => {
        server.use(
            http.get(`${API}/account`, () =>
                HttpResponse.json({ success: true, status: 200, message: 'ok', data: { id: '1' } })
            )
        );
        vi.stubEnv('VITE_VALIDATE_RESPONSES', 'true');
        return loadHttp().then(({ orvalMutator }) =>
            expect(orvalMutator({ url: '/account', method: 'GET' })).rejects.toThrow(
                /\[contract] response for GET \/account does not match the OpenAPI schema/
            )
        );
    });

    it('throws a contract error when the response carries an undeclared field (strict schema)', () => {
        server.use(
            http.get(`${API}/account`, () =>
                HttpResponse.json({
                    success: true,
                    status: 200,
                    message: 'ok',
                    data: {
                        id: '1',
                        email: 'a@b.com',
                        username: 'alice',
                        // Not part of the OpenAPI schema — the exact class of bug (over-serialization)
                        // this validation exists to catch.
                        passwordHash: 'should-never-be-serialized'
                    }
                })
            )
        );
        vi.stubEnv('VITE_VALIDATE_RESPONSES', 'true');
        return loadHttp().then(({ orvalMutator }) =>
            expect(orvalMutator({ url: '/account', method: 'GET' })).rejects.toThrow(/\[contract]/)
        );
    });

    it('never validates when VITE_VALIDATE_RESPONSES=false, even for a non-conformant response', () => {
        server.use(
            http.get(`${API}/account`, () =>
                HttpResponse.json({ success: true, status: 200, message: 'ok', data: { id: '1' } })
            )
        );
        vi.stubEnv('VITE_VALIDATE_RESPONSES', 'false');
        return loadHttp().then(({ orvalMutator }) =>
            expect(orvalMutator({ url: '/account', method: 'GET' })).resolves.toMatchObject({
                data: { id: '1' }
            })
        );
    });

    it('fails open (warns, does not throw) for a route absent from the schema map', () => {
        server.use(
            http.get(`${API}/not-a-real-route`, () => HttpResponse.json({ anything: 'goes' }))
        );
        vi.stubEnv('VITE_VALIDATE_RESPONSES', 'true');
        const warnSpy = vi.spyOn(console, 'warn').mockImplementation(() => {
            /* no-op */
        });
        return loadHttp()
            .then(({ orvalMutator }) =>
                expect(
                    orvalMutator({ url: '/not-a-real-route', method: 'GET' })
                ).resolves.toMatchObject({ anything: 'goes' })
            )
            .then(() => {
                expect(warnSpy).toHaveBeenCalledWith(
                    expect.stringContaining('no response schema mapped for GET /not-a-real-route')
                );
                warnSpy.mockRestore();
            });
    });
});

src/modules/account/tests/login-view-i18.source:
/**
 * @module
 * Proves a mounted view is actually wired to `usersSchema` + vue-i18n's `revalidateOn`, by
 * parsing with the real schema and reading the rendered `v-text-field` error text in two
 * languages — not a mock of either.
 */
import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { nextTick } from 'vue';
import { mount } from '@vue/test-utils';
import { createPinia } from 'pinia';
import Login from '@/modules/account/views/Login.vue';
import { i18n, loadLocale } from '@/infrastructure/i18n';
import vuetify from '@/ui/vuetify';
import { usersSchema } from '@/modules/users';
import { wireModulesIntoCore } from '../../../../tests/support/unit/wire-modules.ts';

/*
 * Login is account's view, but the field rules it renders are users' — so the expected copy is
 * derived by parsing with `usersSchema` itself, taken from the users **barrel**. That the two
 * modules agree on one set of rules is the point of `account` reaching into `users` at all.
 *
 * Reading users' locale JSON directly would be quicker and is what this spec did at first; lint
 * rejected it, correctly — a sibling's dictionary is an internal, and `@/modules/users` is the
 * whole surface account is entitled to. Parsing through the schema is also the better assertion:
 * it compares the rendered text to what the schema actually produces, rather than to a file that
 * might not be the one loaded.
 *
 * The wiring below is what puts those keys into the i18n instance at all; without it every
 * assertion here would compare a rendered key against a translation.
 */
wireModulesIntoCore();

/**
 * The message `usersSchema` produces for an invalid email, in whatever locale is active.
 */
const emailInvalidMessage = () => {
    const [message] = (
        usersSchema.safeParse({ email: 'nope', username: 'ada' }).error?.issues ?? []
    )
        .filter(({ path }) => path[0] === 'email')
        .map(({ message: text }) => text);
    // A raw key here would mean the dictionaries never loaded, which would make every
    // assertion below vacuously true.
    expect(message).not.toContain('users-form.');
    return message;
};

/**
 * One real view, end to end: the schema module, the composable, vue-i18n and the rendered
 * `v-text-field`. `tests/cross-cutting/schemas-i18n.spec.ts` proves the mechanism in isolation;
 * this proves a view is actually WIRED to it — `revalidateOn: locale` is easy to forget, and a
 * view that forgets it looks perfectly fine until someone switches language mid-form.
 *
 * vue-i18n is NOT mocked. A `t` stubbed to return its key would make both languages identical and
 * the assertion meaningless.
 */
vi.mock('vue-router', () => ({
    RouterLink: { template: '<a><slot /></a>' },
    useRoute: () => ({ fullPath: '/', params: {}, query: {} }),
    useRouter: () => ({ push: vi.fn(), replace: vi.fn() })
}));

/**
 * Mounts `Login` with the plugins and stub it needs — the DOM under test for every case below.
 */
const mountLogin = () =>
    mount(Login, {
        global: {
            plugins: [createPinia(), vuetify, i18n],
            stubs: {
                LayoutDefault: { template: '<div><slot /></div>' }
            }
        }
    });

/**
 * The Vuetify validation-message texts currently rendered in the wrapper.
 */
const errorTexts = (wrapper: ReturnType<typeof mountLogin>) =>
    wrapper.findAll('.v-messages__message').map((node) => node.text());

describe('Login view, language switched mid-form', () => {
    beforeEach(() => loadLocale('en'));
    afterEach(() => loadLocale('en'));

    it('re-translates a displayed validation error', () => {
        let english = '';
        const wrapper = mountLogin();

        return wrapper
            .get('input[type="email"]')
            .setValue('not-an-email')
            .then(() => wrapper.get('form').trigger('submit'))
            .then(() => nextTick())
            .then(() => {
                english = emailInvalidMessage();
                // Against the dictionary's literal string, not just `usersSchema`'s own output —
                // `users/locales/en.json`'s `users-form.email-invalid` drifting would fail this.
                expect(english).toBe('Must be a valid email');
                expect(errorTexts(wrapper)).toContain(english);
                return loadLocale('it');
            })
            .then(() => nextTick())
            .then(() => {
                const italian = emailInvalidMessage();
                expect(italian).toBe("Deve essere un'email valida");
                // Both halves matter: the Italian message is on screen AND the English one is
                // gone. Asserting only the first would pass on a field that renders both.
                expect(italian).not.toBe(english);
                expect(errorTexts(wrapper)).toContain(italian);
                expect(errorTexts(wrapper)).not.toContain(english);
            });
    });

    it('does not put errors on a pristine form just because the language changed', () => {
        const wrapper = mountLogin();

        return loadLocale('it')
            .then(() => nextTick())
            .then(() => {
                expect(errorTexts(wrapper)).toEqual([]);
            });
    });
});

tests/unit/ui/form-image-upload.spec.ts.source:
/**
 * `FormImageUpload.vue` — the component the plan ranks first by risk.
 *
 * `utils/uploads.ts` (the limits and the predicates) is well tested and now carries property
 * tests too. The component WRAPPING it was not tested at all, and the thing it owns is not
 * validation — it is a **resource**.
 *
 * `URL.createObjectURL` pins the picked blob in memory until `revokeObjectURL` releases it. The
 * component holds the URL in a ref precisely so it can revoke it, and there are three moments
 * where failing to do so leaks a whole image:
 *
 *   1. replacing one pick with another,
 *   2. clearing the field,
 *   3. unmounting while a file is picked.
 *
 * None of the three shows up as a failing assertion anywhere else, and none is visible in the UI
 * — it is a long editing session quietly holding a dozen images. So all three are asserted here
 * against a counted stub, which is the only way to see a revoke that did not happen.
 *
 * The other behaviours worth pinning are the two that a naive implementation gets backwards:
 * `progress === 0` must SHOW the bar (a request that has started and sent nothing) while
 * `undefined` hides it; and an array selection must be collapsed back into the model, because
 * every `imageUpload` field in the contract declares a single file.
 */
import { asStub } from '../../support/stub';
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { mount } from '@vue/test-utils';
import FormImageUpload from '@/ui/molecules/FormImageUpload.vue';
import vuetify from '@/ui/vuetify';
import { i18n } from '@/infrastructure/i18n';
import { ACCEPTED_IMAGE_ACCEPT_ATTRIBUTE } from '@/infrastructure/utils/uploads';
import { instance } from '@/infrastructure/http/client';

/**
 * What a stored image's path becomes in `src`.
 *
 * The API answers an upload with a path relative to ITSELF (`/images/…`), and the browser would
 * resolve that against THIS app's origin — a 404 on every deployment where the two differ. The
 * preview therefore prefixes the API's own origin, and the expectation is built from the axios
 * instance rather than written out, so a spec cannot pass by agreeing with a stale `.env`.
 *
 * @param path - The path as the API returned it.
 * @returns The absolute URL the preview should show.
 */
const served = (path: string) => `${String(instance.defaults.baseURL)}${path}`;

/** Object-URL bookkeeping, so a missing revoke is observable. */
const created: string[] = [];
const revoked: string[] = [];

beforeEach(() => {
    created.length = 0;
    revoked.length = 0;
    let counter = 0;
    globalThis.URL.createObjectURL = vi.fn(() => {
        counter += 1;
        const url = `blob:mock/${counter}`;
        created.push(url);
        return url;
    });
    globalThis.URL.revokeObjectURL = vi.fn((url: string) => {
        revoked.push(url);
    });
});

afterEach(() => {
    vi.restoreAllMocks();
});

const makeFile = (name = 'photo.png', type = 'image/png') =>
    new File([new Uint8Array([1, 2, 3])], name, { type });

const mountUpload = (props: Record<string, unknown> = {}) =>
    mount(FormImageUpload, {
        props,
        global: { plugins: [vuetify, i18n] }
    });

describe('FormImageUpload — the object-URL resource', () => {
    it('mints exactly one object URL for a picked file', async () => {
        const wrapper = mountUpload();

        await wrapper.setProps({ modelValue: makeFile() });
        await wrapper.vm.$nextTick();

        expect(created).toHaveLength(1);
    });

    it('revokes the previous URL when the pick is REPLACED', async () => {
        // The leak that is easiest to miss: clearing is usually handled, replacing is not.
        const wrapper = mountUpload();

        await wrapper.setProps({ modelValue: makeFile('first.png') });
        await wrapper.vm.$nextTick();
        await wrapper.setProps({ modelValue: makeFile('second.png') });
        await wrapper.vm.$nextTick();

        expect(created).toHaveLength(2);
        expect(revoked).toContain(created[0]);
    });

    it('revokes the URL when the field is cleared', async () => {
        const wrapper = mountUpload();

        await wrapper.setProps({ modelValue: makeFile() });
        await wrapper.vm.$nextTick();
        await wrapper.setProps({ modelValue: undefined });
        await wrapper.vm.$nextTick();

        expect(revoked).toContain(created[0]);
    });

    it('revokes the URL on unmount, rather than leaking it with the component', async () => {
        const wrapper = mountUpload();

        await wrapper.setProps({ modelValue: makeFile() });
        await wrapper.vm.$nextTick();
        wrapper.unmount();

        expect(revoked).toContain(created[0]);
    });

    it('revokes nothing when nothing was ever picked', () => {
        // `releaseObjectUrl` guards on the ref; without the guard this revokes `undefined`.
        mountUpload().unmount();

        expect(revoked).toHaveLength(0);
    });
});

describe('FormImageUpload — the preview', () => {
    it('shows the existing image while nothing is picked', () => {
        const wrapper = mountUpload({ currentImageUrl: '/images/existing.png' });

        expect(wrapper.find('img').attributes('src')).toBe(served('/images/existing.png'));
    });

    it('prefers the picked file over the existing image', async () => {
        // An edit form must not keep showing the old picture after the user chose a new one.
        const wrapper = mountUpload({ currentImageUrl: '/images/existing.png' });

        await wrapper.setProps({ modelValue: makeFile() });
        await wrapper.vm.$nextTick();

        expect(wrapper.find('img').attributes('src')).toBe(created[0]);
    });

    it('renders no image at all when there is neither', () => {
        expect(mountUpload().find('img').exists()).toBe(false);
    });

    it('falls back to the existing image again once the pick is cleared', async () => {
        const wrapper = mountUpload({ currentImageUrl: '/images/existing.png' });

        await wrapper.setProps({ modelValue: makeFile() });
        await wrapper.vm.$nextTick();
        await wrapper.setProps({ modelValue: undefined });
        await wrapper.vm.$nextTick();

        expect(wrapper.find('img').attributes('src')).toBe(served('/images/existing.png'));
    });
});

/*
 * Selected by `data-testid`, never by `.v-progress-linear`: Vuetify's `v-file-input` renders its
 * own progress bar inside the field loader, so the class matches even when this component's bar
 * is absent — a spec written against it passes in both states and asserts nothing.
 */
describe('FormImageUpload — the progress bar', () => {
    it('is hidden while no upload is running', () => {
        expect(mountUpload().find('[data-testid=upload-progress]').exists()).toBe(false);
    });

    it('is SHOWN at zero percent, which is not the same as idle', async () => {
        // The distinction the component exists to make: `undefined` is idle, `0` is a request
        // that has started and sent nothing yet. A truthiness check collapses the two.
        const wrapper = mountUpload({ progress: 0 });
        await wrapper.vm.$nextTick();

        expect(wrapper.find('[data-testid=upload-progress]').exists()).toBe(true);
    });

    it('is shown while an upload is in flight', async () => {
        const wrapper = mountUpload({ progress: 42 });
        await wrapper.vm.$nextTick();

        expect(wrapper.find('[data-testid=upload-progress]').exists()).toBe(true);
    });

    it('rounds a fractional percentage', async () => {
        // Asserted on `aria-valuenow` rather than on the visible label, for two reasons: it is
        // what a screen reader actually announces, and the label is an i18n message whose
        // dictionary is lazily loaded, so in a unit test it renders as the raw key.
        const wrapper = mountUpload({ progress: 42.6 });
        await wrapper.vm.$nextTick();

        expect(wrapper.find('[data-testid=upload-progress]').attributes('aria-valuenow')).toBe(
            '43'
        );
    });

    it('reports the exact percentage when it is already whole', async () => {
        const wrapper = mountUpload({ progress: 42 });
        await wrapper.vm.$nextTick();

        expect(wrapper.find('[data-testid=upload-progress]').attributes('aria-valuenow')).toBe(
            '42'
        );
    });
});

describe('FormImageUpload — the field', () => {
    it('restricts the picker to the types the backend accepts', () => {
        // The picker's filter and the validation rule are both derived from ACCEPTED_IMAGE_TYPES
        // so they cannot disagree; this pins that the derivation actually reaches the DOM.
        expect(mountUpload().find('input[type=file]').attributes('accept')).toBe(
            ACCEPTED_IMAGE_ACCEPT_ATTRIBUTE
        );
    });

    it('surfaces validation errors passed by the form', async () => {
        const wrapper = mountUpload({ errorMessages: ['File is too large'] });
        await wrapper.vm.$nextTick();

        expect(wrapper.text()).toContain('File is too large');
    });

    it('disables the picker while the form is submitting', () => {
        expect(
            mountUpload({ disabled: true }).find('input[type=file]').attributes('disabled')
        ).toBeDefined();
    });

    it('collapses an array selection back to a single file', async () => {
        // Vuetify types VFileInput's model as `File | File[] | null` because one component covers
        // the `multiple` case. Every `imageUpload` field in the contract is a single file, so an
        // array reaching the parent would be a contract violation.
        const wrapper = mountUpload();
        const file = makeFile();

        await wrapper.setProps({ modelValue: asStub<File>([file]) });
        await wrapper.vm.$nextTick();

        const emitted = wrapper.emitted('update:modelValue');
        expect(emitted?.at(-1)?.[0]).toBe(file);
    });
});

