/**
 * `LazyImage.vue` — the four decisions every stored picture in this app now goes through.
 *
 * Three of them are invisible until they are wrong, which is why they are pinned here rather than
 * left to the visual suite:
 *
 *   1. **The placeholder is chosen by absence, not by failure.** A record with no picture and a
 *      record whose picture 404s must both end up showing the stand-in — the second only after the
 *      browser has actually given up, so a slow image is never pre-empted by the placeholder
 *      mid-load.
 *   2. **`alt` follows what is on screen.** Announcing "Photo of Blue Widget" over the placeholder
 *      icon is a lie told to exactly the visitors who cannot check it. The one exception is `alt=""`,
 *      which means decorative and has to STAY decorative in every tier — the account button in the
 *      navigation carries its own name, and an avatar that announced itself would say it twice.
 *   3. **Failure state is per-URL, not per-instance.** A `v-for` over table rows recycles one
 *      component across many records; without a reset, the first broken image in a list would
 *      leave every row after it showing the placeholder.
 *
 * The fourth — `loading="lazy"` — is a one-line attribute assertion, and it is here because it is
 * the entire performance claim the component makes.
 */
import { beforeAll, describe, expect, it } from 'vitest';
import { mount } from '@vue/test-utils';
import LazyImage from '@/ui/molecules/LazyImage.vue';
import vuetify from '@/ui/vuetify';
import { i18n, loadLocale } from '@/infrastructure/i18n';
import { instance } from '@/infrastructure/http/client';
import enMessages from '@/locales/en.json';

/**
 * The dictionary has to be loaded, and this is not boilerplate.
 *
 * Without it `t('image.placeholder-alt')` answers the KEY, the component renders the key, and an
 * assertion comparing the two agrees with itself — a green test proving only that vue-i18n is
 * consistent about failing. Asserting against the JSON is what makes it a real comparison.
 */
beforeAll(() => loadLocale('en'));

/** The wording the placeholder announces, read from the dictionary rather than duplicated. */
const PLACEHOLDER_ALT = enMessages.image['placeholder-alt'];

/**
 * @param props - Overrides for the mount.
 * @returns The mounted component.
 */
const mountImage = (props: Record<string, unknown> = {}) =>
    mount(LazyImage, {
        props: { alt: 'Photo of Blue Widget', ...props },
        global: { plugins: [vuetify, i18n] }
    });

/** The full-image layer — always the LAST `img`, under any thumbnail tier. */
const mainImage = (wrapper: ReturnType<typeof mountImage>) => wrapper.findAll('img').at(-1)!;

/** The blurred first-paint layer — absent from the DOM entirely when there is none. */
const thumbnailImage = (wrapper: ReturnType<typeof mountImage>) =>
    wrapper.find('[data-test="lazy-image-thumbnail"]');

describe('LazyImage — which picture is shown', () => {
    it('shows the record’s own image, resolved against the API origin', () => {
        const wrapper = mountImage({ src: '/images/abc.png' });

        expect(mainImage(wrapper).attributes('src')).toBe(
            `${String(instance.defaults.baseURL)}/images/abc.png`
        );
        expect(wrapper.attributes('data-placeholder')).toBeUndefined();
    });

    it('shows the placeholder when the record has no image', () => {
        const wrapper = mountImage({ src: undefined, width: 56, height: 56 });

        expect(mainImage(wrapper).attributes('src')).toBe('/images/no-image-placeholder.svg');
        expect(wrapper.attributes('data-placeholder')).toBe('true');
    });

    it('falls back to the placeholder only once the browser has given up', async () => {
        const wrapper = mountImage({ src: '/images/gone.png', width: 56, height: 56 });

        // Before the error the real URL is still on screen: a slow image must not be pre-empted.
        expect(mainImage(wrapper).attributes('src')).toContain('/images/gone.png');

        await mainImage(wrapper).trigger('error');

        expect(mainImage(wrapper).attributes('src')).toBe('/images/no-image-placeholder.svg');
    });

    it('gives a new record a clean slate after the previous one failed', async () => {
        // The `v-for` case: one component instance, many rows. Without the reset, the first
        // broken image in a list poisons every row rendered into that slot afterwards.
        const wrapper = mountImage({ src: '/images/gone.png' });
        await mainImage(wrapper).trigger('error');
        expect(wrapper.attributes('data-placeholder')).toBe('true');

        await wrapper.setProps({ src: '/images/next.png' });

        expect(wrapper.attributes('data-placeholder')).toBeUndefined();
        expect(mainImage(wrapper).attributes('src')).toContain('/images/next.png');
    });
});

describe('LazyImage — what it announces', () => {
    it('uses the caller’s alt for the record’s own image', () => {
        const wrapper = mountImage({ src: '/images/abc.png' });

        expect(mainImage(wrapper).attributes('alt')).toBe('Photo of Blue Widget');
    });

    it('says it is a stand-in when it is showing one', () => {
        const wrapper = mountImage({ src: undefined });

        expect(mainImage(wrapper).attributes('alt')).toBe(PLACEHOLDER_ALT);
        expect(mainImage(wrapper).attributes('alt')).not.toBe('Photo of Blue Widget');
        // The dictionary really did resolve — see the note on `beforeAll`.
        expect(PLACEHOLDER_ALT).not.toBe('image.placeholder-alt');
    });

    it('keeps an explicitly empty alt empty, placeholder included', () => {
        // The navigation avatar: the button already carries the accessible name.
        const wrapper = mountImage({ src: undefined, alt: '' });

        expect(mainImage(wrapper).attributes('alt')).toBe('');
    });
});

describe('LazyImage — how it loads', () => {
    it('defers the fetch until the image is near the viewport', () => {
        expect(mainImage(mountImage({ src: '/images/abc.png' })).attributes('loading')).toBe(
            'lazy'
        );
    });

    it('loads at once when the caller knows the image is above the fold', () => {
        const wrapper = mountImage({ src: '/images/abc.png', eager: true });

        expect(mainImage(wrapper).attributes('loading')).toBe('eager');
    });

    it('reserves the box before anything arrives, so a late image cannot reflow the row', () => {
        const wrapper = mountImage({ src: '/images/abc.png', width: 56, height: 72 });

        expect(wrapper.attributes('style')).toContain('width: 56px');
        expect(wrapper.attributes('style')).toContain('aspect-ratio: 56 / 72');
    });

    it('renders no thumbnail tier when the caller passes none', () => {
        // The single `img` IS the assertion: a second one would mean the component is painting a
        // blurred layer with nothing behind it.
        expect(mountImage({ src: '/images/abc.png' }).findAll('img')).toHaveLength(1);
    });
});

describe('LazyImage — the thumbnail tier', () => {
    it('paints the thumbnail, resolved against the API origin, alongside the full image', () => {
        const wrapper = mountImage({
            src: '/images/abc.png',
            thumbnailSrc: '/images/thumbs/v1/abc.webp'
        });

        expect(thumbnailImage(wrapper).exists()).toBe(true);
        expect(thumbnailImage(wrapper).attributes('src')).toBe(
            `${String(instance.defaults.baseURL)}/images/thumbs/v1/abc.webp`
        );
        expect(wrapper.findAll('img')).toHaveLength(2);
    });

    it('is decorative: empty alt and aria-hidden, so a reader never announces it', () => {
        const wrapper = mountImage({
            src: '/images/abc.png',
            thumbnailSrc: '/images/thumbs/v1/abc.webp'
        });

        expect(thumbnailImage(wrapper).attributes('alt')).toBe('');
        expect(thumbnailImage(wrapper).attributes('aria-hidden')).toBe('true');
    });

    it('is independent of `src`: a record with an image but no thumbnail shows only the full tier', () => {
        // A remote/default image, or an upload whose digest job has not finished — `thumbnailSrc`
        // is absent in both, and nothing here derives one from `src`.
        const wrapper = mountImage({ src: '/images/abc.png', thumbnailSrc: undefined });

        expect(thumbnailImage(wrapper).exists()).toBe(false);
        expect(wrapper.findAll('img')).toHaveLength(1);
    });

    it('drops the thumbnail once the full image has failed, same as the placeholder rule', async () => {
        const wrapper = mountImage({
            src: '/images/gone.png',
            thumbnailSrc: '/images/thumbs/v1/gone.webp'
        });
        expect(thumbnailImage(wrapper).exists()).toBe(true);

        await mainImage(wrapper).trigger('error');

        expect(thumbnailImage(wrapper).exists()).toBe(false);
    });
});

tests/unit/infrastructure/utils/formatte.source:
/**
 * Property-based tests — `src/infrastructure/formatters.ts` and `src/infrastructure/uploads.ts`.
 *
 * The example-based suites next door assert what these functions do for the inputs someone
 * thought of. These assert what must hold for EVERY input, which is a different question and
 * catches a different class of bug: the boundary nobody enumerated, the surrogate pair, the
 * `-0`, the string that is whitespace in a script you have never seen.
 *
 * Why this layer exists at all: it is the general form of a fix this repo already paid for the
 * expensive way. `response-schema-map.ts` was tested by sampling a handful of rows from a 52-row
 * table and scored 55% mutation with 182 survivors in that one file; replacing the sample with
 * exhaustive generation took it to ~96% and the whole suite from 55% to 81%. Sampling a space
 * you could have covered is the failure mode, and generation is the answer to it.
 *
 * TWO RULES, both non-negotiable and both about determinism:
 *
 *   1. **Every run is seeded.** `fast-check` defaults to a random seed, which makes a failure
 *      un-reproducible and — worse — makes a test that fails one run in fifty look like flake.
 *      A fixed seed means this suite either passes or fails, the same way every other test does.
 *   2. **Every counterexample becomes a regression case**, written out as an ordinary `it()` with
 *      the seed that found it in a comment. The property stays as the general statement; the
 *      example stays as the thing that once broke.
 *
 * `numRuns` is deliberately modest. These run on the pre-commit path, where the frontend gate is
 * already ~8.5 minutes; a property that needs ten thousand cases to find its bug is a property
 * that wants a nightly, not a commit hook.
 *
 * ── SPLIT WITH `formatters.spec.ts` / `uploads.spec.ts` ─────────────────────────────────────
 * Those files are example-based and own the SPECIFIC values: the exact size boundary, the
 * non-canonical `image/jpg`, the shipped copy of a message. This file owns what only generation
 * can claim — that a rule holds for EVERY input, not for the ones someone thought of.
 *
 * Check there before adding a case here. A fact asserted twice is maintained twice.
 */
import { describe, it, expect, vi, beforeEach } from 'vitest';
import fc from 'fast-check';
import {
    EMPTY_VALUE,
    formatCurrency,
    formatFlag,
    formatText,
    formatDateTime,
    formatDate
} from '@/infrastructure/utils/formatters';
import {
    ACCEPTED_IMAGE_TYPES,
    MAX_UPLOAD_BYTES,
    isAcceptedImageType,
    isWithinUploadSizeLimit
} from '@/infrastructure/utils/uploads';

/**
 * One seed for the whole file, and one place to change it.
 *
 * `endOnFailure` trims the shrunk counterexample instead of continuing to shrink for a while
 * after it has one, which keeps a failure message short enough to paste into a regression case.
 */
const RUN = { seed: 20_260_808, numRuns: 200, endOnFailure: true } as const;

/**
 * The two nullish spellings these signatures actually accept.
 *
 * `formatText(value?: string | null)`, `formatCurrency(value?: number | null)` and
 * `formatFlag(value: boolean | null | undefined, …)` all admit both, and the properties below
 * depend on both taking the fallback branch — so neither can be dropped to satisfy a lint rule
 * that would rather this codebase had only `undefined`.
 */
const nullish = () => fc.constantFrom(null, undefined);

/** The locale the formatters read. Pinned so a machine's locale cannot decide the assertions. */
vi.mock('@/infrastructure/i18n', () => ({
    getCurrentLocale: () => 'en'
}));

beforeEach(() => {
    vi.clearAllMocks();
});

describe('formatText', () => {
    it('never returns an empty or blank string, for any input', () =>
        fc.assert(
            fc.property(fc.option(fc.string(), { nil: undefined }), (value) => {
                const result = formatText(value);
                // The whole purpose of the function: a table cell always has something in it.
                expect(result.trim().length).toBeGreaterThan(0);
            }),
            RUN
        ));

    it('returns the fallback for exactly the inputs that carry no text', () =>
        fc.assert(
            fc.property(fc.option(fc.string(), { nil: undefined }), (value) => {
                // A biconditional, not two separate cases: this is the whole decision rule, and
                // asserting it both ways is what stops the boundary drifting in one direction.
                const isBlank = value === undefined || value.trim().length === 0;
                expect(formatText(value) === EMPTY_VALUE).toBe(isBlank || value === EMPTY_VALUE);
            }),
            RUN
        ));

    it('returns non-blank input UNCHANGED, rather than trimmed', () =>
        fc.assert(
            fc.property(fc.string({ minLength: 1 }), (value) => {
                fc.pre(value.trim().length > 0);
                // The emptiness test trims; the return value does not. A refactor that returned
                // `value.trim()` would pass every "is it non-empty" assertion above.
                expect(formatText(` ${value} `)).toBe(` ${value} `);
            }),
            RUN
        ));

    it('is idempotent', () =>
        fc.assert(
            fc.property(fc.option(fc.string(), { nil: undefined }), (value) => {
                expect(formatText(formatText(value))).toBe(formatText(value));
            }),
            RUN
        ));
});

describe('formatCurrency', () => {
    it('returns the fallback for every non-number, and never for a number', () =>
        fc.assert(
            fc.property(
                fc.oneof(
                    fc.double({ noNaN: true, noDefaultInfinity: true }),
                    nullish(),
                    fc.string(),
                    fc.boolean()
                ),
                (value) => {
                    const result = formatCurrency(value as number | null | undefined);
                    expect(result === EMPTY_VALUE).toBe(typeof value !== 'number');
                }
            ),
            RUN
        ));

    it('never throws, for any amount and any currency code', () =>
        fc.assert(
            fc.property(
                fc.double({ noNaN: true, noDefaultInfinity: true }),
                fc.string(),
                (value, currency) => {
                    // The `catch` in formatCurrency exists for exactly this: an unknown or
                    // malformed ISO 4217 code makes Intl throw a RangeError, and a product page
                    // must not 500 over a currency string. Generation is what reaches the codes
                    // nobody would think to write down.
                    expect(() => formatCurrency(value, currency)).not.toThrow();
                }
            ),
            RUN
        ));

    it('degrades to a plain number rather than the fallback on a bad currency', () =>
        fc.assert(
            fc.property(fc.double({ noNaN: true, noDefaultInfinity: true }), (value) => {
                // The failure path must still show the AMOUNT. Returning EMPTY_VALUE here would
                // hide a real price behind an em dash because of a config typo.
                expect(formatCurrency(value, 'not-a-currency')).not.toBe(EMPTY_VALUE);
            }),
            RUN
        ));

    it('renders every finite amount with at least one digit', () =>
        fc.assert(
            fc.property(fc.double({ noNaN: true, noDefaultInfinity: true }), (value) => {
                expect(formatCurrency(value)).toMatch(/\d/);
            }),
            RUN
        ));
});

describe('formatFlag', () => {
    it('returns one of exactly three things, and the fallback only for nullish', () =>
        fc.assert(
            fc.property(
                fc.option(fc.boolean(), { nil: undefined }),
                fc.string(),
                fc.string(),
                (value, trueLabel, falseLabel) => {
                    // The expected value is computed first and asserted once, rather than
                    // branching around two `expect`s — same property, but it states the whole
                    // decision rule as one expression.
                    //
                    // `false` is the classic place this breaks: a `!value` guard would send it
                    // down the fallback branch alongside null and undefined.
                    const expected =
                        value === undefined ? EMPTY_VALUE : value ? trueLabel : falseLabel;

                    expect(formatFlag(value, trueLabel, falseLabel)).toBe(expected);
                }
            ),
            RUN
        ));
});

describe('formatDateTime', () => {
    it('never throws, whatever string it is handed', () =>
        fc.assert(
            fc.property(fc.option(fc.string(), { nil: undefined }), (value) => {
                // The value comes off the wire. An unparseable one yields "Invalid Date", which
                // is ugly but must not be an exception in a render.
                expect(() => formatDateTime(value)).not.toThrow();
            }),
            RUN
        ));

    it('returns the fallback for every falsy input', () =>
        fc.assert(
            fc.property(fc.oneof(nullish(), fc.constant('')), (value) => {
                expect(formatDateTime(value)).toBe(EMPTY_VALUE);
            }),
            RUN
        ));
});

describe('formatDate', () => {
    it('never throws, whatever string it is handed', () =>
        fc.assert(
            fc.property(fc.option(fc.string(), { nil: undefined }), (value) => {
                // Same contract as `formatDateTime`: off-the-wire input, never an exception mid-render.
                expect(() => formatDate(value)).not.toThrow();
            }),
            RUN
        ));

    it('returns the fallback for every falsy input', () =>
        fc.assert(
            fc.property(fc.oneof(nullish(), fc.constant('')), (value) => {
                expect(formatDate(value)).toBe(EMPTY_VALUE);
            }),
            RUN
        ));

    it('is never longer than the datetime it drops the time from', () =>
        fc.assert(
            fc.property(fc.date({ noInvalidDate: true }), (date) => {
                const iso = date.toISOString();
                expect(formatDate(iso).length).toBeLessThanOrEqual(formatDateTime(iso).length);
            }),
            RUN
        ));
});

/** A File whose `type` and `size` are the only fields the upload predicates read. */
const makeFile = (type: string, size: number) => ({ type, size }) as File;

describe('upload predicates', () => {
    it('accepts a type if and only if it is on the shared list', () =>
        fc.assert(
            fc.property(fc.string(), fc.nat(), (type, size) => {
                expect(isAcceptedImageType(makeFile(type, size))).toBe(
                    (ACCEPTED_IMAGE_TYPES as readonly string[]).includes(type)
                );
            }),
            RUN
        ));

    it('is case-sensitive about the mime type, matching the backend', () =>
        fc.assert(
            fc.property(fc.constantFrom(...ACCEPTED_IMAGE_TYPES), (type) => {
                // Documented rather than assumed: the backend's fileFilter compares verbatim, so
                // a client-side check that lowercased first would accept files the server then
                // rejects — a worse experience than rejecting early.
                expect(isAcceptedImageType(makeFile(type.toUpperCase(), 1))).toBe(false);
            }),
            RUN
        ));

    it('treats the size limit as inclusive, on both sides of the boundary', () =>
        fc.assert(
            fc.property(fc.nat(), (size) => {
                expect(isWithinUploadSizeLimit(makeFile('image/png', size))).toBe(
                    size <= MAX_UPLOAD_BYTES
                );
            }),
            RUN
        ));

    /*
     * The exact boundary — `MAX_UPLOAD_BYTES` and one byte over — is NOT asserted here. It is
     * already an example in `uploads.spec.ts` ("accepts a file of exactly the limit and rejects
     * one byte more"), and restating it was a straight duplicate. The property above covers the
     * whole range; that one pins the single value `fc.nat()` would only reach by luck.
     */
});

tests/unit/ui/form-card.spec.ts.source:
/**
 * `FormCard.vue` — the card `ProductCreate` and `UserCreate` submit through.
 *
 * The component itself is markup, and markup is not what this pins. What it pins is the seam the
 * markup created: the `<form>` now lives one level below the page that owns the form state, and
 * `useAppForm` reaches it through `defineExpose`. That indirection is invisible when it breaks —
 * a page whose `formElement` resolves to `undefined` still shows its errors, it just never moves
 * focus, which is a screen-reader user submitting into silence. `tests/cross-cutting/form-idiom`
 * checks that a page PASSES a `formElement`; only this checks there is something on the other end.
 *
 * The slotted fields are asserted to be inside that same element for the same reason: focus is
 * found by querying the container, so fields rendered beside it would be fields nothing can find.
 */
import { describe, it, expect } from 'vitest';
import { mount } from '@vue/test-utils';
import { createRouter, createMemoryHistory } from 'vue-router';
import type { Ref } from 'vue';
import FormCard from '@/ui/organisms/FormCard.vue';
import vuetify from '@/ui/vuetify';

const router = createRouter({
    history: createMemoryHistory(),
    routes: [
        { path: '/:locale/products', name: 'ProductsList', component: { template: '<div />' } }
    ]
});

const mountCard = () =>
    mount(FormCard, {
        props: {
            submitLabel: 'Save',
            backTo: { name: 'ProductsList' },
            backLabel: 'Back to the list'
        },
        slots: { default: '<input class="field" name="title" />' },
        global: { plugins: [vuetify, router] }
    });

/**
 * What a parent's template ref actually receives.
 *
 * Read off `$.exposed` rather than `wrapper.vm`, and that is the entire point: a `<script setup>`
 * component is CLOSED, so `wrapper.vm` reaches its bindings whether they are exposed or not, and
 * an assertion through it passes with the `defineExpose` deleted — while the page it exists for
 * breaks.
 */
const exposedFormOf = (wrapper: ReturnType<typeof mountCard>) =>
    (wrapper.vm.$.exposed as { formElement?: Ref<HTMLFormElement | undefined> } | null)?.formElement
        ?.value;

describe('FormCard — the seam between the page and its form', () => {
    it('exposes the form element itself, not a wrapper around it', () => {
        const wrapper = mountCard();

        // What `useAppForm` receives, and what it will call `querySelector` on.
        expect(exposedFormOf(wrapper)).toBe(wrapper.find('form').element);
    });

    it('renders the slotted fields inside that element', () => {
        const wrapper = mountCard();

        expect(exposedFormOf(wrapper)?.querySelector('.field')).not.toBeNull();
    });

    it('reports a submit to the page rather than letting the browser send the form', () => {
        const wrapper = mountCard();

        return wrapper
            .find('form')
            .trigger('submit')
            .then(() => {
                expect(wrapper.emitted('submit')).toHaveLength(1);
            });
    });
});

src/modules/locales/tests/store.spec.ts.source:
/**
 * @module
 * Store tests driven by mocking `orvalMutator` and asserting on the URLs it was called with, per
 * canned `responses` keyed by `METHOD path` — same transport-mock pattern as the inventory spec.
 *
 * Worth pinning: every language write refetches the manifest BEFORE answering (the board renders
 * `LocaleCapability`, writes answer with `Language` — a different shape), and entry writes keep
 * the toolkit's search cache honest — create resets it, edit patches the record in place.
 */
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';
import { useLocalesStore } from '@/modules/locales/store.ts';
import { orvalMutator } from '@/infrastructure/http';
import { wireModulesIntoCore } from '../../../../tests/support/unit/wire-modules.ts';
import {
    orvalEnvelope,
    parseOrvalFixture
} from '../../../../tests/unit/infrastructure/http/orval-fixture-schema.ts';

wireModulesIntoCore();

/**
 * A `GET /locales` row: the merged manifest shape the board renders.
 */
const CAPABILITY = {
    tag: 'es',
    name: 'Spanish',
    nativeName: 'Español',
    direction: 'ltr',
    active: true,
    tenants: ['demo-fe'],
    source: 'dynamic',
    entryCount: 2,
    revision: 3
};

/**
 * A write response's `Language` row — the dynamic-tier record alone, not the merged manifest.
 */
const LANGUAGE = {
    id: 'language-es',
    tag: 'es',
    baseLanguage: 'es',
    name: 'Spanish',
    nativeName: 'Español',
    direction: 'ltr',
    active: true,
    revision: 3
};

/**
 * A stored entry row, as the entries endpoints answer with it.
 */
const ENTRY = {
    id: 'locale-entry-1',
    locale: 'es',
    tenant: 'demo-fe',
    key: 'generic.search',
    value: 'Buscar'
};

/**
 * The canned response for each `METHOD path` the mocked `orvalMutator` is called with, reset per test.
 */
let responses: Record<string, unknown>;

vi.mock('@/infrastructure/http', () => ({
    orvalMutator: vi.fn((config: { url: string; method: string }) => {
        const key = `${config.method?.toUpperCase()} ${config.url}`;
        return Promise.resolve(parseOrvalFixture(config.method, config.url, responses[key]));
    })
}));

/**
 * The `METHOD path` of every call the mocked `orvalMutator` received so far, in order.
 */
const requestedUrls = () =>
    vi
        .mocked(orvalMutator)
        .mock.calls.map(
            (call) =>
                `${(call[0] as { method: string }).method} ${(call[0] as { url: string }).url}`
        );

beforeEach(() => {
    setActivePinia(createPinia());
    // `reset`, not `clear`: the paging test swaps the implementation, and a reset puts the
    // table-driven one back for whatever runs after it.
    vi.resetAllMocks();
    responses = {
        'GET /locales': orvalEnvelope({ locales: [CAPABILITY], default: 'en', fallback: 'en' }),
        'POST /locales': orvalEnvelope(LANGUAGE),
        'PUT /locales/es': orvalEnvelope(LANGUAGE),
        'GET /locales/tenants': orvalEnvelope({
            tenants: [
                { id: 'demo-be', label: 'API', kind: 'backend' },
                { id: 'demo-fe', label: 'Frontend', kind: 'frontend' }
            ]
        }),
        // Bodyless per the real contract — no `data` at all — unlike the write endpoints above.
        'DELETE /locales/es': orvalEnvelope(),
        'POST /locales/es/entries': orvalEnvelope(ENTRY),
        'PUT /locales/es/entries/locale-entry-1': orvalEnvelope({ ...ENTRY, value: 'Cercar' }),
        'DELETE /locales/es/entries/locale-entry-1': orvalEnvelope(),
        'PATCH /locales/es/entries': orvalEnvelope({
            created: 2,
            updated: 1,
            removed: 0,
            revision: 4
        }),
        'PUT /locales/es/entries': orvalEnvelope({
            created: 2,
            updated: 1,
            removed: 5,
            revision: 4
        })
    };
});

describe('fetchLanguages', () => {
    it('replaces the manifest with what the API answered, defaults included', () => {
        const store = useLocalesStore();
        return store.fetchLanguages().then(() => {
            expect(store.capabilities.map(({ tag }) => tag)).toEqual(['es']);
            expect(store.defaultLocale).toBe('en');
            expect(store.fallbackLocale).toBe('en');
        });
    });
});

describe('language writes', () => {
    it('creates, then refetches the manifest before answering', () => {
        const store = useLocalesStore();
        return store
            .createLanguage({ tag: 'es', name: 'Spanish', nativeName: 'Español' })
            .then((language) => {
                expect(language).toEqual(LANGUAGE);
                expect(requestedUrls()).toEqual(['POST /locales', 'GET /locales']);
            });
    });

    it('edits without ever sending the tag in the body — it is not editable', () => {
        const store = useLocalesStore();
        return store.editLanguage('es', { name: 'Castilian' }).then(() => {
            const call = vi.mocked(orvalMutator).mock.calls[0][0] as { data?: unknown };
            expect(call.data).toEqual({ name: 'Castilian' });
            expect(requestedUrls()).toEqual(['PUT /locales/es', 'GET /locales']);
        });
    });

    it('removes, then refetches, so the board never shows a deleted language', () => {
        const store = useLocalesStore();
        return store.removeLanguage('es').then(() => {
            expect(requestedUrls()).toEqual(['DELETE /locales/es', 'GET /locales']);
        });
    });
});

describe('entry writes', () => {
    it('adds an entry against the language named in the call', () => {
        const store = useLocalesStore();
        return store
            .addEntry('es', { tenant: 'demo-fe', key: 'generic.search', value: 'Buscar' })
            .then((entry) => {
                expect(entry).toEqual(ENTRY);
                expect(requestedUrls()).toEqual(['POST /locales/es/entries']);
            });
    });

    it('edits only the value — the key is identity and stays out of the body', () => {
        const store = useLocalesStore();
        return store.editEntry('es', 'locale-entry-1', 'Cercar').then((entry) => {
            const call = vi.mocked(orvalMutator).mock.calls[0][0] as { data?: unknown };
            expect(call.data).toEqual({ value: 'Cercar' });
            expect(entry?.value).toBe('Cercar');
        });
    });

    it('routes a merge to PATCH and answers the counted result', () => {
        const store = useLocalesStore();
        return store
            .importEntries('es', 'merge', 'demo-fe', [{ key: 'a', value: 'b' }])
            .then((result) => {
                expect(requestedUrls()).toEqual(['PATCH /locales/es/entries']);
                expect(result?.removed).toBe(0);
            });
    });

    it('routes a replace to PUT — the method carries the deleting semantics', () => {
        const store = useLocalesStore();
        return store
            .importEntries('es', 'replace', 'demo-fe', [{ key: 'a', value: 'b' }])
            .then((result) => {
                expect(requestedUrls()).toEqual(['PUT /locales/es/entries']);
                expect(result?.removed).toBe(5);
            });
    });

    it('names the tenant once for the whole batch, exactly as the contract shapes it', () => {
        const store = useLocalesStore();
        return store
            .importEntries('es', 'merge', 'demo-be', [{ key: 'a', value: 'b' }])
            .then(() => {
                const call = vi.mocked(orvalMutator).mock.calls[0][0] as { data?: unknown };
                expect(call.data).toEqual({
                    tenant: 'demo-be',
                    entries: [{ key: 'a', value: 'b' }]
                });
            });
    });
});

describe('fetchAllEntries', () => {
    it('pages to completion rather than trusting one response to be everything', () => {
        const pageOne = orvalEnvelope({
            items: [ENTRY],
            meta: { page: 1, pageSize: 100, totalItems: 2, totalPages: 2 }
        });
        const pageTwo = orvalEnvelope({
            items: [{ ...ENTRY, id: 'locale-entry-2', key: 'generic.cancel' }],
            meta: { page: 2, pageSize: 100, totalItems: 2, totalPages: 2 }
        });
        let served = 0;
        responses['GET /locales/es/entries'] = undefined;
        vi.mocked(orvalMutator).mockImplementation((config: { url?: string; method?: string }) =>
            Promise.resolve(
                parseOrvalFixture(
                    config.method,
                    config.url,
                    served++ === 0 ? pageOne : pageTwo
                ) as never
            )
        );
        const store = useLocalesStore();
        return store.fetchAllEntries('es').then((entries) => {
            expect(entries?.map(({ key }) => key)).toEqual(['generic.search', 'generic.cancel']);
        });
    });
});

describe('entry search and removal', () => {
    it('searches the language the filters name, through the toolkit search cache', () => {
        const store = useLocalesStore();
        responses['GET /locales/es/entries'] = orvalEnvelope({
            items: [ENTRY],
            meta: { totalItems: 1, totalPages: 1 }
        });
        store.filters = { tag: 'es', text: 'bus', tenant: 'demo-fe' };
        return store
            .watchSearchEntries()
            .search()
            .then(() => {
                expect(requestedUrls()).toContain('GET /locales/es/entries');
            });
    });

    it("searches with an empty tag when the filters name none — the `?? ''` arm", () => {
        const store = useLocalesStore();
        responses['GET /locales//entries'] = orvalEnvelope({
            items: [],
            meta: { totalItems: 0, totalPages: 0 }
        });
        store.filters = { text: 'bus' };
        return store
            .watchSearchEntries()
            .search()
            .then(() => {
                expect(requestedUrls()).toContain('GET /locales//entries');
            });
    });

    it('removes an entry against the row named in the call', () => {
        const store = useLocalesStore();
        return store.removeEntry('es', ENTRY.id).then(() => {
            expect(requestedUrls()).toContain('DELETE /locales/es/entries/locale-entry-1');
        });
    });
});

describe('fetchApiDictionary', () => {
    it('flattens the deployed tree into dotted keys, the shape the board cells read', () => {
        responses['GET /locales/es'] = orvalEnvelope({
            locale: 'es',
            messages: { generic: { search: 'Buscar', list: ['a', 'b'] } }
        });
        return useLocalesStore()
            .fetchApiDictionary('es')
            .then((dictionary) => {
                expect(dictionary).toEqual({
                    'generic.search': 'Buscar',
                    'generic.list.0': 'a',
                    'generic.list.1': 'b'
                });
            });
    });

    it('answers an empty dictionary for a language the API has no file for', () => {
        // A dynamic-only language is the normal case for a freshly added one, not an error.
        vi.mocked(orvalMutator).mockRejectedValueOnce(new Error('404'));
        return useLocalesStore()
            .fetchApiDictionary('xx')
            .then((dictionary) => {
                expect(dictionary).toEqual({});
            });
    });
});

describe('entriesPageTotal', () => {
    it("is the server's page count for THIS search, not the local cache divided by page size", () => {
        responses['GET /locales/fr/entries'] = orvalEnvelope({
            items: [{ ...ENTRY, id: 'fr-1', locale: 'fr' }],
            meta: { page: 1, pageSize: 10, totalItems: 1, totalPages: 1 }
        });
        const store = useLocalesStore();
        store.filters = { tag: 'fr' };
        return store
            .watchSearchEntries()
            .search()
            .then(() => {
                expect(store.entriesPageTotal).toBe(1);
            });
    });
});

describe('fetchBundledDictionary', () => {
    it('flattens the bundled dictionary of a shipped language', () =>
        useLocalesStore()
            .fetchBundledDictionary('en')
            .then((dictionary) => {
                expect(dictionary['generic.search']).toBe('Search');
            }));

    it('answers an empty dictionary for a language this build does not ship', () =>
        useLocalesStore()
            .fetchBundledDictionary('kl')
            .then((dictionary) => {
                expect(dictionary).toEqual({});
            }));
});

describe('the tenant registry', () => {
    it('loads the tenants and names the backend one', () => {
        const store = useLocalesStore();
        return store.fetchTenants().then(() => {
            expect(store.tenants.map(({ id }) => id)).toEqual(['demo-be', 'demo-fe']);
            expect(store.backendTenant).toBe('demo-be');
            expect(store.tenantLabel('demo-be')).toBe('API');
            // A stranger renders as its id rather than as nothing.
            expect(store.tenantLabel('nobody')).toBe('nobody');
        });
    });

    it("knows this build's own tenant without asking the API", () => {
        expect(useLocalesStore().ownTenant).toBe('demo-fe');
    });
});

tests/unit/infrastructure/http/client.sp.source:
/**
 * The shared axios instance's configuration — `src/infrastructure/http/client.ts`.
 *
 * Both defaults are read from the environment at import time and both have a fallback, which is
 * exactly the shape that goes wrong silently: a missing `VITE_API_URL` that resolved to
 * `undefined` would make every relative call hit the dev server instead of the API, and a
 * missing timeout would make a hung request hang forever. So each arm is loaded on its own.
 */
import { afterEach, describe, expect, it, vi } from 'vitest';

/**
 * Imports the client fresh, so the module-scope env reads run again.
 *
 * @param environment - Variables to stub before the import; anything omitted is unset.
 * @returns The freshly imported module.
 */
const loadClient = (environment: Record<string, string | undefined>) => {
    vi.resetModules();
    for (const [key, value] of Object.entries(environment))
        if (value === undefined) vi.stubEnv(key, undefined);
        else vi.stubEnv(key, value);
    return import('@/infrastructure/http/client.ts');
};

afterEach(() => {
    vi.unstubAllEnvs();
});

describe('axios instance defaults', () => {
    it('takes the base URL and timeout from the environment', () => {
        return loadClient({ VITE_API_URL: 'http://api.test', VITE_AXIOS_TIMEOUT: '2500' }).then(
            ({ instance }) => {
                expect(instance.defaults.baseURL).toBe('http://api.test');
                expect(instance.defaults.timeout).toBe(2500);
            }
        );
    });

    it('falls back to same-origin relative calls and a ten second timeout', () => {
        return loadClient({ VITE_API_URL: undefined, VITE_AXIOS_TIMEOUT: undefined }).then(
            ({ instance }) => {
                // Empty string, not undefined: axios treats an undefined baseURL as "no prefix",
                // which is the same result by accident rather than by decision.
                expect(instance.defaults.baseURL).toBe('');
                expect(instance.defaults.timeout).toBe(10_000);
            }
        );
    });

    it('sends credentials, so the httpOnly refresh cookie travels with every call', () => {
        return loadClient({}).then(({ instance }) => {
            expect(instance.defaults.withCredentials).toBe(true);
        });
    });
});

src/modules/account/tests/profile.spec.t.source:
/**
 * @module
 * Unit tests for the profile store's flows: fetch/update the record, the role-view widget, the
 * live password change, email verification, and account deletion. Mocks only the transport and
 * keys answers by request URL, so every layer above it — the generated client, `session.ts`, the
 * observability store, `useStructureRestApi` — runs for real.
 *
 * A few cases need a session established first (`updateOwnRole`'s refetch, deletion's "must not
 * touch the session yet"), so those log in through the real `useAuthStore().login` first, exactly
 * like a real caller would.
 */
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';

import { useProfileStore } from '@/modules/account/stores/profile.ts';
import { useAuthStore } from '@/modules/account/stores/auth.ts';
import { useSessionStore } from '@/infrastructure/session.ts';
import { orvalMutator } from '@/infrastructure/http';
import { wireModulesIntoCore } from '../../../../tests/support/unit/wire-modules.ts';
import {
    orvalEnvelope,
    parseOrvalFixture
} from '../../../../tests/unit/infrastructure/http/orval-fixture-schema.ts';

wireModulesIntoCore();

/**
 * A representative user record, used across the fetch/update/role assertions below.
 */
const USER = { id: 'u1', username: 'ada', email: 'ada@example.com', admin: false };

/**
 * Responses per endpoint, rebuilt for each test so one case cannot leak into the next.
 *
 * Keyed by `METHOD /path` and consulted by the mock below. A test that needs a different answer
 * overwrites one entry rather than re-mocking the module, which keeps the default shape — the one
 * every other test relies on — in exactly one place.
 */
let responses: Record<string, unknown>;

vi.mock('@/infrastructure/http', () => ({
    orvalMutator: vi.fn((config: { url: string; method: string }) => {
        const key = `${config.method?.toUpperCase()} ${config.url}`;
        return Promise.resolve(parseOrvalFixture(config.method, config.url, responses[key]));
    })
}));

/**
 * Every request URL handed to the transport, in order.
 */
const requestedUrls = () =>
    vi.mocked(orvalMutator).mock.calls.map((call) => (call[0] as { url: string }).url);

beforeEach(() => {
    setActivePinia(createPinia());
    vi.clearAllMocks();
    responses = {
        // Wrapped under `data`, as `LoginResponseEnvelope` declares — the only shape
        // `getTokenFromResponse` reads.
        'POST /account/login': orvalEnvelope({ token: 'jwt-token' }),
        'GET /account': orvalEnvelope(USER),
        'DELETE /account': orvalEnvelope(),
        'DELETE /account/delete-confirm': orvalEnvelope(),
        'PUT /account': orvalEnvelope({ ...USER, username: 'ada2' }),
        // `updateOwnRole` routes through the admin users endpoint, not `/account` — see below.
        'PUT /users/u1': orvalEnvelope({ ...USER, admin: true }),
        // The envelope the real endpoint answers: a fresh access token for this session.
        'POST /account/password': orvalEnvelope({ token: 'rotated-jwt' }),
        'POST /account/verify-request': orvalEnvelope(),
        'POST /account/verify-confirm': orvalEnvelope()
    };
});

describe('fetchProfile', () => {
    it('selects the identifier the profile updates address', () =>
        useProfileStore()
            .fetchProfile(true)
            .then(() => {
                // `updateProfile` rejects without this, so a fetch that loads the record but does
                // not select it leaves the store readable and unwritable.
                expect(useProfileStore().profile).toMatchObject({ id: 'u1' });
            }));

    it('publishes the viewer without a login having happened', () =>
        // The restore path: a returning visitor holds a refresh cookie, so `tryRestoreAuth` calls
        // this directly and the guards depend on it filling the projection.
        useProfileStore()
            .fetchProfile(true)
            .then(() => {
                expect(useSessionStore().viewer).toMatchObject({ id: 'u1' });
            }));

    it('leaves the viewer alone when the response carries no payload', () => {
        // `data` is required by the real contract, so this exact payload is impossible against
        // it — it bypasses `parseOrvalFixture` on purpose to pin the store's OWN defence for
        // that state, same as `addresses.spec.ts`'s book-less case.
        vi.mocked(orvalMutator).mockImplementationOnce(() =>
            Promise.resolve({ success: true, status: 200, message: 'OK', data: undefined })
        );

        return useProfileStore()
            .fetchProfile(true)
            .then(() => {
                expect(useSessionStore().viewer).toBeUndefined();
                expect(useSessionStore().isAuth).toBe(false);
            });
    });
});

describe('updateProfile', () => {
    it('rejects when no profile has been loaded', () =>
        // Not a thrown error: the caller is a form submit handler, and an unhandled rejection here
        // would surface as a silent no-op on the button.
        expect(useProfileStore().updateProfile({ username: 'ada2' })).rejects.toThrow(
            'invalid user'
        ));

    it('sends only the fields a user owns, to the self-service endpoint', () => {
        const store = useProfileStore();

        return store
            .fetchProfile(true)
            .then(() => store.updateProfile({ username: 'ada2', admin: true }))
            .then(() => {
                // The write, not the refetch that follows it — `updateProfile` re-reads the
                // record afterwards, so the LAST call is a GET.
                const last = vi
                    .mocked(orvalMutator)
                    .mock.calls.map(
                        (call) =>
                            call[0] as {
                                url: string;
                                method: string;
                                data: Record<string, unknown>;
                            }
                    )
                    .find(({ method }) => method?.toUpperCase() === 'PUT')!;

                // PUT /account, never the admin write: routing self-service through
                // `/users/{id}` answers 403 for anyone who is not an admin — every visitor
                // editing their own record.
                expect(last.url).toBe('/account');
                // `admin` was passed in and must NOT reach the wire: a user editing their own
                // record cannot promote themselves, and the store is the only thing enforcing it.
                expect(Object.keys(last.data).toSorted()).toEqual(
                    ['email', 'username', 'locale', 'imageUrl', 'phone', 'website'].toSorted()
                );
                expect(last.data.username).toBe('ada2');
            });
    });
});

describe('locale preference', () => {
    it('persists the chosen language through PUT /account', () => {
        const store = useProfileStore();

        return store
            .fetchProfile(true)
            .then(() => store.updateProfile({ locale: 'it' }))
            .then(() => {
                const put = vi
                    .mocked(orvalMutator)
                    .mock.calls.map(
                        (call) =>
                            call[0] as { method?: string; url: string; data?: { locale?: string } }
                    )
                    .find(
                        (call) => call.method?.toUpperCase() === 'PUT' && call.url === '/account'
                    );
                // The record carries the language, so the next login can re-apply it.
                expect(put?.data?.locale).toBe('it');
            });
    });
});

/**
 * The role change is the one profile edit that does NOT go to `PUT /account`, and that is the
 * whole point of it: the self-service payload carries no role, so a role change has to be made
 * where the API can authorise it. These pin the endpoint and the projection, because getting
 * either wrong is silent — the form would look like it worked.
 */
describe('own role', () => {
    it('goes to the admin users endpoint, never to the self-service one', () => {
        const store = useProfileStore();

        return store
            .fetchProfile(true)
            .then(() => store.updateOwnRole(true))
            .then(() => {
                const put = vi
                    .mocked(orvalMutator)
                    .mock.calls.map(
                        (call) =>
                            call[0] as {
                                method?: string;
                                url: string;
                                data?: { admin?: boolean };
                            }
                    )
                    .find((call) => call.method?.toUpperCase() === 'PUT');

                // `PUT /account` is deliberately roleless; `/users/{id}` is behind the admin
                // guard, so the API decides whether this visitor may promote anyone.
                expect(put?.url).toBe('/users/u1');
                expect(put?.data).toEqual({ admin: true });
            });
    });

    it('refetches the record, so the shell learns the role from the server', () => {
        const profile = useProfileStore();

        return useAuthStore()
            .login('ada@example.com', 'hunter2hunter2')
            .then(() => {
                expect(useSessionStore().isAdmin).toBe(false);
                // What the server holds AFTER the write. The projection must follow this, not the
                // value the form happened to send.
                responses['GET /account'] = orvalEnvelope({ ...USER, admin: true });
                return profile.updateOwnRole(true);
            })
            .then(() => {
                expect(requestedUrls().at(-1)).toBe('/account');
                expect(useSessionStore().isAdmin).toBe(true);
            });
    });

    it('refuses when no profile is loaded, rather than writing to `/users/undefined`', () =>
        expect(useProfileStore().updateOwnRole(true)).rejects.toThrow('invalid user'));
});

describe('the account deletion flow', () => {
    it('requests deletion without touching the session', () => {
        const profile = useProfileStore();

        return useAuthStore()
            .login('ada@example.com', 'hunter2hunter2')
            .then(() => profile.requestAccountDelete())
            .then(() => {
                // Only a token has been emailed at this point. Signing the visitor out here would
                // strand them holding a confirmation link they can no longer use.
                expect(requestedUrls().at(-1)).toBe('/account');
                expect(useSessionStore().isAuth).toBe(true);
            });
    });

    it('clears the session once deletion is confirmed', () => {
        const profile = useProfileStore();

        return useAuthStore()
            .login('ada@example.com', 'hunter2hunter2')
            .then(() => profile.confirmAccountDelete('delete-token'))
            .then(() => {
                const session = useSessionStore();

                expect(requestedUrls().at(-1)).toBe('/account/delete-confirm');
                expect(session.accessToken).toBeUndefined();
                expect(session.isAuth).toBe(false);
                expect(profile.profile).toBeUndefined();
            });
    });
});

describe('the self-service actions', () => {
    it('changePassword sends all three fields and adopts the rotated access token', () =>
        useProfileStore()
            .changePassword('old-secret', 'new-secret', 'new-secret')
            .then(() => {
                const last = vi.mocked(orvalMutator).mock.calls.at(-1)![0] as {
                    url: string;
                    data: Record<string, unknown>;
                };
                expect(last.url).toBe('/account/password');
                expect(Object.keys(last.data).toSorted()).toEqual(
                    ['currentPassword', 'password', 'passwordConfirm'].toSorted()
                );
                // The API revoked every other session and re-keyed this one; running on with the
                // old token is the regression this pins against.
                expect(useSessionStore().accessToken).toBe('rotated-jwt');
            }));

    it('confirmEmailVerification refetches the profile only for a live session', () => {
        const profile = useProfileStore();
        // Guest first: spend a token with no session — no profile call may follow.
        return profile
            .confirmEmailVerification('a-token')
            .then(() => {
                expect(requestedUrls()).toEqual(['/account/verify-confirm']);
            })
            .then(() => useAuthStore().login('ada@example.com', 'hunter2hunter2'))
            .then(() => profile.confirmEmailVerification('a-token'))
            .then(() => {
                // Authenticated: the freshly verified record is pulled back in.
                expect(requestedUrls().at(-1)).toBe('/account');
            });
    });

    it('requestEmailVerification asks for the re-send', () =>
        useProfileStore()
            .requestEmailVerification()
            .then(() => {
                expect(requestedUrls().at(-1)).toBe('/account/verify-request');
            }));
});

