/**
 * @module
 * Unit tests for the users store, mocking `orvalMutator` directly (the multipart encoding lives
 * in the generated client) and inspecting the raw requests sent by the store's actions. Same
 * shape as the products store, including why `@api` is not mocked — the multipart encoding lives
 * in the generated client, so the transport is mocked instead.
 *
 * One extra thing is asserted here that has no products equivalent: `updateUser` receives a
 * password, and a password must not end up parked in client-side store state.
 *
 * Each `it` RETURNS its chain rather than awaiting — vitest fails a test whose returned promise
 * rejects, so the assertions inside a `.then` are as binding as awaited ones. See
 * `docs/tools/unit-testing.md`.
 */
import { asStub } from '../../../../tests/support/stub';
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';

import { useUsersStore } from '@/modules/users/store';
import { orvalMutator } from '@/infrastructure/http';
import { wireModulesIntoCore } from '../../../../tests/support/unit/wire-modules.ts';
import {
    orvalEnvelope,
    parseOrvalFixture
} from '../../../../tests/unit/infrastructure/http/orval-fixture-schema.ts';

wireModulesIntoCore();

vi.mock('@/infrastructure/http', () => ({
    // A delete answers with no `data` at all — every OTHER write here answers with the record —
    // so the method picks which envelope shape this default resolves.
    orvalMutator: vi.fn((config: { url: string; method: string }) =>
        Promise.resolve(
            parseOrvalFixture(
                config.method,
                config.url,
                config.method?.toUpperCase() === 'DELETE'
                    ? orvalEnvelope()
                    : orvalEnvelope({ id: 'u1', username: 'ada', email: 'ada@example.com' })
            )
        )
    )
}));

/**
 * The axios config handed to orvalMutator on its most recent call.
 */
const lastRequest = () => {
    const call = vi.mocked(orvalMutator).mock.calls.at(-1);
    if (!call) throw new Error('orvalMutator was never called');
    return call[0] as { url: string; method: string; data: unknown };
};

/**
 * As above, asserting the body was multipart-encoded.
 */
const lastFormData = () => {
    const { data } = lastRequest();
    if (!(data instanceof FormData)) throw new Error('last request body was not FormData');
    return data;
};

/**
 * Makes the transport answer with a paginated envelope for this test. `meta` matches the real
 * `PaginationMeta` shape — `search:` (`store.ts`) reads `meta.totalPages` for `pageTotal`, so an
 * envelope without one no longer represents a real response.
 */
const respondWithItems = (items: unknown[]) =>
    vi.mocked(orvalMutator).mockImplementation((config: { url?: string; method?: string }) =>
        Promise.resolve(
            parseOrvalFixture(
                config.method,
                config.url,
                orvalEnvelope({
                    items,
                    meta: { page: 1, pageSize: 10, totalItems: items.length, totalPages: 1 }
                })
            )
        )
    );

/**
 * The query parameters of the most recent request.
 */
/**
 * The JSON body of the most recent request — what `POST /users/search` reads.
 */
const lastBody = () => asStub<{ data: Record<string, unknown> }>(lastRequest()).data;

describe('useUsersStore', () => {
    beforeEach(() => {
        setActivePinia(createPinia());
        vi.clearAllMocks();
    });

    describe('createUser', () => {
        it('posts JSON when no avatar is attached', () =>
            useUsersStore()
                .createUser({
                    email: 'ada@example.com',
                    username: 'ada',
                    password: 'password123'
                })
                .then(() => {
                    const request = lastRequest();
                    expect(request).toMatchObject({ url: '/users', method: 'POST' });
                    expect(request.data).not.toBeInstanceOf(FormData);
                    expect(request.data).toMatchObject({
                        email: 'ada@example.com',
                        username: 'ada'
                    });
                }));

        it('posts multipart to /users when an avatar is attached', () =>
            useUsersStore()
                .createUser({
                    email: 'ada@example.com',
                    username: 'ada',
                    password: 'password123',
                    imageUpload: new Blob(['x'])
                })
                .then(() => {
                    expect(lastRequest()).toMatchObject({ url: '/users', method: 'POST' });
                    expect(lastFormData().get('email')).toBe('ada@example.com');
                }));

        it('sends a Blob avatar, not only a File', () =>
            // The contract types the field as Blob, and encoders that recurse into anything that
            // is not a File (axios' `toFormData` among them) drop a plain Blob silently.
            useUsersStore()
                .createUser({
                    email: 'ada@example.com',
                    username: 'ada',
                    password: 'password123',
                    imageUpload: new Blob(['x'])
                })
                .then(() => {
                    expect(lastFormData().get('imageUpload')).toBeInstanceOf(Blob);
                }));

        it('omits unset optional fields instead of sending the string "undefined"', () =>
            useUsersStore()
                .createUser({
                    email: 'ada@example.com',
                    username: 'ada',
                    password: 'password123',
                    admin: undefined,
                    imageUpload: new Blob(['x'])
                })
                .then(() => {
                    const formData = lastFormData();
                    expect(formData.has('admin')).toBe(false);
                    expect([...formData.values()]).not.toContain('undefined');
                }));
    });

    describe('updateUser', () => {
        it('puts JSON when no new avatar is attached', () =>
            useUsersStore()
                .updateUser('u1', { username: 'ada2' })
                .then(() => {
                    const request = lastRequest();
                    expect(request).toMatchObject({ url: '/users/u1', method: 'PUT' });
                    expect(request.data).not.toBeInstanceOf(FormData);
                    expect(request.data).toMatchObject({ username: 'ada2' });
                }));

        it('puts multipart when an avatar is attached', () =>
            useUsersStore()
                .updateUser('u1', { username: 'ada2', imageUpload: new Blob(['x']) })
                .then(() => {
                    expect(lastRequest()).toMatchObject({ url: '/users/u1', method: 'PUT' });
                    expect(lastFormData().get('username')).toBe('ada2');
                }));

        it('never parks the submitted password in store state', () => {
            const store = useUsersStore();
            store.addUser({ id: 'u1', username: 'ada', email: 'ada@example.com' });

            return store
                .updateUser('u1', { username: 'ada2', password: 'hunter2hunter2' })
                .then(() => {
                    expect(JSON.stringify(store.users)).not.toContain('hunter2hunter2');
                });
        });

        it('never parks the uploaded Blob in store state', () => {
            const store = useUsersStore();
            store.addUser({ id: 'u1', username: 'ada', email: 'ada@example.com' });

            return store
                .updateUser('u1', { username: 'ada2', imageUpload: new Blob(['x']) })
                .then(() => {
                    expect(store.users.u1).not.toHaveProperty('imageUpload');
                });
        });

        /**
         * The reason `orvalMutator` takes a second argument at all — `UserEdit.vue` passes
         * `onUploadProgress` through it to drive its progress bar.
         */
        it('forwards the upload progress callback to the transport', () => {
            const onUploadProgress = vi.fn();

            return useUsersStore()
                .updateUser(
                    'u1',
                    { username: 'ada2', imageUpload: new Blob(['x']) },
                    { onUploadProgress }
                )
                .then(() => {
                    expect(orvalMutator).toHaveBeenCalledWith(
                        expect.anything(),
                        expect.objectContaining({ onUploadProgress })
                    );
                });
        });
    });

    describe('deleteUser', () => {
        it('calls the delete endpoint with the user id', () =>
            useUsersStore()
                .deleteUser('u1')
                .then(() => {
                    expect(lastRequest()).toMatchObject({ url: '/users/u1', method: 'DELETE' });
                }));
    });

    describe('hardDeleteUser', () => {
        /*
         * A separate method rather than a flag on `deleteUser`, because the two are not the same
         * operation: the soft form sets `deletedAt` and an admin can toggle it back, this one is
         * irreversible. Distinct names mean the destructive path cannot be reached by passing the
         * wrong boolean — so what is worth pinning is the URL, and that it differs from the soft one.
         */
        it('calls the /hard endpoint with the user id', () =>
            useUsersStore()
                .hardDeleteUser('u1')
                .then(() => {
                    expect(lastRequest()).toMatchObject({
                        url: '/users/u1/hard',
                        method: 'DELETE'
                    });
                }));

        it('is a different URL from the soft delete', () =>
            useUsersStore()
                .deleteUser('u1')
                .then(() => {
                    const soft = lastRequest()?.url;
                    return useUsersStore()
                        .hardDeleteUser('u1')
                        .then(() => {
                            expect(lastRequest()?.url).not.toBe(soft);
                        });
                }));
    });

    /**
     * Read paths — same rationale as the products store: the toolkit's pagination and caching
     * are not re-tested, but the request each wrapper builds and the envelope depth it unwraps
     * are this repo's logic. Unlike products, `watchSearchUsers` passes `id` through unrenamed,
     * which is asserted explicitly so the two stores' differing conventions stay deliberate
     * rather than becoming an accident someone "fixes" in one place.
     */
    describe('read paths', () => {
        const USER = { id: 'u1', username: 'ada', email: 'ada@example.com' };

        it('fetchUsers requests the collection and unwraps the paginated envelope', () => {
            respondWithItems([USER]);

            return useUsersStore()
                .fetchUsers()
                .then((result) => {
                    expect(lastRequest()).toMatchObject({ url: '/users', method: 'GET' });
                    expect(result).toEqual([USER]);
                });
        });

        it('fetchPaginationUsers defaults to the first page of ten', () => {
            respondWithItems([]);

            return useUsersStore()
                .fetchPaginationUsers()
                .then(() => {
                    // A paged read IS a search with no filters, so it rides the search route.
                    expect(lastRequest()).toMatchObject({
                        url: '/users/search',
                        method: 'POST',
                        data: { page: 1, pageSize: 10 }
                    });
                });
        });

        it('fetchPaginationUsers passes an explicit page and size through', () => {
            respondWithItems([]);

            return useUsersStore()
                .fetchPaginationUsers(2, 50)
                .then(() => {
                    expect(lastRequest()).toMatchObject({ data: { page: 2, pageSize: 50 } });
                });
        });

        it('fetchUser requests one user and unwraps a single-record envelope', () => {
            vi.mocked(orvalMutator).mockImplementation(
                (config: { url?: string; method?: string }) =>
                    Promise.resolve(
                        parseOrvalFixture(config.method, config.url, orvalEnvelope(USER))
                    )
            );

            return useUsersStore()
                .fetchUser('u1')
                .then((result) => {
                    expect(lastRequest()).toMatchObject({ url: '/users/u1', method: 'GET' });
                    expect(result).toEqual(USER);
                });
        });

        it('watchSearchUsers posts every supported filter to /users/search', () => {
            respondWithItems([]);
            const store = useUsersStore();
            store.filters = {
                text: 'ada',
                id: 'u1',
                email: 'ada@example.com',
                username: 'ada',
                active: true
            };

            return store
                .watchSearchUsers()
                .search()
                .then(() => {
                    expect(lastRequest()).toMatchObject({ url: '/users/search', method: 'POST' });
                    expect(lastBody()).toMatchObject({
                        text: 'ada',
                        // Passed through under its own name here — contrast with the products
                        // store, where the same field is sent as `productId`.
                        id: 'u1',
                        email: 'ada@example.com',
                        username: 'ada',
                        active: true
                    });
                });
        });

        it('watchSearchUsers keeps active:false distinct from "no filter"', () => {
            // A truthiness check on `active` would drop `false` and silently return active AND
            // inactive users when an admin asked for inactive ones only.
            respondWithItems([]);
            const store = useUsersStore();
            store.filters = { active: false };

            return store
                .watchSearchUsers()
                .search()
                .then(() => {
                    expect(lastBody().active).toBe(false);
                });
        });

        it('watchSearchUsers reports a failed search to the supplied error handler', () => {
            const failure = new Error('network down');
            vi.mocked(orvalMutator).mockRejectedValue(failure);
            const onError = vi.fn();

            return useUsersStore()
                .watchSearchUsers({ onError })
                .search()
                .catch(() => {})
                .then(() => {
                    expect(onError).toHaveBeenCalledWith(failure, expect.anything());
                });
        });
    });
});

src/modules/account/tests/two-factor-sto.source:
/**
 * @module
 * Unit tests for `useTwoFactorStore()`: the enrollment machine (setup → confirm → backup codes),
 * the login-time challenge (send → submit, adopting the session on success), the `resendAfter`
 * countdown, and a 429 surfacing untouched for the view to branch on. Mocks only the transport,
 * same pattern as `sessions.spec.ts` and `auth-session.spec.ts`.
 */
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';

import { useTwoFactorStore } from '@/modules/account/stores/two-factor.ts';
import { useSessionStore } from '@/infrastructure/session.ts';
import { orvalMutator } from '@/infrastructure/http';
import { wireModulesIntoCore } from '../../../../tests/support/unit/wire-modules.ts';
import {
    orvalEnvelope,
    parseOrvalFixture
} from '../../../../tests/unit/infrastructure/http/orval-fixture-schema.ts';

wireModulesIntoCore();

/**
 * A rejection marker: an entry shaped this way makes the mocked transport reject instead of
 * resolve, for the 429/wrong-code cases.
 */
interface RejectWith {
    __reject: unknown;
}

const isRejectWith = (value: unknown): value is RejectWith =>
    typeof value === 'object' && value !== null && '__reject' in value;

let responses: Record<string, unknown>;

vi.mock('@/infrastructure/http', () => ({
    orvalMutator: vi.fn((config: { url: string; method: string }) => {
        const key = `${config.method?.toUpperCase()} ${config.url}`;
        const entry = responses[key];
        return isRejectWith(entry)
            ? // eslint-disable-next-line @typescript-eslint/prefer-promise-reject-errors -- simulating the API's own reject envelope, a plain object, exactly as `onResponseReject` produces it
              Promise.reject(entry.__reject)
            : Promise.resolve(parseOrvalFixture(config.method, config.url, entry));
    })
}));

const requestedUrls = () =>
    vi.mocked(orvalMutator).mock.calls.map((call) => (call[0] as { url: string }).url);

const STATUS_OFF = orvalEnvelope({
    enabled: false,
    methods: [],
    available: [],
    backupCodesRemaining: 0
});

beforeEach(() => {
    setActivePinia(createPinia());
    vi.clearAllMocks();
    responses = { 'GET /account/2fa': STATUS_OFF };
});

describe('fetchStatus', () => {
    it('loads the account status', () => {
        const store = useTwoFactorStore();
        return store.fetchStatus().then(() => {
            expect(store.status).toEqual(STATUS_OFF.data);
        });
    });
});

describe('the enrollment machine', () => {
    it('a device method (no delivery) populates setup with the secret and otpauth URI', () => {
        responses['POST /account/2fa/methods/totp/setup'] = orvalEnvelope({
            method: 'totp',
            delivers: false,
            secret: 'JBSWY3DPEHPK3PXP',
            otpauthUri: 'otpauth://totp/x'
        });
        const store = useTwoFactorStore();
        return store.setupMethod('totp').then(() => {
            expect(store.setup).toMatchObject({ delivers: false, secret: 'JBSWY3DPEHPK3PXP' });
            expect(store.delivery).toBeUndefined();
        });
    });

    it('a delivered method populates setup AND starts the resend countdown', () => {
        responses['POST /account/2fa/methods/email/setup'] = orvalEnvelope({
            method: 'email',
            delivers: true,
            sentTo: 'a***a@example.com',
            resendAfter: 30,
            expiresAt: '2026-01-01T00:10:00.000Z'
        });
        const store = useTwoFactorStore();
        return store.setupMethod('email').then(() => {
            expect(store.setup).toMatchObject({ delivers: true, sentTo: 'a***a@example.com' });
            expect(store.delivery).toMatchObject({ sentTo: 'a***a@example.com', resendAfter: 30 });
            expect(store.secondsUntilResend).toBeGreaterThan(0);
        });
    });

    it('confirming the FIRST factor returns backup codes and refreshes status', () => {
        responses['POST /account/2fa/methods/email/confirm'] = orvalEnvelope({
            method: 'email',
            backupCodes: ['aaa-111', 'bbb-222'],
            backupCodesRemaining: 2
        });
        responses['GET /account/2fa'] = orvalEnvelope({
            enabled: true,
            methods: [{ method: 'email', delivers: true, target: 'a***a@example.com' }],
            available: [],
            backupCodesRemaining: 2
        });
        const store = useTwoFactorStore();
        return store.confirmMethod('email', '123456').then(() => {
            expect(store.confirmed?.backupCodes).toEqual(['aaa-111', 'bbb-222']);
            expect(store.setup).toBeUndefined();
            expect(store.status?.enabled).toBe(true);
        });
    });

    it('confirming a SECOND factor returns no backup codes — never presented as "no codes exist"', () => {
        responses['POST /account/2fa/methods/totp/confirm'] = orvalEnvelope({
            method: 'totp',
            backupCodesRemaining: 7
        });
        const store = useTwoFactorStore();
        return store.confirmMethod('totp', '123456').then((confirmed) => {
            expect(confirmed?.backupCodes).toBeUndefined();
            expect(confirmed?.backupCodesRemaining).toBe(7);
        });
    });

    it('clearSetup drops the pending enrollment and any confirmed result', () => {
        responses['POST /account/2fa/methods/totp/confirm'] = orvalEnvelope({
            method: 'totp',
            backupCodesRemaining: 7
        });
        const store = useTwoFactorStore();
        return store.confirmMethod('totp', '123456').then(() => {
            store.clearSetup();
            expect(store.setup).toBeUndefined();
            expect(store.confirmed).toBeUndefined();
        });
    });

    it('a 429 resend-too-soon rejection still reaches the caller, but starts the cooldown first', () => {
        responses['POST /account/2fa/methods/email/setup'] = {
            __reject: {
                success: false,
                status: 429,
                errors: [
                    {
                        code: 'TWO_FACTOR_RESEND_TOO_SOON',
                        message: 'wait',
                        details: { retryAfter: 12 }
                    }
                ]
            }
        };
        const store = useTwoFactorStore();
        return expect(store.setupMethod('email'))
            .rejects.toMatchObject({
                errors: [{ code: 'TWO_FACTOR_RESEND_TOO_SOON' }]
            })
            .then(() => {
                // The button must not be hammerable while the SERVER is still refusing it — the
                // countdown starts from its own `retryAfter`, not only from a successful send.
                expect(store.secondsUntilResend).toBe(12);
            });
    });

    it('a rejection with no retryAfter leaves the cooldown untouched', () => {
        responses['POST /account/2fa/methods/email/setup'] = {
            __reject: {
                success: false,
                status: 400,
                errors: [{ code: 'INVALID_METHOD', message: 'nope' }]
            }
        };
        const store = useTwoFactorStore();
        return expect(store.setupMethod('email'))
            .rejects.toMatchObject({ errors: [{ code: 'INVALID_METHOD' }] })
            .then(() => {
                expect(store.secondsUntilResend).toBe(0);
            });
    });

    it('removeMethod and disableAll each refetch status afterward', () => {
        responses['DELETE /account/2fa/methods/email'] = orvalEnvelope();
        responses['DELETE /account/2fa'] = orvalEnvelope();
        const store = useTwoFactorStore();
        return store
            .removeMethod('email', '123456')
            .then(() => store.disableAll('123456'))
            .then(() => {
                expect(requestedUrls()).toEqual([
                    '/account/2fa/methods/email',
                    '/account/2fa',
                    '/account/2fa',
                    '/account/2fa'
                ]);
            });
    });
});

describe('the resend countdown', () => {
    beforeEach(() => vi.useFakeTimers());
    afterEach(() => vi.useRealTimers());

    it('ticks down to zero and stops counting', () => {
        responses['POST /account/2fa/methods/email/setup'] = orvalEnvelope({
            method: 'email',
            delivers: true,
            sentTo: 'a***a@example.com',
            resendAfter: 2,
            expiresAt: '2026-01-01T00:10:00.000Z'
        });
        const store = useTwoFactorStore();
        return store.setupMethod('email').then(() => {
            expect(store.secondsUntilResend).toBe(2);
            vi.advanceTimersByTime(3000);
            expect(store.secondsUntilResend).toBe(0);
        });
    });
});

describe('the login-time challenge', () => {
    const MFA_OUTCOME = {
        kind: 'mfa' as const,
        challenge: 'claim-check-token',
        expiresAt: '2026-01-01T00:05:00.000Z',
        methods: [{ method: 'email', delivers: true, target: 'a***a@example.com' }],
        defaultMethod: 'email'
    };

    it('sendLoginCode delivers a code against the live challenge and tracks its resend cooldown', () => {
        const store = useTwoFactorStore();
        store.beginLoginChallenge(MFA_OUTCOME, false);
        responses['POST /account/login/2fa/send'] = orvalEnvelope({
            method: 'email',
            sentTo: 'a***a@example.com',
            resendAfter: 15,
            expiresAt: '2026-01-01T00:05:00.000Z'
        });
        return store.sendLoginCode('email').then(() => {
            const last = vi.mocked(orvalMutator).mock.calls.at(-1)![0] as {
                url: string;
                data: Record<string, unknown>;
            };
            expect(last.url).toBe('/account/login/2fa/send');
            expect(last.data).toEqual({ challenge: 'claim-check-token', method: 'email' });
            expect(store.secondsUntilResend).toBeGreaterThan(0);
        });
    });

    it('sendLoginCode also starts the cooldown from a 429s own retryAfter', () => {
        const store = useTwoFactorStore();
        store.beginLoginChallenge(MFA_OUTCOME, false);
        responses['POST /account/login/2fa/send'] = {
            __reject: {
                success: false,
                status: 429,
                errors: [
                    {
                        code: 'TWO_FACTOR_RESEND_TOO_SOON',
                        message: 'wait',
                        details: { retryAfter: 20 }
                    }
                ]
            }
        };
        return expect(store.sendLoginCode('email'))
            .rejects.toMatchObject({ errors: [{ code: 'TWO_FACTOR_RESEND_TOO_SOON' }] })
            .then(() => {
                expect(store.secondsUntilResend).toBe(20);
            });
    });

    it('submitLoginCode adopts the session — token, viewer, isAuth — and clears the challenge', () => {
        const store = useTwoFactorStore();
        store.beginLoginChallenge(MFA_OUTCOME, false);
        responses['POST /account/login/2fa'] = orvalEnvelope({ token: 'stepped-up-jwt' });
        responses['GET /account'] = orvalEnvelope({
            id: 'u1',
            username: 'ada',
            email: 'ada@example.com',
            admin: false
        });

        return store.submitLoginCode('123456').then(() => {
            const session = useSessionStore();
            expect(session.accessToken).toBe('stepped-up-jwt');
            expect(session.isAuth).toBe(true);
            expect(store.challenge).toBeUndefined();
        });
    });

    it('a backup code takes the same path — the server tells the two apart, not this store', () => {
        const store = useTwoFactorStore();
        store.beginLoginChallenge(MFA_OUTCOME, false);
        responses['POST /account/login/2fa'] = orvalEnvelope({ token: 'stepped-up-jwt' });
        responses['GET /account'] = orvalEnvelope({
            id: 'u1',
            username: 'ada',
            email: 'ada@example.com',
            admin: false
        });

        return store.submitLoginCode('backup-code-xyz').then(() => {
            const last = vi
                .mocked(orvalMutator)
                .mock.calls.find(
                    (call) => (call[0] as { url: string }).url === '/account/login/2fa'
                )![0] as { data: Record<string, unknown> };
            expect(last.data).toEqual({ challenge: 'claim-check-token', code: 'backup-code-xyz' });
        });
    });

    it('rejects rather than calling the API when there is no live challenge', () => {
        const store = useTwoFactorStore();
        return expect(store.sendLoginCode('email'))
            .rejects.toBeInstanceOf(Error)
            .then(() => expect(store.submitLoginCode('123456')).rejects.toBeInstanceOf(Error))
            .then(() => {
                expect(requestedUrls()).toEqual([]);
            });
    });

    it('clearChallenge drops the challenge and its delivery', () => {
        const store = useTwoFactorStore();
        store.beginLoginChallenge(MFA_OUTCOME, false);
        store.clearChallenge();
        expect(store.challenge).toBeUndefined();
        expect(store.delivery).toBeUndefined();
    });
});

