/**
 * @module
 * `use-dictionary-cell-editor.ts` — per-cell writes on the dictionary board.
 *
 * The store, the dialog and the notifications are faked at the module boundary, so what is
 * asserted is which of create/edit/remove a given cell state chooses and what it leaves behind.
 * The blur rules carry the most weight: three outcomes decided by the draft against the stored
 * value, and one of them — remove — deliberately unreachable from a blur.
 */
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';
import { ref } from 'vue';
import { useDictionaryCellEditor } from '@/modules/locales/composables/use-dictionary-cell-editor.ts';
import type { LocaleCapability, LocaleEntry } from '@types';

/** The column every test writes into. */
const ENGLISH = { tag: 'en', nativeName: 'English', source: 'dynamic' } as LocaleCapability;

/** The tenant a NEW entry is created in. */
const OWN_TENANT = 'demo-fe';

/** The store's three writes, re-created per test so call counts start at zero. */
const addEntry = vi.fn(() => Promise.resolve());
const editEntry = vi.fn(() => Promise.resolve());
const removeEntry = vi.fn(() => Promise.resolve());

/** What `dialogStore.confirm()` resolves with; flipped per test. */
let confirmAnswer = true;

/** Every toast raised during a test. */
let messages: string[] = [];

vi.mock('@/modules/locales/store.ts', () => ({
    useLocalesStore: () => ({
        addEntry: (...arguments_: unknown[]) => addEntry(...(arguments_ as [])),
        editEntry: (...arguments_: unknown[]) => editEntry(...(arguments_ as [])),
        removeEntry: (...arguments_: unknown[]) => removeEntry(...(arguments_ as []))
    })
}));

vi.mock('@/ui/dialog.ts', () => ({
    useDialogStore: () => ({ confirm: () => Promise.resolve(confirmAnswer) })
}));

vi.mock('@guebbit/vue-toolkit', () => ({
    useNotificationsStore: () => ({
        addMessage: (message: string) => {
            messages.push(message);
        }
    })
}));

// The i18n key is echoed back so an assertion can name the message the cell chose without
// depending on the vocabulary.
vi.mock('vue-i18n', () => ({
    useI18n: () => ({ t: (key: string) => key })
}));

vi.mock('@/infrastructure/utils/errors.ts', () => ({
    notifyErrorMessages: (addMessage: (message: string) => unknown, error: unknown) => {
        addMessage(`notified:${String(error)}`);
    }
}));

/** One stored entry, as the board's lookup returns it. */
const entry = (key: string, value: string): LocaleEntry => ({
    id: `entry-${key}`,
    locale: 'en',
    tenant: OWN_TENANT,
    key,
    value
});

/**
 * The composable wired to a fixed set of stored entries.
 *
 * `afterWrite` is a spy rather than a no-op: "the column was reloaded" is part of what a
 * successful write promises, and a mutation that drops the call is otherwise invisible.
 */
const editorWith = (
    stored: Record<string, LocaleEntry | undefined> = {},
    baselines: Record<string, string | undefined> = {}
) => {
    const afterWrite = vi.fn(() => Promise.resolve());
    const editor = useDictionaryCellEditor(
        ref(OWN_TENANT),
        (_tag, key) => stored[key],
        (_tag, key) => baselines[key],
        afterWrite
    );
    return { editor, afterWrite };
};

beforeEach(() => {
    setActivePinia(createPinia());
    vi.clearAllMocks();
    vi.useRealTimers();
    confirmAnswer = true;
    messages = [];
});

describe('handleCellBlur', () => {
    it('does nothing when the cell was never typed into', () => {
        const { editor, afterWrite } = editorWith({ greeting: entry('greeting', 'Hello') });

        expect(editor.handleCellBlur(ENGLISH, 'greeting')).toBeUndefined();
        expect(addEntry).not.toHaveBeenCalled();
        expect(editEntry).not.toHaveBeenCalled();
        expect(afterWrite).not.toHaveBeenCalled();
    });

    /**
     * "Clicked through" — focus moved on, nothing changed. A save here would write the value the
     * cell already holds on every pass of the keyboard.
     */
    it('does nothing when the draft matches the stored value', () => {
        const { editor } = editorWith({ greeting: entry('greeting', 'Hello') });
        editor.handleCellInput(ENGLISH, 'greeting', 'Hello');

        expect(editor.handleCellBlur(ENGLISH, 'greeting')).toBeUndefined();
        expect(editEntry).not.toHaveBeenCalled();
    });

    it('does nothing when an empty draft matches an absent entry', () => {
        const { editor } = editorWith();
        editor.handleCellInput(ENGLISH, 'greeting', '');

        expect(editor.handleCellBlur(ENGLISH, 'greeting')).toBeUndefined();
        expect(addEntry).not.toHaveBeenCalled();
    });

    it('creates an entry in the chosen tenant when the cell was empty', () => {
        const { editor, afterWrite } = editorWith();
        editor.handleCellInput(ENGLISH, 'greeting', 'Ciao');

        return editor.handleCellBlur(ENGLISH, 'greeting')!.then(() => {
            expect(addEntry).toHaveBeenCalledWith('en', {
                tenant: OWN_TENANT,
                key: 'greeting',
                value: 'Ciao'
            });
            expect(editEntry).not.toHaveBeenCalled();
            expect(afterWrite).toHaveBeenCalledWith('en');
        });
    });

    it('edits the stored entry by its own id when the cell held one', () => {
        const { editor } = editorWith({ greeting: entry('greeting', 'Hello') });
        editor.handleCellInput(ENGLISH, 'greeting', 'Ciao');

        return editor.handleCellBlur(ENGLISH, 'greeting')!.then(() => {
            expect(editEntry).toHaveBeenCalledWith('en', 'entry-greeting', 'Ciao');
            expect(addEntry).not.toHaveBeenCalled();
        });
    });

    /**
     * The rule the composable's own doc calls out: a confirmation that opens because focus moved
     * on is a dialog nobody asked for. An emptied cell left by blur just reads its stored value
     * again.
     */
    it('never removes an entry — an emptied cell only forgets its draft', () => {
        const { editor } = editorWith({ greeting: entry('greeting', 'Hello') });
        editor.handleCellInput(ENGLISH, 'greeting', '');

        expect(editor.handleCellBlur(ENGLISH, 'greeting')).toBeUndefined();
        expect(removeEntry).not.toHaveBeenCalled();
        expect(editor.drafts.value[editor.cellId('en', 'greeting')]).toBeUndefined();
    });

    it('drops the draft and shows the saved mark once a write lands', () => {
        vi.useFakeTimers();
        const { editor } = editorWith();
        const id = editor.cellId('en', 'greeting');
        editor.handleCellInput(ENGLISH, 'greeting', 'Ciao');

        return editor.handleCellBlur(ENGLISH, 'greeting')!.then(() => {
            expect(editor.savedCells.value[id]).toBe(true);
            expect(editor.drafts.value[id]).toBeUndefined();

            // The mark is transient — it must not outlive the beat it was given.
            vi.advanceTimersByTime(1500);
            expect(editor.savedCells.value[id]).toBeUndefined();
        });
    });

    it('leaves the error on the cell and raises a toast when the write fails', () => {
        editEntry.mockRejectedValueOnce(new Error('nope'));
        const { editor, afterWrite } = editorWith({ greeting: entry('greeting', 'Hello') });
        const id = editor.cellId('en', 'greeting');
        editor.handleCellInput(ENGLISH, 'greeting', 'Ciao');

        return editor.handleCellBlur(ENGLISH, 'greeting')!.then(() => {
            expect(editor.cellErrors.value[id]).toBe('locales-dictionary-page.error-save');
            expect(messages).toContain('notified:Error: nope');
            // The column is not reloaded after a failure: nothing changed to reload.
            expect(afterWrite).not.toHaveBeenCalled();
        });
    });
});

describe('handleCellInput', () => {
    it('records the draft', () => {
        const { editor } = editorWith();
        editor.handleCellInput(ENGLISH, 'greeting', 'Ci');

        expect(editor.drafts.value[editor.cellId('en', 'greeting')]).toBe('Ci');
    });

    it('clears a previous error, so a fresh attempt starts clean', () => {
        editEntry.mockRejectedValueOnce(new Error('nope'));
        const { editor } = editorWith({ greeting: entry('greeting', 'Hello') });
        const id = editor.cellId('en', 'greeting');
        editor.handleCellInput(ENGLISH, 'greeting', 'Ciao');

        return editor.handleCellBlur(ENGLISH, 'greeting')!.then(() => {
            expect(editor.cellErrors.value[id]).toBeDefined();

            editor.handleCellInput(ENGLISH, 'greeting', 'Ciao!');
            expect(editor.cellErrors.value[id]).toBeUndefined();
        });
    });
});

describe('handleCellClear', () => {
    it('removes the entry once confirmed and names the cell in the toast', () => {
        const { editor, afterWrite } = editorWith({ greeting: entry('greeting', 'Hello') });

        return editor.handleCellClear(ENGLISH, 'greeting', new Event('click'))!.then(() => {
            expect(removeEntry).toHaveBeenCalledWith('en', 'entry-greeting');
            expect(messages).toContain('locales-dictionary-page.success-remove-named');
            expect(afterWrite).toHaveBeenCalledWith('en');
        });
    });

    /**
     * A cancel has to put the cell back exactly as it was — the stored value AND the focus, which
     * the dialog took.
     */
    it('removes nothing and restores the draft when the confirmation is declined', () => {
        confirmAnswer = false;
        const { editor } = editorWith({ greeting: entry('greeting', 'Hello') });
        const id = editor.cellId('en', 'greeting');
        editor.handleCellInput(ENGLISH, 'greeting', '');

        return editor.handleCellClear(ENGLISH, 'greeting', new Event('click'))!.then(() => {
            expect(removeEntry).not.toHaveBeenCalled();
            expect(editor.drafts.value[id]).toBeUndefined();
        });
    });

    it('asks nothing when the cell has no stored entry to remove', () => {
        const { editor } = editorWith();
        editor.handleCellInput(ENGLISH, 'greeting', '');

        expect(editor.handleCellClear(ENGLISH, 'greeting', new Event('click'))).toBeUndefined();
        expect(removeEntry).not.toHaveBeenCalled();
    });

    it('returns focus to the input the event came from on cancel', () => {
        confirmAnswer = false;
        document.body.innerHTML =
            '<div class="v-field"><input id="cell" /><button id="clear"></button></div>';
        const input = document.querySelector<HTMLInputElement>('#cell')!;
        const button = document.querySelector<HTMLButtonElement>('#clear')!;
        const { editor } = editorWith({ greeting: entry('greeting', 'Hello') });

        const event = new Event('click');
        Object.defineProperty(event, 'target', { value: button });

        return editor.handleCellClear(ENGLISH, 'greeting', event)!.then(() => {
            // The click landed on the clear button; the focus belongs on the field beside it.
            expect(document.activeElement).toBe(input);
        });
    });
});

describe('handleCellEnter', () => {
    it('removes when the cell was emptied', () => {
        const { editor } = editorWith({ greeting: entry('greeting', 'Hello') });
        editor.handleCellInput(ENGLISH, 'greeting', '');

        return editor.handleCellEnter(ENGLISH, 'greeting', new Event('keydown'))!.then(() => {
            expect(removeEntry).toHaveBeenCalledOnce();
            expect(editEntry).not.toHaveBeenCalled();
        });
    });

    it('saves when the cell holds a value — the same save a blur would do', () => {
        const { editor } = editorWith({ greeting: entry('greeting', 'Hello') });
        editor.handleCellInput(ENGLISH, 'greeting', 'Ciao');

        return editor.handleCellEnter(ENGLISH, 'greeting', new Event('keydown'))!.then(() => {
            expect(editEntry).toHaveBeenCalledWith('en', 'entry-greeting', 'Ciao');
            expect(removeEntry).not.toHaveBeenCalled();
        });
    });

    it('saves rather than removes when the cell was never typed into', () => {
        const { editor } = editorWith({ greeting: entry('greeting', 'Hello') });

        // An undefined draft is not an emptied cell: Enter on an untouched cell must not confirm
        // a removal.
        expect(editor.handleCellEnter(ENGLISH, 'greeting', new Event('keydown'))).toBeUndefined();
        expect(removeEntry).not.toHaveBeenCalled();
    });
});

describe('cellLabel', () => {
    it('names the baseline the cell would replace', () => {
        const { editor } = editorWith({}, { greeting: 'Hello' });

        expect(editor.cellLabel(ENGLISH, 'greeting')).toBe(
            'locales-dictionary-page.cell-label-baseline'
        );
    });

    it('omits the baseline when the cell already holds an entry', () => {
        const { editor } = editorWith(
            { greeting: entry('greeting', 'Ciao') },
            { greeting: 'Hello' }
        );

        expect(editor.cellLabel(ENGLISH, 'greeting')).toBe('locales-dictionary-page.cell-label');
    });

    it('omits the baseline when there is none', () => {
        const { editor } = editorWith();

        expect(editor.cellLabel(ENGLISH, 'greeting')).toBe('locales-dictionary-page.cell-label');
    });
});

describe('cellId', () => {
    /**
     * The separator has to be something no BCP 47 tag can contain, or two different cells could
     * share a draft.
     */
    it('joins tag and key with a separator no tag can contain', () => {
        const { editor } = editorWith();

        expect(editor.cellId('pt-BR', 'a.b')).toBe('pt-BR|a.b');
        expect(editor.cellId('en', 'x')).not.toBe(editor.cellId('e', 'nx'));
    });
});

src/modules/account/tests/auth-session.s.source:
/**
 * @module
 * Unit tests for the auth store's session flows (login, logout, logoutEverywhere, password reset
 * request), mocking only the transport and keying answers by request URL so every layer above it
 * — the generated client, session/profile/observability stores — runs for real. `signup` is
 * covered separately, see `auth-signup.spec.ts`.
 *
 * `login` is COORDINATION rather than computation: it puts a token somewhere and asks for a
 * profile, so asserting against the real session store — rather than mocking it — asserts the
 * same thing the router guards actually read.
 */
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';

import { useAuthStore } from '@/modules/account/stores/auth.ts';
import { useProfileStore } from '@/modules/account/stores/profile.ts';
import { useSessionStore } from '@/infrastructure/session.ts';
import { orvalMutator } from '@/infrastructure/http';
import { wireModulesIntoCore } from '../../../../tests/support/unit/wire-modules.ts';
import {
    orvalEnvelope,
    parseOrvalFixture
} from '../../../../tests/unit/infrastructure/http/orval-fixture-schema.ts';

wireModulesIntoCore();

/**
 * A representative user record, used across the login/session assertions below.
 */
const USER = { id: 'u1', username: 'ada', email: 'ada@example.com', admin: false };

/**
 * Responses per endpoint, rebuilt for each test so one case cannot leak into the next.
 *
 * Keyed by `METHOD /path` and consulted by the mock below. A test that needs a different answer
 * overwrites one entry rather than re-mocking the module, which keeps the default shape — the one
 * every other test relies on — in exactly one place.
 */
let responses: Record<string, unknown>;

vi.mock('@/infrastructure/http', () => ({
    orvalMutator: vi.fn((config: { url: string; method: string }) => {
        const key = `${config.method?.toUpperCase()} ${config.url}`;
        // Unknown endpoint resolves to `undefined` rather than throwing: several actions ignore
        // their response body entirely, and forcing every one of them into the table above would
        // make the table a list of the endpoints called rather than of the answers that matter.
        return Promise.resolve(parseOrvalFixture(config.method, config.url, responses[key]));
    })
}));

/**
 * Every request URL handed to the transport, in order.
 */
const requestedUrls = () =>
    vi.mocked(orvalMutator).mock.calls.map((call) => (call[0] as { url: string }).url);

beforeEach(() => {
    setActivePinia(createPinia());
    vi.clearAllMocks();
    responses = {
        'POST /account/login': orvalEnvelope({ token: 'jwt-token' }),
        'GET /account': orvalEnvelope(USER),
        'POST /account/reset': orvalEnvelope(),
        'POST /account/reset-confirm': orvalEnvelope(),
        'POST /account/logout': orvalEnvelope(),
        'POST /account/logout-all': orvalEnvelope()
    };
});

describe('login', () => {
    it('stores the token, then loads the profile with it', () =>
        useAuthStore()
            .login('ada@example.com', 'hunter2hunter2')
            .then(() => {
                // Order is the assertion: a profile fetched before the token is attached is an
                // anonymous request, which answers 401 rather than the account.
                expect(requestedUrls()).toEqual(['/account/login', '/account']);
                expect(useSessionStore().accessToken).toBe('jwt-token');
            }));

    it('maps the remember checkbox to the medium tier, and sends no tier otherwise', () =>
        useAuthStore()
            .login('ada@example.com', 'hunter2hunter2', true)
            .then(() => useAuthStore().login('ada@example.com', 'hunter2hunter2'))
            .then(() => {
                const bodies = vi
                    .mocked(orvalMutator)
                    .mock.calls.filter(
                        (call) => (call[0] as { url: string }).url === '/account/login'
                    )
                    .map((call) => (call[0] as { data: unknown }).data);
                expect(bodies).toEqual([
                    { email: 'ada@example.com', password: 'hunter2hunter2', remember: 'medium' },
                    { email: 'ada@example.com', password: 'hunter2hunter2', remember: undefined }
                ]);
            }));

    it('publishes the viewer the router guards read', () =>
        useAuthStore()
            .login('ada@example.com', 'hunter2hunter2')
            .then(() => {
                const session = useSessionStore();

                // The projection, not the record: the shell is not allowed to know what a `User`
                // is, so anything beyond these three fields leaking in is a regression.
                expect(session.viewer).toEqual({
                    id: 'u1',
                    email: 'ada@example.com',
                    admin: false
                });
                expect(session.isAuth).toBe(true);
                expect(session.isAdmin).toBe(false);
            }));

    it('marks an admin as one, so the admin routes resolve', () => {
        responses['GET /account'] = orvalEnvelope({ ...USER, admin: true });

        return useAuthStore()
            .login('ada@example.com', 'hunter2hunter2')
            .then(() => {
                expect(useSessionStore().isAdmin).toBe(true);
            });
    });

    it('leaves the session anonymous when the response carries no token', () => {
        // A `data` with neither shape the union declares is impossible against the real contract
        // (`orvalMutator` itself would reject it) — this pins `getTokenFromResponse`'s OWN defence
        // for that state, so it bypasses `parseOrvalFixture` on purpose rather than resolving
        // through the keyed `responses` table.
        vi.mocked(orvalMutator).mockImplementationOnce(() =>
            Promise.resolve({ success: true, status: 200, message: 'OK', data: {} })
        );

        return useAuthStore()
            .login('ada@example.com', 'hunter2hunter2')
            .then(() => {
                expect(useSessionStore().accessToken).toBeUndefined();
            });
    });
});

describe('logout', () => {
    it('ends THIS session only and clears the state the guards read', () => {
        const auth = useAuthStore();

        return auth
            .login('ada@example.com', 'hunter2hunter2')
            .then(() => auth.logout())
            .then(() => {
                const session = useSessionStore();

                // The single-session endpoint: other devices stay signed in, which is what a
                // shared-machine logout should mean. `logoutEverywhere` is the wide one.
                expect(requestedUrls().at(-1)).toBe('/account/logout');
                // The whole point of the action: a stale `isAuth` would let the guards wave the
                // next navigation through with no token to back it.
                expect(session.accessToken).toBeUndefined();
                expect(session.viewer).toBeUndefined();
                expect(session.isAuth).toBe(false);
            });
    });

    it('drops the cached profile, so the next visitor is not served this one', () => {
        const auth = useAuthStore();

        return auth
            .login('ada@example.com', 'hunter2hunter2')
            .then(() => auth.logout())
            .then(() => {
                expect(useProfileStore().profile).toBeUndefined();
            });
    });
});

describe('the password reset flow', () => {
    it('requests a token for an email', () =>
        useAuthStore()
            .requestPasswordReset('ada@example.com')
            .then(() => {
                expect(requestedUrls()).toEqual(['/account/reset']);
            }));

    it('confirms with the token and the new password', () =>
        useAuthStore()
            .confirmPasswordReset('reset-token', 'hunter3hunter3', 'hunter3hunter3')
            .then(() => {
                const last = vi.mocked(orvalMutator).mock.calls.at(-1)![0] as {
                    url: string;
                    data: Record<string, unknown>;
                };

                expect(last.url).toBe('/account/reset-confirm');
                expect(last.data).toMatchObject({ token: 'reset-token' });
            }));
});

describe('logoutEverywhere', () => {
    it('calls logout-all — the compromised-credentials button', () => {
        const auth = useAuthStore();

        return auth
            .login('ada@example.com', 'hunter2hunter2')
            .then(() => auth.logoutEverywhere())
            .then(() => {
                expect(requestedUrls().at(-1)).toBe('/account/logout-all');
                expect(useSessionStore().isAuth).toBe(false);
            });
    });
});

src/modules/users/tests/schemas-i18n.spe.source:
/**
 * @module
 * Users' validation messages follow the active locale. The MECHANISM — that a thunked Zod message
 * re-resolves at parse time — is proven once elsewhere, with an invented schema, in
 * `tests/cross-cutting/schemas-i18n.spec.ts`; this file proves THIS module's schemas and
 * dictionaries actually agree, so it lives with the domain (`docs/theory/modules.md`).
 *
 * Runs against the real vue-i18n instance, with the modules wired in as `src/main.ts` does: a
 * mocked `t` would assert only that a key was looked up, which stays true when the message is
 * frozen in the wrong language.
 */
import { describe, it, expect, beforeAll, afterEach } from 'vitest';
import { nextTick } from 'vue';
import { loadLocale } from '@/infrastructure/i18n';
import { wireModulesIntoCore } from '../../../../tests/support/unit/wire-modules.ts';
import { usersSchema, usersPasswordSchema } from '@/modules/users';
import enMessages from '../locales/en.json';
import itMessages from '../locales/it.json';

/**
 * Switches the active i18n locale and waits for the DOM-facing reactivity to settle.
 *
 * @param locale - Locale code to switch to.
 * @returns A promise resolving once the locale is active.
 */
const setLocale = (locale: string) => loadLocale(locale).then(() => nextTick());

/**
 * Every issue message a schema produces for a value, in the currently active locale.
 */
const messagesOf = (
    schema: { safeParse: (value: unknown) => { error?: { issues: { message: string }[] } } },
    value: unknown
) => schema.safeParse(value).error?.issues.map(({ message }) => message) ?? [];

describe('users schema messages', () => {
    beforeAll(() => {
        wireModulesIntoCore();
        return setLocale('en');
    });
    afterEach(() => setLocale('en'));

    it('resolves in English, then in Italian, from the same schema object', () => {
        expect(messagesOf(usersSchema, { email: 'nope', username: 'a' })).toEqual(
            expect.arrayContaining([enMessages['users-form']['email-invalid']])
        );

        return setLocale('it').then(() => {
            expect(messagesOf(usersSchema, { email: 'nope', username: 'a' })).toEqual(
                expect.arrayContaining([itMessages['users-form']['email-invalid']])
            );
        });
    });

    it('does the same for every password rule, including the refinements', () =>
        setLocale('it').then(() => {
            expect(messagesOf(usersPasswordSchema, 'short')).toEqual(
                expect.arrayContaining([
                    itMessages['users-form']['password-min'],
                    itMessages['users-form']['password-maius-required'],
                    itMessages['users-form']['password-number-required'],
                    itMessages['users-form']['password-special-required']
                ])
            );
        }));
});

src/modules/orders/tests/store.spec.ts.source:
/**
 * @module
 * Unit tests for the orders store, mocking the `@api` client module directly and exercising the
 * store's actions against canned responses.
 *
 * One thing here is this repo's own logic rather than the toolkit's: `downloadInvoice`, the one
 * call whose payload is a binary Blob rather than a JSON envelope.
 *
 * Checkout is not tested here because it is not here: `POST /cart/checkout` empties the cart, so
 * `useCartStore` owns it and `src/modules/cart/tests/store.spec.ts` covers it.
 */
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';

import { useOrdersStore } from '@/modules/orders/store';
import {
    listOrders,
    searchOrders,
    getOrderById,
    createOrder as apiCreateOrder,
    updateOrderById,
    deleteOrderById,
    hardDeleteOrderById,
    getOrderInvoice
} from '@api';

/**
 * Fixture order returned by the mocked `@api` client.
 */
const ORDER = {
    id: 'o1',
    userId: 'u1',
    email: 'ada@example.com',
    items: [],
    totalItems: 1,
    totalQuantity: 2,
    totalPrice: 19.98,
    status: 'pending'
};

/**
 * Fixture PDF blob returned by the mocked invoice endpoint.
 */
const INVOICE = new Blob(['%PDF-1.4'], { type: 'application/pdf' });

// `meta` matches the real `PaginationMeta` shape — `search:` (`store.ts`) reads
// `meta.totalPages` for `pageTotal`, so an envelope without one no longer represents a real
// response.
const EMPTY_PAGE = { items: [], meta: { page: 1, pageSize: 10, totalItems: 0, totalPages: 1 } };

vi.mock('@api', () => ({
    listOrders: vi.fn(() => Promise.resolve({ data: EMPTY_PAGE })),
    searchOrders: vi.fn(() => Promise.resolve({ data: EMPTY_PAGE })),
    getOrderById: vi.fn(() => Promise.resolve({ data: ORDER })),
    createOrder: vi.fn(() => Promise.resolve({ data: ORDER })),
    updateOrderById: vi.fn(() => Promise.resolve({ data: ORDER })),
    deleteOrderById: vi.fn(() => Promise.resolve({ data: undefined })),
    hardDeleteOrderById: vi.fn(() => Promise.resolve({ data: undefined })),
    getOrderInvoice: vi.fn(() => Promise.resolve(INVOICE))
}));

describe('useOrdersStore', () => {
    beforeEach(() => {
        setActivePinia(createPinia());
        vi.clearAllMocks();
    });

    describe('fetchOrders', () => {
        it('reads the item list out of the paginated envelope', () => {
            const store = useOrdersStore();

            return store.fetchOrders().then(() => {
                expect(listOrders).toHaveBeenCalled();
                expect(store.ordersList).toEqual([]);
            });
        });
    });

    describe('fetchPaginationOrders', () => {
        it('defaults to the first page of ten', () =>
            useOrdersStore()
                .fetchPaginationOrders()
                .then(() => {
                    // A paged read IS a search with no filters, so it rides the search route.
                    expect(searchOrders).toHaveBeenCalledWith({ page: 1, pageSize: 10 });
                }));

        it('passes an explicit page and size through', () =>
            useOrdersStore()
                .fetchPaginationOrders(3, 25)
                .then(() => {
                    expect(searchOrders).toHaveBeenCalledWith({ page: 3, pageSize: 25 });
                }));
    });

    describe('createOrder', () => {
        it('forwards the payload unchanged', () => {
            const payload = {
                userId: 'u1',
                email: 'ada@example.com',
                items: [{ productId: 'p1', quantity: 1 }]
            };

            return useOrdersStore()
                .createOrder(payload)
                .then(() => {
                    expect(apiCreateOrder).toHaveBeenCalledWith(payload);
                });
        });
    });

    describe('updateOrder', () => {
        it('sends the id in the path and the changes in the body', () =>
            useOrdersStore()
                .updateOrder('o1', { status: 'shipped' })
                .then(() => {
                    expect(updateOrderById).toHaveBeenCalledWith('o1', { status: 'shipped' });
                }));
    });

    describe('deleteOrder', () => {
        it('calls the delete endpoint with the order id', () =>
            useOrdersStore()
                .deleteOrder('o1')
                .then(() => {
                    expect(deleteOrderById).toHaveBeenCalledWith('o1');
                }));
    });

    describe('hardDeleteOrder', () => {
        /*
         * A separate method rather than a flag on `deleteOrder`: the soft form sets `deletedAt` and
         * an admin can toggle it back, this one is irreversible. Distinct names mean the destructive
         * path cannot be reached by passing the wrong boolean, so the assertion worth making is that
         * each reaches its OWN client function and not the other's.
         */
        it('calls the hard-delete client with the order id', () =>
            useOrdersStore()
                .hardDeleteOrder('o1')
                .then(() => {
                    expect(hardDeleteOrderById).toHaveBeenCalledWith('o1');
                    expect(deleteOrderById).not.toHaveBeenCalled();
                }));

        it('leaves the soft delete reaching only the soft client', () =>
            useOrdersStore()
                .deleteOrder('o1')
                .then(() => {
                    expect(deleteOrderById).toHaveBeenCalledWith('o1');
                    expect(hardDeleteOrderById).not.toHaveBeenCalled();
                }));
    });

    describe('downloadInvoice', () => {
        it('returns the binary payload as-is, without unwrapping an envelope', () =>
            useOrdersStore()
                .downloadInvoice('o1')
                .then((result) => {
                    expect(getOrderInvoice).toHaveBeenCalledWith('o1');
                    expect(result).toBe(INVOICE);
                }));
    });

    describe('fetchOrder', () => {
        it('fetches one order and unwraps a single-record envelope', () =>
            useOrdersStore()
                .fetchOrder('o1')
                .then((result) => {
                    expect(getOrderById).toHaveBeenCalledWith('o1');
                    // `.data`, one level shallower than the list endpoints' `.data.items`.
                    expect(result).toEqual(ORDER);
                }));

        it('passes the id through as the cache key, not just as the URL parameter', () => {
            // `fetchTarget(fetcher, orderId, ...)` — the second argument is what the toolkit
            // caches and selects on. Dropping it would still produce a correct HTTP request,
            // so the request assertion above cannot catch it.
            const store = useOrdersStore();

            return store
                .fetchOrder('o1')
                .then(() => store.fetchOrder('o1'))
                .then(() => {
                    // Second call served from cache: the id reached the cache layer.
                    expect(getOrderById).toHaveBeenCalledTimes(1);
                });
        });

        it('bypasses the cache when forced', () => {
            const store = useOrdersStore();

            return store
                .fetchOrder('o1')
                .then(() => store.fetchOrder('o1', { forced: true }))
                .then(() => {
                    expect(getOrderById).toHaveBeenCalledTimes(2);
                });
        });
    });

    describe('watchSearchOrders', () => {
        it('posts every supported filter to /orders/search', () => {
            const store = useOrdersStore();
            store.filters = {
                id: 'o1',
                userId: 'u1',
                productId: 'p1',
                email: 'ada@example.com'
            };

            return store
                .watchSearchOrders()
                .search()
                .then(() => {
                    expect(searchOrders).toHaveBeenCalledWith(
                        expect.objectContaining({
                            id: 'o1',
                            userId: 'u1',
                            productId: 'p1',
                            email: 'ada@example.com'
                        })
                    );
                });
        });

        it('includes the current page and size alongside the filters', () => {
            const store = useOrdersStore();
            store.filters = { email: 'ada@example.com' };

            return store
                .watchSearchOrders()
                .search()
                .then(() => {
                    // Dropping pagination here would silently return only the first page for
                    // every search, no matter which page the user is on.
                    expect(searchOrders).toHaveBeenCalledWith(
                        expect.objectContaining({
                            page: expect.any(Number),
                            pageSize: expect.any(Number)
                        })
                    );
                });
        });

        it('reports a failed search to the supplied error handler', () => {
            const failure = new Error('network down');
            vi.mocked(searchOrders).mockRejectedValueOnce(failure);
            const onError = vi.fn();

            return useOrdersStore()
                .watchSearchOrders({ onError })
                .search()
                .catch(() => {})
                .then(() => {
                    expect(onError).toHaveBeenCalledWith(failure, expect.anything());
                });
        });
    });
});

src/modules/cart/tests/store.spec.ts.source:
/**
 * @module
 * Unit tests for the cart store.
 *
 * Unlike products/users, this store owns real state: every action replaces the local cart with
 * the payload the API returned. Two rules are worth guarding:
 *
 *   - `clearCart()` is bodyless and hits `DELETE /cart/all`, a separate URL from
 *     `removeCartItem(productId)`'s `DELETE /cart/:productId` — the two used to be one
 *     overloaded endpoint, and collapsing them back into an optional-body call would restore the
 *     failure a stripped body used to cause: silently clearing everything instead of one line.
 *   - the summary getters must survive an unfetched cart, since the header renders the item
 *     count before anything has been loaded.
 *   - checkout reports BOTH outcomes. The backend emits `checkout_completed` and `checkout_failed`
 *     from one handler and the funnel is built across the two repos, so a rejection this side
 *     swallowed would read as a user abandoning checkout rather than checkout refusing them.
 */
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';

import { useCartStore } from '@/modules/cart/store';
import {
    getCart,
    getCartSummary,
    upsertCartItem,
    updateCartItemById,
    removeCartItem,
    clearCart,
    checkout as apiCheckout,
    reorder as apiReorder
} from '@api';
const CART = {
    items: [{ productId: 'p1', quantity: 2 }],
    summary: { itemsCount: 1, totalQuantity: 2, total: 19.98 }
};

const EMPTY_CART = { items: [], summary: { itemsCount: 0, totalQuantity: 0, total: 0 } };

const ORDER = { id: 'o1', totalPrice: 19.98 };

/**
 * The reject envelope `onResponseReject` builds — never an `Error`, which is the whole point.
 */
const apiFailure = (status: number) =>
    // eslint-disable-next-line @typescript-eslint/prefer-promise-reject-errors -- the API's error ENVELOPE is this client's rejection contract
    Promise.reject({
        success: false,
        status,
        message: 'nope',
        errors: [{ code: 'STUB_ERROR', message: 'nope' }]
    }) as never;

vi.mock('@api', () => ({
    getCart: vi.fn(() => Promise.resolve({ data: CART })),
    getCartSummary: vi.fn(() => Promise.resolve({ data: CART.summary })),
    upsertCartItem: vi.fn(() => Promise.resolve({ data: CART })),
    updateCartItemById: vi.fn(() => Promise.resolve({ data: CART })),
    removeCartItem: vi.fn(() => Promise.resolve({ data: EMPTY_CART })),
    clearCart: vi.fn(() => Promise.resolve({ data: EMPTY_CART })),
    checkout: vi.fn(() => Promise.resolve({ data: { order: ORDER } })),
    reorder: vi.fn(() => Promise.resolve({ data: CART }))
}));

describe('useCartStore', () => {
    beforeEach(() => {
        setActivePinia(createPinia());
        vi.clearAllMocks();
    });

    /**
     * The header's badge, and the one read where a failure is an ordinary state: a guest has no
     * cart, so 401 empties it. Only 401 — a 500 emptied here shows a full cart as empty.
     */
    describe('fetchSummary', () => {
        it('seeds the badge from the summary endpoint', () => {
            const store = useCartStore();

            return store.fetchSummary().then(() => {
                // Units, not lines: one line of two is a badge saying 2.
                expect(store.badgeQuantity).toBe(2);
                expect(store.badgeTotal).toBe(19.98);
            });
        });

        it('reads a 401 as "no cart", leaving the badge empty', () => {
            vi.mocked(getCartSummary).mockReturnValueOnce(apiFailure(401));
            const store = useCartStore();

            return store.fetchSummary().then((summary) => {
                expect(summary).toBeUndefined();
                expect(store.badgeQuantity).toBeUndefined();
                expect(store.badgeTotal).toBeUndefined();
            });
        });

        it('lets any other failure through instead of calling it "no cart"', () => {
            vi.mocked(getCartSummary).mockReturnValueOnce(apiFailure(500));
            const store = useCartStore();

            return expect(store.fetchSummary()).rejects.toMatchObject({ status: 500 });
        });
    });

    describe('before anything is fetched', () => {
        it('exposes an empty item list and no summary', () => {
            const store = useCartStore();

            expect(store.cart).toBeUndefined();
            expect(store.cartItems).toEqual([]);
            expect(store.cartSummary).toBeUndefined();
        });
    });

    describe('fetchCart', () => {
        it('stores the payload and derives items, summary and count from it', () => {
            const store = useCartStore();

            return store.fetchCart().then(() => {
                expect(getCart).toHaveBeenCalled();
                expect(store.cartItems).toEqual(CART.items);
                expect(store.cartSummary).toEqual(CART.summary);
                expect(store.cartSummary?.itemsCount).toBe(1);
            });
        });
    });

    describe('upsertCartItem', () => {
        it('sends the product and quantity and replaces the local cart', () => {
            const store = useCartStore();

            return store.upsertCartItem('p1', 2).then(() => {
                expect(upsertCartItem).toHaveBeenCalledWith({ productId: 'p1', quantity: 2 });
                expect(store.cartItems).toEqual(CART.items);
            });
        });
    });

    describe('updateCartItem', () => {
        it('sends only the quantity, with the product in the path', () =>
            useCartStore()
                .updateCartItem('p1', 5)
                .then(() => {
                    expect(updateCartItemById).toHaveBeenCalledWith('p1', { quantity: 5 });
                }));

        /**
         * The endpoint recalculates the summary, so the response is the whole cart and not just
         * the edited line. Without this, an implementation that fired the request and threw the
         * answer away would pass both tests above while leaving the totals on screen stale.
         */
        it('replaces the local cart with the recalculated response', () => {
            const store = useCartStore();

            return store.updateCartItem('p1', 5).then((result) => {
                expect(store.cart).toEqual(CART);
                expect(store.cartSummary?.itemsCount).toBe(1);
                expect(result).toEqual(CART);
            });
        });
    });

    describe('removeCartItem', () => {
        it('replaces the local cart with the emptied one', () => {
            const store = useCartStore();

            return store
                .fetchCart()
                .then(() => store.removeCartItem('p1'))
                .then(() => {
                    expect(removeCartItem).toHaveBeenCalledWith('p1');
                    expect(store.cartItems).toEqual([]);
                });
        });
    });

    describe('clearCart', () => {
        it('takes no arguments — clearing is DELETE /cart/all, not an optional body', () =>
            useCartStore()
                .clearCart()
                .then(() => {
                    expect(clearCart).toHaveBeenCalledWith();
                }));
    });

    describe('checkout', () => {
        it('calls the endpoint with no payload when none is given', () =>
            useCartStore()
                .checkout()
                .then(() => {
                    expect(apiCheckout).toHaveBeenCalledWith(undefined);
                }));

        it('returns the checkout envelope, order included', () =>
            useCartStore()
                .checkout({ notes: 'leave at door' })
                .then((result) => {
                    expect(apiCheckout).toHaveBeenCalledWith({ notes: 'leave at door' });
                    expect(result).toEqual({ order: ORDER });
                }));

        it('empties the local cart, because the server emptied the real one', () => {
            const store = useCartStore();

            return store
                .fetchCart()
                .then(() => {
                    expect(store.cartSummary?.itemsCount).toBe(1);
                    return store.checkout();
                })
                .then(() => {
                    expect(store.cart).toBeUndefined();
                    expect(store.cartItems).toEqual([]);
                    expect(store.cartSummary).toBeUndefined();
                });
        });

        it('lets a refusal the API answered reach the caller', () => {
            // The rejection has to survive the store: the view turns it into the toast the user
            // sees, and a swallowed error is a failure reported to nobody.
            vi.mocked(apiCheckout).mockRejectedValueOnce({
                status: 409,
                errors: [{ code: 'CART_EMPTY' }]
            });

            return expect(useCartStore().checkout()).rejects.toMatchObject({ status: 409 });
        });

        it('lets a request that never arrived reach the caller too', () => {
            // No status means no response: the connection dropped, or the request never left the
            // browser. Faro's fetch instrumentation already records it, so the store adds nothing
            // and only has to keep the rejection intact.
            vi.mocked(apiCheckout).mockRejectedValueOnce(new Error('Network Error'));

            return expect(useCartStore().checkout()).rejects.toThrow('Network Error');
        });

        /**
         * A 200 carrying no order is not a shape this client should crash on: the cart was still
         * emptied server-side, so the success path must run to the end and resolve.
         */
        it('survives a success envelope with no order in it', () => {
            const store = useCartStore();
            vi.mocked(apiCheckout).mockResolvedValueOnce({ data: {} } as never);

            return store
                .fetchCart()
                .then(() => store.checkout())
                .then((result) => {
                    expect(result).toEqual({});
                    expect(store.cart).toBeUndefined();
                });
        });
    });

    /**
     * Reorder copies one of the caller's own orders back into the cart. The response is the
     * updated cart rather than the order, because products that left the catalogue are skipped
     * server-side — replacing the local copy with the answer is what makes that skip visible.
     */
    describe('reorder', () => {
        it('sends the order id and replaces the local cart with the response', () => {
            const store = useCartStore();

            return store.reorder('o1').then((result) => {
                expect(apiReorder).toHaveBeenCalledWith('o1');
                expect(store.cart).toEqual(CART);
                expect(store.cartSummary?.itemsCount).toBe(1);
                expect(result).toEqual(CART);
            });
        });
    });

    /**
     * Pinia identifies a store by the string given to `defineStore`. Nothing else in this suite
     * would notice it changing, since every test reaches the store through `useCartStore()`.
     */
    it('is registered under the "cart" id', () => {
        expect(useCartStore().$id).toBe('cart');
    });
});

