/**
 * @module
 * `src/modules/locales/schemas.ts` — the locale admin's three Zod schemas.
 *
 * Two things are asserted that a happy-path parse would not reach: the BCP 47 tag pattern's case
 * rules, and that every message is a THUNK, so it resolves in the locale active at parse time
 * rather than the one active when the module was imported. The second is the whole reason the
 * schemas are written the way they are — this is the screen where the language changes.
 */
import { describe, expect, it } from 'vitest';
import {
    localesEntrySchema,
    localesLanguageEditSchema,
    localesLanguageSchema
} from '@/modules/locales/schemas';

/**
 * A create-form payload that passes, for tests that vary one field away from valid.
 */
const validLanguage = {
    tag: 'pt-BR',
    name: 'Portuguese',
    nativeName: 'Português'
};

describe('localesLanguageSchema', () => {
    it('accepts a primary subtag with and without a region', () => {
        expect(localesLanguageSchema.parse({ ...validLanguage, tag: 'en' }).tag).toBe('en');
        expect(localesLanguageSchema.parse(validLanguage).tag).toBe('pt-BR');
    });

    /**
     * Case carries meaning in BCP 47 and the API stores the tag as given, so a lowercase region
     * is a different tag rather than a spelling of the same one.
     */
    it.each(['pt-br', 'PT-BR', 'Pt-BR', 'por', 'p', 'pt-BRA', 'pt_BR', 'pt-', ''])(
        'rejects %o as a language tag',
        (tag) => {
            expect(localesLanguageSchema.safeParse({ ...validLanguage, tag }).success).toBe(false);
        }
    );

    /**
     * `.default()` rather than `.optional()`: an omitted value has to reach the API as the
     * contract's own fallback, not as `undefined`.
     */
    it('defaults direction to ltr and active to true', () => {
        const parsed = localesLanguageSchema.parse(validLanguage);

        expect(parsed.direction).toBe('ltr');
        expect(parsed.active).toBe(true);
    });

    it('keeps an explicit direction and active over the defaults', () => {
        const parsed = localesLanguageSchema.parse({
            ...validLanguage,
            direction: 'rtl',
            active: false
        });

        expect(parsed.direction).toBe('rtl');
        expect(parsed.active).toBe(false);
    });

    it('accepts only the two writing directions', () => {
        expect(
            localesLanguageSchema.safeParse({ ...validLanguage, direction: 'ttb' }).success
        ).toBe(false);
    });

    it.each(['name', 'nativeName'] as const)('rejects an empty %s', (field) => {
        expect(localesLanguageSchema.safeParse({ ...validLanguage, [field]: '' }).success).toBe(
            false
        );
    });
});

describe('localesLanguageEditSchema', () => {
    /**
     * The field is disabled on the edit form and `UpdateLocaleRequest` has no `tag` at all, so
     * nothing typed into it can reach the API — the schema stops policing it rather than failing
     * a form on a value that is never sent.
     */
    it('accepts a tag the create form would reject', () => {
        expect(localesLanguageEditSchema.parse({ ...validLanguage, tag: 'not a tag' }).tag).toBe(
            'not a tag'
        );
    });

    /**
     * Relaxing these would only move the rejection to a 422: the form omits nothing, and a sent
     * field still has to satisfy the contract's `minLength: 1`.
     */
    it.each(['name', 'nativeName'] as const)('still requires %s', (field) => {
        expect(localesLanguageEditSchema.safeParse({ ...validLanguage, [field]: '' }).success).toBe(
            false
        );
    });

    it('keeps the defaults the create form applies', () => {
        const parsed = localesLanguageEditSchema.parse(validLanguage);

        expect(parsed.direction).toBe('ltr');
        expect(parsed.active).toBe(true);
    });
});

describe('localesEntrySchema', () => {
    it('accepts a complete entry', () => {
        expect(localesEntrySchema.parse({ tenant: 'demo-fe', key: 'a.b', value: 'Hello' })).toEqual(
            { tenant: 'demo-fe', key: 'a.b', value: 'Hello' }
        );
    });

    it.each(['tenant', 'key', 'value'] as const)('rejects an empty %s', (field) => {
        const entry = { tenant: 'demo-fe', key: 'a.b', value: 'Hello', [field]: '' };

        expect(localesEntrySchema.safeParse(entry).success).toBe(false);
    });
});

describe('every message is resolved at parse time', () => {
    /**
     * The claim the thunks exist for. A message frozen at import would be identical in both
     * locales; these are parsed either side of a locale switch and compared.
     *
     * The keys are asserted rather than the translated text: what matters is that the schema
     * asked i18n for a message at parse time, and the fallback locale returns the key itself when
     * the vocabulary has no entry for it.
     */
    it.each([
        [localesLanguageSchema, { tag: '', name: '', nativeName: '' }],
        [localesEntrySchema, { tenant: '', key: '', value: '' }]
    ])('names an i18n key for every failure', (schema, payload) => {
        const result = schema.safeParse(payload);

        expect(result.success).toBe(false);
        for (const issue of result.error!.issues) {
            expect(issue.message).not.toBe('');
            // Zod's own built-in text ("Too small: ...") is what a missing thunk would leave
            // behind, so its absence is the assertion.
            expect(issue.message).not.toMatch(/^Too small/);
        }
    });
});

src/modules/account/tests/auth-login-mfa.source:
/**
 * @module
 * Unit tests for `useAuthStore().login()`'s union narrowing: the `mfa` branch must resolve with
 * the challenge and touch NEITHER the session store nor the profile store — the bug this narrowing
 * exists to fix stored `undefined` as a token and then 401'd fetching the profile with it, locking
 * every 2FA account out of the app. `auth-session.spec.ts` covers the plain `session` branch this
 * store already had; this file is only about telling the two apart.
 */
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';

import { useAuthStore } from '@/modules/account/stores/auth.ts';
import { useSessionStore } from '@/infrastructure/session.ts';
import { orvalMutator } from '@/infrastructure/http';
import { wireModulesIntoCore } from '../../../../tests/support/unit/wire-modules.ts';
import {
    orvalEnvelope,
    parseOrvalFixture
} from '../../../../tests/unit/infrastructure/http/orval-fixture-schema.ts';

wireModulesIntoCore();

let responses: Record<string, unknown>;

vi.mock('@/infrastructure/http', () => ({
    orvalMutator: vi.fn((config: { url: string; method: string }) => {
        const key = `${config.method?.toUpperCase()} ${config.url}`;
        return Promise.resolve(parseOrvalFixture(config.method, config.url, responses[key]));
    })
}));

const requestedUrls = () =>
    vi.mocked(orvalMutator).mock.calls.map((call) => (call[0] as { url: string }).url);

const MFA_CHALLENGE = {
    mfaRequired: true,
    challenge: 'claim-check-token',
    expiresAt: '2026-01-01T00:05:00.000Z',
    methods: [{ method: 'email', delivers: true, target: 'a***a@example.com' }],
    defaultMethod: 'email'
};

beforeEach(() => {
    setActivePinia(createPinia());
    vi.clearAllMocks();
    responses = {
        'POST /account/login': orvalEnvelope({ token: 'jwt-token' }),
        'GET /account': orvalEnvelope({ id: 'u1', username: 'ada', email: 'ada@example.com' })
    };
});

describe('login — the mfa branch', () => {
    it('resolves with the challenge, echoed from the response', () => {
        responses['POST /account/login'] = orvalEnvelope(MFA_CHALLENGE);

        return useAuthStore()
            .login('ada@example.com', 'hunter2hunter2')
            .then((outcome) => {
                expect(outcome).toEqual({
                    kind: 'mfa',
                    challenge: 'claim-check-token',
                    expiresAt: '2026-01-01T00:05:00.000Z',
                    methods: MFA_CHALLENGE.methods,
                    defaultMethod: 'email'
                });
            });
    });

    it('never fetches the profile — an MfaChallenge response carries no token to fetch it with', () => {
        responses['POST /account/login'] = orvalEnvelope(MFA_CHALLENGE);

        return useAuthStore()
            .login('ada@example.com', 'hunter2hunter2')
            .then(() => {
                expect(requestedUrls()).toEqual(['/account/login']);
            });
    });

    it('leaves the session store untouched — the bug this branch exists to fix', () => {
        responses['POST /account/login'] = orvalEnvelope(MFA_CHALLENGE);

        return useAuthStore()
            .login('ada@example.com', 'hunter2hunter2')
            .then(() => {
                const session = useSessionStore();
                expect(session.accessToken).toBeUndefined();
                expect(session.viewer).toBeUndefined();
                expect(session.isAuth).toBe(false);
            });
    });
});

describe('login — the session branch', () => {
    it('resolves with kind: session for a plain account', () =>
        useAuthStore()
            .login('ada@example.com', 'hunter2hunter2')
            .then((outcome) => {
                expect(outcome).toEqual({ kind: 'session' });
                expect(useSessionStore().isAuth).toBe(true);
            }));
});

tests/unit/infrastructure/observability/.source:
/**
 * @module
 * The Faro-ENABLED half of `src/infrastructure/observability/store.ts`.
 *
 * `observability.spec.ts` covers the disabled state and explains why it stops there. What it
 * leaves untested is this repo's own mapping — the config object handed to `initializeFaro`, the
 * one-shot init promise, and the error normalisation — so the two SDKs are mocked at the module
 * boundary and only OUR arguments are asserted, never the SDKs' behaviour.
 */
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';
import { useObservabilityStore } from '@/infrastructure/observability/store.ts';

/** The `faro.api` surface this store calls, spied so each call can be asserted. */
const faroApi = {
    setUser: vi.fn(),
    resetUser: vi.fn(),
    pushError: vi.fn()
};

/** What `initializeFaro` returns — only the `api` handle is ever read. */
const fakeFaro = { api: faroApi };

const initializeFaro = vi.fn(() => fakeFaro);

/**
 * Stands in for the tracing SDK's instrumentation class, capturing the options it is constructed
 * with so `propagateTraceHeaderCorsUrls` can be checked.
 */
const tracingOptions: unknown[] = [];

vi.mock('@grafana/faro-web-sdk', () => ({
    initializeFaro: (...arguments_: unknown[]) => initializeFaro(...(arguments_ as [])),
    getWebInstrumentations: () => ['web-instrumentations']
}));

// An anonymous `function` rather than a class: a class holding only a constructor is what the lint
// rejects, and an arrow cannot be used with `new`, which is how the store builds this. Options are
// read from the body rather than captured — `vi.mock` hoists above `tracingOptions`, so anything
// evaluated at factory time would hit the temporal dead zone.
vi.mock('@grafana/faro-web-tracing', () => ({
    TracingInstrumentation: vi.fn(function (options: unknown) {
        tracingOptions.push(options);
    })
}));

beforeEach(() => {
    setActivePinia(createPinia());
    tracingOptions.length = 0;
    vi.stubEnv('VITE_FARO_URL', 'http://collector/collect');
    vi.stubEnv('VITE_FARO_APP_NAME', 'shop');
    vi.stubEnv('VITE_FARO_APP_VERSION', '2.4.0');
    vi.stubEnv('VITE_FARO_ENVIRONMENT', 'staging');
    vi.stubEnv('VITE_API_URL', 'https://api.example.com');
    vi.stubEnv('VITE_UMAMI_WEBSITE_ID', '');
});

afterEach(() => {
    vi.unstubAllEnvs();
    vi.clearAllMocks();
});

describe('initFaro', () => {
    it('reports success and flips faroReady', async () => {
        const store = useObservabilityStore();

        await expect(store.initFaro()).resolves.toBe(true);
        expect(store.faroReady).toBe(true);
    });

    it('hands the SDK the configuration this repo read', async () => {
        const store = useObservabilityStore();
        await store.initFaro();

        expect(initializeFaro).toHaveBeenCalledWith(
            expect.objectContaining({
                url: 'http://collector/collect',
                app: { name: 'shop', version: '2.4.0', environment: 'staging' },
                ignoreUrls: ['http://collector/collect']
            })
        );
    });

    /**
     * The reason `apiOrigin` exists: without this pattern the browser sends no `traceparent` to
     * the API, and a request's front-end and back-end halves become two unrelated traces.
     */
    it('propagates trace headers to the API origin', async () => {
        const store = useObservabilityStore();
        await store.initFaro();

        const [options] = tracingOptions as {
            instrumentationOptions: { propagateTraceHeaderCorsUrls: RegExp[] };
        }[];
        const [pattern] = options.instrumentationOptions.propagateTraceHeaderCorsUrls;

        expect(pattern.test('https://api.example.com/orders')).toBe(true);
        expect(pattern.test('https://other.example.com/orders')).toBe(false);
    });

    /**
     * `faroInitPromise ??=` is the guard: two callers racing at bootstrap must share one setup,
     * or the second initialises a second Faro over the first.
     */
    it('initialises once however many callers race', async () => {
        const store = useObservabilityStore();
        await Promise.all([store.initFaro(), store.initFaro(), store.initFaro()]);
        await store.initFaro();

        expect(initializeFaro).toHaveBeenCalledOnce();
    });

    it('resolves false and calls nothing when no collector is configured', async () => {
        vi.stubEnv('VITE_FARO_URL', '');
        const store = useObservabilityStore();

        await expect(store.initFaro()).resolves.toBe(false);
        expect(store.faroReady).toBe(false);
        expect(initializeFaro).not.toHaveBeenCalled();
    });
});

describe('identifyUser, once Faro is up', () => {
    it('sets the user on Faro', async () => {
        const store = useObservabilityStore();
        await store.initFaro();
        store.identifyUser('u1', 'a@example.com');

        expect(faroApi.setUser).toHaveBeenCalledWith({ id: 'u1', email: 'a@example.com' });
    });

    it('passes an undefined email through rather than inventing one', async () => {
        const store = useObservabilityStore();
        await store.initFaro();
        store.identifyUser('u1');

        expect(faroApi.setUser).toHaveBeenCalledWith({ id: 'u1', email: undefined });
    });

    it('clears the identity on unidentify', async () => {
        const store = useObservabilityStore();
        await store.initFaro();
        store.unidentifyUser();

        expect(faroApi.resetUser).toHaveBeenCalledOnce();
    });
});

describe('captureException, once Faro is up', () => {
    it('pushes an Error unchanged and with no context', async () => {
        const store = useObservabilityStore();
        await store.initFaro();
        const error = new Error('boom');
        store.captureException(error);

        expect(faroApi.pushError).toHaveBeenCalledWith(error, undefined);
    });

    /**
     * A thrown non-Error still has to arrive as one: Faro's `pushError` reads `.stack`, and a
     * bare string would report an error with no message and no origin.
     */
    it.each([
        ['a string', 'a string'],
        [42, '42'],
        [undefined, 'undefined'],
        [{ code: 'E' }, '[object Object]']
    ])('normalises %o into an Error', async (thrown, message) => {
        const store = useObservabilityStore();
        await store.initFaro();
        store.captureException(thrown);

        const [pushed] = faroApi.pushError.mock.calls[0] as [Error];
        expect(pushed).toBeInstanceOf(Error);
        expect(pushed.message).toBe(message);
    });

    /**
     * Faro's error context is a string map, so a nested value has to be JSON — an object left as
     * itself arrives as `[object Object]` and the context is lost exactly when it is needed.
     */
    it('stringifies non-string context values and leaves strings alone', async () => {
        const store = useObservabilityStore();
        await store.initFaro();
        store.captureException(new Error('boom'), {
            data: { orderId: 'o1', quantity: 3, lines: [{ sku: 'a' }], missing: null }
        });

        expect(faroApi.pushError).toHaveBeenCalledWith(expect.any(Error), {
            context: {
                orderId: 'o1',
                quantity: '3',
                lines: '[{"sku":"a"}]',
                missing: 'null'
            }
        });
    });

    it('sends no context at all when none was given', async () => {
        const store = useObservabilityStore();
        await store.initFaro();
        store.captureException(new Error('boom'), {});

        expect(faroApi.pushError).toHaveBeenCalledWith(expect.any(Error), undefined);
    });
});

src/modules/inventory/tests/store.spec.t.source:
/**
 * @module
 * The inventory store — transport-mocked like the wishlist's spec.
 *
 * Worth pinning: both reads are whole-list replacement (the page renders what the API answered),
 * and both writes reload what they changed BEFORE answering, so a caller never sees a counter the
 * views have not caught up with. The order of those reloads is asserted rather than assumed — the
 * ledger explains the board, and a board that arrived first reads as a number nobody wrote.
 */
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';
import { useInventoryStore } from '@/modules/inventory/store.ts';
import { orvalMutator } from '@/infrastructure/http';
import { wireModulesIntoCore } from '../../../../tests/support/unit/wire-modules.ts';
import {
    orvalEnvelope,
    parseOrvalFixture
} from '../../../../tests/unit/infrastructure/http/orval-fixture-schema.ts';

wireModulesIntoCore();

/**
 * A stock movement row, as the ledger renders it.
 */
const MOVEMENT = {
    id: 'movement-1',
    productId: 'p1',
    reason: 'reserve',
    onHandDelta: 0,
    reservedDelta: 2
};

/**
 * A stock level row, as the board renders it.
 */
const LEVEL = { productId: 'p1', title: 'Product one', onHand: 24, reserved: 2, available: 22 };

/**
 * The mocked transport's canned response, keyed by `METHOD /path`; reset in `beforeEach`.
 */
let responses: Record<string, unknown>;

vi.mock('@/infrastructure/http', () => ({
    orvalMutator: vi.fn((config: { url: string; method: string }) => {
        const key = `${config.method?.toUpperCase()} ${config.url}`;
        return Promise.resolve(parseOrvalFixture(config.method, config.url, responses[key]));
    })
}));

/**
 * The URLs requested so far, in call order — used to assert a write's reload sequence.
 */
const requestedUrls = () =>
    vi.mocked(orvalMutator).mock.calls.map((call) => (call[0] as { url: string }).url);

beforeEach(() => {
    setActivePinia(createPinia());
    vi.clearAllMocks();
    responses = {
        // `totalPages` is required by the real contract alongside `totalItems` — absent from
        // this fixture before wiring in `parseOrvalFixture` ever proved it against the schema.
        'GET /inventory/movements': orvalEnvelope({
            items: [MOVEMENT],
            meta: { totalItems: 1, totalPages: 1 }
        }),
        'GET /inventory/levels': orvalEnvelope({
            items: [LEVEL],
            meta: { totalItems: 1, totalPages: 1 }
        }),
        'POST /inventory/receipts': orvalEnvelope(LEVEL),
        'POST /inventory/adjustments': orvalEnvelope(LEVEL)
    };
});

describe('fetchMovements', () => {
    it('replaces the ledger with what the API answered', () => {
        const store = useInventoryStore();
        return store.fetchMovements().then(() => {
            expect(store.movements.map(({ id }) => id)).toEqual(['movement-1']);
        });
    });

    it('narrows to one product by passing the id through as a query param', () => {
        const store = useInventoryStore();
        return store.fetchMovements({ productId: 'p1' }).then(() => {
            const call = vi.mocked(orvalMutator).mock.calls[0][0] as {
                params?: { productId?: string };
            };
            expect(call.params).toEqual({ productId: 'p1' });
        });
    });

    it('keeps the audit honest: totalItems from meta, not the row count', () => {
        responses['GET /inventory/movements'] = orvalEnvelope({
            items: [MOVEMENT],
            meta: { page: 1, pageSize: 10, totalItems: 41, totalPages: 5 }
        });
        const store = useInventoryStore();
        return store.fetchMovements({ page: 1, pageSize: 10 }).then(() => {
            expect(store.movementsTotal).toBe(41);
        });
    });

    it('repeats the last query when called with none — the reload-after-write path', () => {
        const store = useInventoryStore();
        return store
            .fetchMovements({ reason: 'adjust' })
            .then(() => store.fetchMovements())
            .then(() => {
                const calls = vi
                    .mocked(orvalMutator)
                    .mock.calls.map((call) => (call[0] as { params?: unknown }).params);
                expect(calls).toEqual([{ reason: 'adjust' }, { reason: 'adjust' }]);
            });
    });
});

describe('fetchLevels', () => {
    it('replaces the board with what the API answered', () => {
        const store = useInventoryStore();
        return store.fetchLevels().then(() => {
            expect(store.levels).toEqual([LEVEL]);
        });
    });
});

describe('receive', () => {
    it('answers the counters the API reported and reloads both views it changed', () => {
        const store = useInventoryStore();
        return store.receive('p1', 20).then((level) => {
            expect(level).toEqual(LEVEL);
            // The reload is the point, and so is its order: the ledger explains the board.
            expect(requestedUrls()).toEqual([
                '/inventory/receipts',
                '/inventory/movements',
                '/inventory/levels'
            ]);
        });
    });

    it('sends the quantity as a receipt body rather than a query param', () => {
        const store = useInventoryStore();
        return store.receive('p1', 20).then(() => {
            const call = vi.mocked(orvalMutator).mock.calls[0][0] as { data?: unknown };
            expect(call.data).toEqual({ productId: 'p1', quantity: 20 });
        });
    });

    it("carries the operator's note onto the row when one was written", () => {
        const store = useInventoryStore();
        return store.receive('p1', 20, 'pallet 7, DHL').then(() => {
            const call = vi.mocked(orvalMutator).mock.calls[0][0] as { data?: unknown };
            expect(call.data).toEqual({ productId: 'p1', quantity: 20, note: 'pallet 7, DHL' });
        });
    });
});

describe('sweep', () => {
    it('answers how many holds were released and reloads both views', () => {
        responses['POST /inventory/reservations/sweep'] = orvalEnvelope({ expired: 3 });
        const store = useInventoryStore();
        return store.sweep().then((expired) => {
            expect(expired).toBe(3);
            expect(requestedUrls()).toEqual([
                '/inventory/reservations/sweep',
                '/inventory/movements',
                '/inventory/levels'
            ]);
        });
    });
});

describe('adjust', () => {
    it('passes the delta through signed, because shrinkage is the common case', () => {
        const store = useInventoryStore();
        return store.adjust('p1', -3).then(() => {
            const call = vi.mocked(orvalMutator).mock.calls[0][0] as { data?: unknown };
            expect(call.data).toEqual({ productId: 'p1', delta: -3 });
        });
    });

    it('reloads both views it changed, exactly as a receipt does', () => {
        const store = useInventoryStore();
        return store.adjust('p1', -3).then(() => {
            expect(requestedUrls()).toEqual([
                '/inventory/adjustments',
                '/inventory/movements',
                '/inventory/levels'
            ]);
        });
    });
});

src/modules/demo/tests/provided.spec.ts.source:
/**
 * @module
 * `src/modules/demo/provided.ts` — the typed provide/inject pair.
 *
 * Driven through a real parent/child mount rather than by calling the two functions directly:
 * `provide`/`inject` only resolve inside a component instance, and the claim worth testing is that
 * a descendant receives the SAME ref the provider holds, not that two functions return objects.
 */
import { describe, expect, it } from 'vitest';
import { defineComponent, h, nextTick } from 'vue';
import { mount } from '@vue/test-utils';
import { provideVariable, providedVariableKey, useProvidedVariable } from '@/modules/demo/provided';
import type { ProvidedVariableContext } from '@/modules/demo/provided';

/**
 * What the last mount's two sides captured, written by the components below as they set up.
 *
 * Module-level rather than per-call because the components have to be too: defining them inside a
 * helper puts their render functions in a nested scope, which the lint forbids.
 */
let parentContext: ProvidedVariableContext | undefined;
let childContext: ProvidedVariableContext | undefined;

/**
 * The descendant, one level below the provider, so the lookup crosses a component boundary.
 *
 * `render` as an option rather than a closure returned from `setup`: the two are equivalent to
 * Vue, and only this spelling keeps the render function out of a nested scope.
 */
const Child = defineComponent({
    setup() {
        childContext = useProvidedVariable();
    },
    render() {
        return h('span', childContext!.providedVariable.value);
    }
});

/** The provider, rendering the child inside its own tree. */
const Parent = defineComponent({
    setup() {
        parentContext = provideVariable();
    },
    render() {
        return h('div', [h(Child)]);
    }
});

/**
 * Mounts the pair, handing back both sides' contexts.
 */
const mountPair = () => {
    const wrapper = mount(Parent);
    return { wrapper, parent: parentContext!, child: childContext! };
};

describe('provideVariable', () => {
    it('starts at the playground default', () => {
        const { parent } = mountPair();

        expect(parent.providedVariable.value).toBe('From the Playground');
    });

    it('returns the same pair it provides, so the provider can use it too', () => {
        const { parent, child } = mountPair();

        expect(child.providedVariable).toBe(parent.providedVariable);
        expect(child.setProvidedVariable).toBe(parent.setProvidedVariable);
    });

    it('writes through to the descendant that injected it', async () => {
        const { wrapper, parent } = mountPair();
        parent.setProvidedVariable('Written by the parent');
        await nextTick();

        expect(wrapper.text()).toBe('Written by the parent');
    });

    /**
     * The default parameter is the point of the mutation: `setProvidedVariable()` with no argument
     * clears the value rather than writing `undefined` into a `Ref<string>`.
     */
    it('clears to an empty string when called with no value', () => {
        const { parent } = mountPair();
        parent.setProvidedVariable('something');
        parent.setProvidedVariable();

        expect(parent.providedVariable.value).toBe('');
    });

    it('gives each provider its own state', () => {
        const first = mountPair();
        const second = mountPair();
        first.parent.setProvidedVariable('only mine');

        expect(second.parent.providedVariable.value).toBe('From the Playground');
    });
});

describe('providedVariableKey', () => {
    /**
     * A `Symbol` rather than the string `'providedVariable'`: a magic string has to be spelled the
     * same way in two files and nothing checks that it was.
     */
    it('is a symbol, so no string can collide with it', () => {
        expect(typeof providedVariableKey).toBe('symbol');
        expect(String(providedVariableKey)).toContain('demo:providedVariable');
    });
});

src/modules/account/tests/profile-avatar.source:
/**
 * @module
 * Unit tests for `stores/profile.ts`'s `updateProfile` avatar branches: the multipart upload an
 * `imageUpload` switches to, progress forwarded through to the transport, and the plain-JSON
 * `imageUrl: ''` remove path. `profile.spec.ts` covers every other field of the same action; this
 * file is only about the picture, which is why it is split out — same split the plan's testing
 * table draws.
 */
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';

import { useProfileStore } from '@/modules/account/stores/profile.ts';
import { orvalMutator } from '@/infrastructure/http';
import { wireModulesIntoCore } from '../../../../tests/support/unit/wire-modules.ts';
import {
    orvalEnvelope,
    parseOrvalFixture
} from '../../../../tests/unit/infrastructure/http/orval-fixture-schema.ts';

wireModulesIntoCore();

const USER = { id: 'u1', username: 'ada', email: 'ada@example.com', admin: false };

let responses: Record<string, unknown>;

vi.mock('@/infrastructure/http', () => ({
    orvalMutator: vi.fn((config: { url: string; method: string }) => {
        const key = `${config.method?.toUpperCase()} ${config.url}`;
        return Promise.resolve(parseOrvalFixture(config.method, config.url, responses[key]));
    })
}));

/**
 * Every call the transport received, with its config AND the per-call options
 * (`updateProfile`'s second argument) that `orvalMutator` receives separately in real usage.
 */
const calls = () =>
    vi.mocked(orvalMutator).mock.calls.map(
        (call) =>
            call[0] as {
                url: string;
                method?: string;
                headers?: Record<string, string>;
                data: unknown;
            }
    );

beforeEach(() => {
    setActivePinia(createPinia());
    vi.clearAllMocks();
    responses = {
        'GET /account': orvalEnvelope(USER),
        'PUT /account': orvalEnvelope({ ...USER, imageUrl: undefined })
    };
});

describe('an imageUpload switches the call to multipart', () => {
    it('carries the file, not the old imageUrl field', () => {
        const store = useProfileStore();
        const file = new File(['pixels'], 'avatar.png', { type: 'image/png' });

        return store
            .fetchProfile(true)
            .then(() => store.updateProfile({ imageUpload: file }))
            .then(() => {
                const put = calls().find(({ method }) => method?.toUpperCase() === 'PUT')!;
                expect(put.headers?.['Content-Type']).toBe('multipart/form-data');
                expect(put.data).toBeInstanceOf(FormData);
                expect((put.data as FormData).get('imageUpload')).toBe(file);
                expect((put.data as FormData).has('imageUrl')).toBe(false);
            });
    });

    it('forwards onUploadProgress through to the transport', () => {
        const store = useProfileStore();
        const file = new File(['pixels'], 'avatar.png', { type: 'image/png' });
        const onUploadProgress = vi.fn();

        return store
            .fetchProfile(true)
            .then(() => store.updateProfile({ imageUpload: file }, { onUploadProgress }))
            .then(() => {
                const optionsSeen = vi
                    .mocked(orvalMutator)
                    .mock.calls.map((call) => call[1] as { onUploadProgress?: unknown } | undefined)
                    .find((options) => options?.onUploadProgress === onUploadProgress);
                expect(optionsSeen).toBeDefined();
            });
    });

    it('refetches the profile afterward, same as every other field', () => {
        const store = useProfileStore();
        const file = new File(['pixels'], 'avatar.png', { type: 'image/png' });

        return store
            .fetchProfile(true)
            .then(() => store.updateProfile({ imageUpload: file }))
            .then(() => {
                const methods = calls().map(({ method }) => method?.toUpperCase());
                // ...GET, PUT, GET: the write, then the re-read `updateProfile` always chains.
                expect(methods.at(-1)).toBe('GET');
            });
    });
});

describe('removing the picture', () => {
    it('sends imageUrl: "" through the plain JSON path — not multipart', () => {
        const store = useProfileStore();

        return store
            .fetchProfile(true)
            .then(() => store.updateProfile({ imageUrl: '' }))
            .then(() => {
                const put = calls().find(({ method }) => method?.toUpperCase() === 'PUT')!;
                expect(put.headers?.['Content-Type']).not.toBe('multipart/form-data');
                expect(put.data).toMatchObject({ imageUrl: '' });
            });
    });
});

tests/unit/infrastructure/session.spec.t.source:
/**
 * `persistLocalePreference` — `src/infrastructure/session.ts`.
 *
 * The one write the session store makes that is not about the session itself, and the reason
 * `AppLanguageSwitcher` does not know what a session is. Every case below is the same claim from
 * a different side: **choosing a language always succeeds, whatever the account endpoint does.**
 *
 * The store is real — `isAuth` derives from token AND viewer, and stubbing it would test the stub.
 * Only `@api` is mocked, at the network boundary.
 */
import { describe, it, expect, beforeEach, vi } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';

const updateAccountMock = vi.fn();
const getAccountMock = vi.fn();

vi.mock('@api', () => ({
    getAccount: () => getAccountMock(),
    refreshToken: vi.fn(),
    logout: vi.fn(),
    logoutAll: vi.fn(),
    updateAccount: (body: { locale: string }) => updateAccountMock(body)
}));

const { useSessionStore } = await import('@/infrastructure/session.ts');

/** A store with a token AND a viewer, which is what `isAuth` actually requires. */
const signedIn = () => {
    const store = useSessionStore();
    store.setAccessToken('token');
    store.setViewer({ id: '1', email: 'a@b.c', admin: false });
    return store;
};

beforeEach(() => {
    setActivePinia(createPinia());
    vi.clearAllMocks();
    updateAccountMock.mockResolvedValue({ data: {} });
});

describe('persistLocalePreference', () => {
    it('writes the choice onto a signed-in visitor’s account', () => {
        return signedIn()
            .persistLocalePreference('it')
            .then(() => {
                expect(updateAccountMock).toHaveBeenCalledWith({ locale: 'it' });
            });
    });

    /*
     * The rule that used to live at the call site. A guest has no record to write to, so the call
     * is not made at all — an anonymous `PUT /account` would answer 401 and teach nobody anything.
     */
    it('does not call the API for a guest', () => {
        return useSessionStore()
            .persistLocalePreference('it')
            .then(() => {
                expect(updateAccountMock).not.toHaveBeenCalled();
            });
    });

    /* A token with no viewer is a session restored but not yet identified — not signed in. */
    it('does not call the API for a token whose holder is still unknown', () => {
        const store = useSessionStore();
        store.setAccessToken('token');
        return store.persistLocalePreference('it').then(() => {
            expect(updateAccountMock).not.toHaveBeenCalled();
        });
    });

    it('resolves rather than rejecting when the write fails', () => {
        updateAccountMock.mockRejectedValue(new Error('account service down'));
        return expect(signedIn().persistLocalePreference('it')).resolves.toBeUndefined();
    });

    /*
     * Stated as its own case because it is the whole point of the seam: the switcher fires this
     * without awaiting it, so a rejection that escaped would surface as an unhandled rejection in
     * the console of a page that switched language perfectly well.
     */
    it('resolves with nothing on the happy path too, so the caller can ignore it', () => {
        return expect(signedIn().persistLocalePreference('en')).resolves.toBeUndefined();
    });
});

/** Every cookie this store touches, as a plain map — jsdom keeps `document.cookie` real. */
const cookieJar = () =>
    Object.fromEntries(
        document.cookie
            .split('; ')
            .filter(Boolean)
            .map((pair) => pair.split('=') as [string, string])
    );

describe('setAccessToken — the isAuth/rememberMe cookie pair', () => {
    beforeEach(() => {
        // Tests earlier in this file call `signedIn()`, which sets these cookies as a side
        // effect; jsdom keeps `document.cookie` for the whole file, not per test. Cleared through
        // the store's own method, like production code, rather than a raw assignment.
        useSessionStore().clearSession();
    });

    it('sets a session-only isAuth cookie when remember was not chosen', () => {
        useSessionStore().setAccessToken('token', false);

        const jar = cookieJar();
        expect(jar.isAuth).toBe('true');
        expect(jar.rememberMe).toBeUndefined();
    });

    it('sets a persistent isAuth cookie when remember was chosen', () => {
        useSessionStore().setAccessToken('token', true);

        const jar = cookieJar();
        expect(jar.isAuth).toBe('true');
        expect(jar.rememberMe).toBe('true');
    });

    /*
     * The bug this closes: a silent refresh does not know the original login's choice, so it
     * must read it back from `rememberMe` rather than defaulting to session-only — otherwise a
     * "remember me" visitor's isAuth hint would still die at the next browser restart.
     */
    it('keeps the isAuth cookie persistent across a refresh that does not pass `remember`', () => {
        const store = useSessionStore();
        store.setAccessToken('token', true);

        store.setAccessToken('refreshed-token');

        expect(cookieJar().rememberMe).toBe('true');
        // Presence is what `tryRestoreAuth` reads; jsdom does not expose max-age back out.
        expect(cookieJar().isAuth).toBe('true');
    });

    it('does not start a rememberMe marker for a login that never opts in', () => {
        const store = useSessionStore();
        store.setAccessToken('token', true);

        store.setAccessToken('token-again', false);

        expect(cookieJar().rememberMe).toBeUndefined();
    });
});

describe('loadViewer', () => {
    /**
     * `thumbnailUrl` rides alongside `imageUrl` on the account payload — the shell's avatar is the
     * one place outside `account` itself that reads either, so a projection that dropped it would
     * silently fall back to loading the full image for every navigation-bar avatar.
     */
    it('carries thumbnailUrl into the viewer projection', () => {
        getAccountMock.mockResolvedValue({
            data: {
                id: '1',
                email: 'a@b.c',
                admin: false,
                imageUrl: '/images/abc.png',
                thumbnailUrl: '/images/thumbs/v1/abc.webp'
            }
        });
        const store = useSessionStore();

        return store.loadViewer().then(() => {
            expect(store.viewer?.imageUrl).toBe('/images/abc.png');
            expect(store.viewer?.thumbnailUrl).toBe('/images/thumbs/v1/abc.webp');
        });
    });

    it('leaves thumbnailUrl undefined for an account with none', () => {
        getAccountMock.mockResolvedValue({
            data: { id: '1', email: 'a@b.c', admin: false, imageUrl: '/images/abc.png' }
        });
        const store = useSessionStore();

        return store.loadViewer().then(() => {
            expect(store.viewer?.thumbnailUrl).toBeUndefined();
        });
    });
});

src/modules/admin/tests/use-admin-observ.source:
/**
 * @module
 * Unit tests for the Admin dashboard's data composable.
 *
 * The three endpoints are mocked at `@api`: what this file owns is the composition — that each
 * fetcher writes its own slice of state without touching the other two, that the audit envelope is
 * split into items and page meta rather than tracked as state that could disagree, and that a dead
 * endpoint degrades to an error message beside the panels that did answer.
 *
 * The loading/error bookkeeping itself belongs to `useAsyncAction` and is covered in
 * `tests/unit/infrastructure/use-async-action.spec.ts`; only the parts this composable configures —
 * the fallback messages and the filter payload — are asserted here.
 */
import { beforeEach, describe, expect, it, vi } from 'vitest';
import {
    getObservabilityHealth,
    getObservabilityMetricsOverview,
    getObservabilityAuditLogs,
    deleteExpiredTokens
} from '@api';
import type { AuditEventItem } from '@api';
import { useAdminObservability } from '@/modules/admin/composables/use-admin-observability';

const HEALTH = { status: 'ok', uptimeSeconds: 120 };
const METRICS = { totalRequests: 42, totalErrors: 1 };

/**
 * A page's worth of meta, as `PaginationMeta` declares it.
 */
const meta = (totalItems: number, totalPages = 1, page = 1, pageSize = 50) => ({
    page,
    pageSize,
    totalItems,
    totalPages
});

/**
 * One audit row exactly as `AuditEventItem` declares it.
 *
 * Typed rather than a bare literal: the schema is `additionalProperties: false` with six required
 * fields, so an invented key or a missing one is a compile error here instead of a green test
 * standing on a shape the endpoint never returns.
 */
const AUDIT_ITEM: AuditEventItem = {
    actor_user_id: 'ada@example.com',
    actor_role: 'admin',
    action: 'user.login',
    outcome: 'success',
    timestamp: '2026-01-01T00:00:00.000Z',
    level: 'info'
};

vi.mock('@api', () => ({
    getObservabilityHealth: vi.fn(() => Promise.resolve({ data: HEALTH })),
    getObservabilityMetricsOverview: vi.fn(() => Promise.resolve({ data: METRICS })),
    getObservabilityAuditLogs: vi.fn(() =>
        Promise.resolve({ data: { items: [AUDIT_ITEM], meta: meta(1) } })
    ),
    deleteExpiredTokens: vi.fn(() => Promise.resolve({ data: undefined }))
}));

/**
 * The reject envelope every real API failure arrives in — `onResponseReject` builds it, and it is
 * a plain object, never an `Error`. Rejecting with anything else here would let a composable that
 * reads its message off `instanceof Error` pass while showing its fallback to every user.
 */
const apiFailure = (status: number, message: string) => ({
    success: false,
    status,
    message,
    errors: [{ code: 'STUB_ERROR', message }]
});

describe('useAdminObservability', () => {
    beforeEach(() => {
        vi.clearAllMocks();
    });

    describe('initial state', () => {
        it('starts with nothing loaded, nothing loading and nothing failed', () => {
            const observability = useAdminObservability();

            expect(observability.health.value).toBeUndefined();
            expect(observability.metrics.value).toBeUndefined();
            expect(observability.auditEvents.value).toEqual([]);
            expect(observability.auditTotal.value).toBe(0);
            expect(observability.loadingHealth.value).toBe(false);
            expect(observability.loadingMetrics.value).toBe(false);
            expect(observability.loadingAudit.value).toBe(false);
            expect(observability.clearingExpiredTokens.value).toBe(false);
            expect(observability.errorHealth.value).toBeUndefined();
            expect(observability.errorMetrics.value).toBeUndefined();
            expect(observability.errorAudit.value).toBeUndefined();
        });
    });

    describe('fetchHealth', () => {
        it('unwraps the response body into health', () => {
            const { health, fetchHealth } = useAdminObservability();

            return expect(fetchHealth())
                .resolves.toBeUndefined()
                .then(() => {
                    expect(getObservabilityHealth).toHaveBeenCalledTimes(1);
                    expect(health.value).toEqual(HEALTH);
                });
        });

        it('is loading while the call is in flight', () => {
            const { loadingHealth, fetchHealth } = useAdminObservability();

            const pending = fetchHealth();
            expect(loadingHealth.value).toBe(true);

            return pending.then(() => {
                expect(loadingHealth.value).toBe(false);
            });
        });

        it('reports its own failure without rejecting or touching the other panels', () => {
            vi.mocked(getObservabilityHealth).mockRejectedValueOnce(
                apiFailure(503, 'Health probe timed out')
            );
            const { health, errorHealth, errorMetrics, errorAudit, fetchHealth } =
                useAdminObservability();

            return expect(fetchHealth())
                .resolves.toBeUndefined()
                .then(() => {
                    // The API's own words, not the fallback: the panel is more useful for saying which
                    // probe failed than for saying that something did.
                    expect(errorHealth.value).toBe('Health probe timed out');
                    expect(health.value).toBeUndefined();
                    expect(errorMetrics.value).toBeUndefined();
                    expect(errorAudit.value).toBeUndefined();
                });
        });
    });

    describe('fetchMetrics', () => {
        it('unwraps the response body into metrics', () => {
            const { metrics, fetchMetrics } = useAdminObservability();

            return fetchMetrics().then(() => {
                expect(getObservabilityMetricsOverview).toHaveBeenCalledTimes(1);
                expect(metrics.value).toEqual(METRICS);
            });
        });

        it('carries its own fallback message when the rejection says nothing', () => {
            // A rejection with no readable message at all — a transport failure that never got a
            // body — is the only case the per-panel fallback is for.
            vi.mocked(getObservabilityMetricsOverview).mockRejectedValueOnce({ status: 0 });
            const { errorMetrics, fetchMetrics } = useAdminObservability();

            return fetchMetrics().then(() => {
                expect(errorMetrics.value).toBe('admin-page.error-load-metrics');
            });
        });
    });

    describe('fetchAuditLogs', () => {
        it('splits the envelope into items, total and page count', () => {
            const { auditEvents, auditTotal, auditPages, fetchAuditLogs } = useAdminObservability();

            return expect(fetchAuditLogs())
                .resolves.toBeUndefined()
                .then(() => {
                    expect(auditEvents.value).toEqual([AUDIT_ITEM]);
                    expect(auditTotal.value).toBe(1);
                    expect(auditPages.value).toBe(1);
                });
        });

        it('reports a total larger than the page, and the pages that reach the rest', () => {
            // The number the dashboard renders as "50 of 3,412" — and, unlike the capped read it
            // replaces, a page count that can actually get to the 3,412nd.
            vi.mocked(getObservabilityAuditLogs).mockResolvedValueOnce({
                data: { items: [AUDIT_ITEM], meta: meta(3412, 69) }
            } as never);
            const { auditTotal, auditPages, fetchAuditLogs } = useAdminObservability();

            return fetchAuditLogs().then(() => {
                expect(auditTotal.value).toBe(3412);
                expect(auditPages.value).toBe(69);
            });
        });

        it('sends every filter through under its contract name', () => {
            const { fetchAuditLogs } = useAdminObservability();

            return fetchAuditLogs({
                actor: 'ada@example.com',
                action: 'user.login',
                outcome: 'failure',
                since: '2026-01-01T00:00:00.000Z',
                page: 3,
                pageSize: 25
            }).then(() => {
                expect(getObservabilityAuditLogs).toHaveBeenCalledWith({
                    actor: 'ada@example.com',
                    action: 'user.login',
                    outcome: 'failure',
                    since: '2026-01-01T00:00:00.000Z',
                    page: 3,
                    pageSize: 25
                });
            });
        });

        it('asks for everything when called with no filters', () => {
            const { fetchAuditLogs } = useAdminObservability();

            return fetchAuditLogs().then(() => {
                expect(getObservabilityAuditLogs).toHaveBeenCalledWith({
                    actor: undefined,
                    action: undefined,
                    outcome: undefined,
                    since: undefined,
                    page: undefined,
                    pageSize: undefined
                });
            });
        });

        it('reads an empty page as no events and a zero total', () => {
            vi.mocked(getObservabilityAuditLogs).mockResolvedValueOnce({
                data: { items: [], meta: meta(0, 0) }
            } as never);
            const { auditEvents, auditTotal, auditPages, fetchAuditLogs } = useAdminObservability();

            return fetchAuditLogs().then(() => {
                expect(auditEvents.value).toEqual([]);
                expect(auditTotal.value).toBe(0);
                // No pages rather than one empty one: the pager hides itself below two.
                expect(auditPages.value).toBe(0);
            });
        });

        it('falls back to an empty page when the call fails', () => {
            vi.mocked(getObservabilityAuditLogs).mockRejectedValueOnce(
                apiFailure(500, 'Audit store unavailable')
            );
            const { auditEvents, auditTotal, auditPages, errorAudit, fetchAuditLogs } =
                useAdminObservability();

            return fetchAuditLogs().then(() => {
                // The panel renders "no events" rather than throwing on an undefined envelope
                expect(auditEvents.value).toEqual([]);
                expect(auditTotal.value).toBe(0);
                expect(auditPages.value).toBe(0);
                expect(errorAudit.value).toBe('Audit store unavailable');
            });
        });

        it('replaces the previous page rather than appending to it', () => {
            vi.mocked(getObservabilityAuditLogs).mockResolvedValueOnce({
                data: { items: [AUDIT_ITEM, AUDIT_ITEM], meta: meta(2) }
            } as never);
            const { auditEvents, auditTotal, fetchAuditLogs } = useAdminObservability();

            return fetchAuditLogs()
                .then(() => {
                    expect(auditTotal.value).toBe(2);
                    return fetchAuditLogs({ actor: 'ada@example.com' });
                })
                .then(() => {
                    expect(auditEvents.value).toEqual([AUDIT_ITEM]);
                    expect(auditTotal.value).toBe(1);
                });
        });
    });

    describe('fetchAll', () => {
        it('loads all three panels in one call', () => {
            const { health, metrics, auditEvents, auditTotal, fetchAll } = useAdminObservability();

            return expect(fetchAll())
                .resolves.toBeUndefined()
                .then(() => {
                    expect(getObservabilityHealth).toHaveBeenCalledTimes(1);
                    expect(getObservabilityMetricsOverview).toHaveBeenCalledTimes(1);
                    expect(getObservabilityAuditLogs).toHaveBeenCalledTimes(1);
                    expect(health.value).toEqual(HEALTH);
                    expect(metrics.value).toEqual(METRICS);
                    expect(auditEvents.value).toEqual([AUDIT_ITEM]);
                    expect(auditTotal.value).toBe(1);
                });
        });

        it('starts the three calls together rather than one after the other', () => {
            const { loadingHealth, loadingMetrics, loadingAudit, fetchAll } =
                useAdminObservability();

            const pending = fetchAll();
            expect(loadingHealth.value).toBe(true);
            expect(loadingMetrics.value).toBe(true);
            expect(loadingAudit.value).toBe(true);

            return pending.then(() => {
                expect(loadingHealth.value).toBe(false);
                expect(loadingMetrics.value).toBe(false);
                expect(loadingAudit.value).toBe(false);
            });
        });

        it('renders the panels that answered when one endpoint is down', () => {
            vi.mocked(getObservabilityMetricsOverview).mockRejectedValueOnce(
                apiFailure(502, 'Metrics upstream refused')
            );
            const { health, metrics, errorMetrics, auditEvents, fetchAll } =
                useAdminObservability();

            return expect(fetchAll())
                .resolves.toBeUndefined()
                .then(() => {
                    expect(errorMetrics.value).toBe('Metrics upstream refused');
                    expect(metrics.value).toBeUndefined();
                    expect(health.value).toEqual(HEALTH);
                    expect(auditEvents.value).toEqual([AUDIT_ITEM]);
                });
        });
    });

    /*
     * The one WRITE on this composable, and the only one that rejects: the view owes the visitor
     * an answer either way, so the rejection is passed through rather than swallowed into an
     * `error` ref like the three reads. What the composable does own is the pending flag, which
     * the view binds to the button and never sets — so both halves are asserted here.
     */
    describe('clearExpiredTokens', () => {
        it('flags the purge as pending while the call is in flight', () => {
            const { clearingExpiredTokens, clearExpiredTokens } = useAdminObservability();

            const pending = clearExpiredTokens();
            expect(clearingExpiredTokens.value).toBe(true);

            return pending.then(() => {
                expect(clearingExpiredTokens.value).toBe(false);
            });
        });

        it('resolves with nothing, so the view answers with its own copy', () => {
            const { clearExpiredTokens } = useAdminObservability();

            return expect(clearExpiredTokens())
                .resolves.toBeUndefined()
                .then(() => {
                    expect(deleteExpiredTokens).toHaveBeenCalledTimes(1);
                });
        });

        it('rejects on failure rather than swallowing it into an error ref', () => {
            vi.mocked(deleteExpiredTokens).mockRejectedValueOnce('down');
            const { clearingExpiredTokens, clearExpiredTokens } = useAdminObservability();

            return expect(clearExpiredTokens())
                .rejects.toBe('down')
                .then(() => {
                    // `.finally`, not `.then` — a failed purge must not leave the button spinning.
                    expect(clearingExpiredTokens.value).toBe(false);
                });
        });
    });
});

