/**
 * @module
 * Unit tests for the OAuth provider store and its two pure helpers — mocking only the transport
 * and keying answers by request URL, same pattern as `sessions.spec.ts`.
 */
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';
import {
    useOAuthProvidersStore,
    oauthStartUrl,
    providerLabel
} from '@/modules/account/stores/oauth.ts';
import { orvalMutator } from '@/infrastructure/http';
import { wireModulesIntoCore } from '../../../../tests/support/unit/wire-modules.ts';
import {
    orvalEnvelope,
    parseOrvalFixture
} from '../../../../tests/unit/infrastructure/http/orval-fixture-schema.ts';

wireModulesIntoCore();

/**
 * Responses per endpoint, consulted by the mocked transport below and reset in `beforeEach`.
 */
let responses: Record<string, unknown>;

vi.mock('@/infrastructure/http', () => ({
    orvalMutator: vi.fn((config: { url: string; method: string }) => {
        const key = `${config.method?.toUpperCase()} ${config.url}`;
        const response = responses[key];
        return response instanceof Error
            ? Promise.reject(response)
            : Promise.resolve(parseOrvalFixture(config.method, config.url, response));
    })
}));

beforeEach(() => {
    setActivePinia(createPinia());
    vi.clearAllMocks();
    responses = {
        'GET /account/oauth/providers': orvalEnvelope({ providers: ['google', 'github'] })
    };
});

describe('providerLabel', () => {
    it('overrides the names a bare capitalization gets wrong', () => {
        expect(providerLabel('github')).toBe('GitHub');
    });

    it('capitalizes anything it has no override for', () => {
        expect(providerLabel('google')).toBe('Google');
        expect(providerLabel('fake')).toBe('Fake');
    });
});

describe('oauthStartUrl', () => {
    it('points at the backend start-login route for that provider', () => {
        const apiUrl = import.meta.env.VITE_API_URL as string;
        expect(oauthStartUrl('google')).toBe(`${apiUrl}/account/oauth/google`);
    });
});

describe('useOAuthProvidersStore', () => {
    it('fetchProviders loads the enabled provider list', () =>
        useOAuthProvidersStore()
            .fetchProviders()
            .then((providers) => {
                expect(providers).toEqual(['google', 'github']);
                expect(useOAuthProvidersStore().providers).toEqual(['google', 'github']);
            }));

    it('a later call is a no-op, reusing the cached list', () =>
        useOAuthProvidersStore()
            .fetchProviders()
            .then(() => useOAuthProvidersStore().fetchProviders())
            .then(() => {
                expect(orvalMutator).toHaveBeenCalledTimes(1);
            }));

    it('a payload with no list reads as no providers', () => {
        // `providers` is required by the real contract, so this exact payload is impossible
        // against it — it bypasses `parseOrvalFixture` on purpose to pin the store's OWN defence
        // for that state, same as `addresses.spec.ts`'s book-less case.
        vi.mocked(orvalMutator).mockImplementationOnce(() =>
            Promise.resolve({ success: true, status: 200, message: 'OK', data: {} })
        );
        return useOAuthProvidersStore()
            .fetchProviders()
            .then((providers) => {
                expect(providers).toEqual([]);
            });
    });

    it('a failed request resolves to the empty list and stays retryable', () => {
        responses['GET /account/oauth/providers'] = new Error('network down');
        const store = useOAuthProvidersStore();

        return store
            .fetchProviders()
            .then((providers) => {
                expect(providers).toEqual([]);
                // Not cached as "no providers, forever" — a transient failure gets another try.
                responses['GET /account/oauth/providers'] = orvalEnvelope({
                    providers: ['github']
                });
                return store.fetchProviders();
            })
            .then((providers) => {
                expect(providers).toEqual(['github']);
                expect(orvalMutator).toHaveBeenCalledTimes(2);
            });
    });
});

tests/cross-cutting/module-file-shapes.s.source:
/**
 * Every file in a module folder is a shape someone named on purpose.
 *
 * A module is a vocabulary as much as a folder: `module.ts`, `routes.ts`, `store.ts`,
 * `views/*.vue`, `response-schemas.ts`. That vocabulary is what makes fourteen domains legible to
 * someone who has read one of them — and it holds only as long as nothing else quietly appears
 * beside it. A `helpers/`, a `utils.ts`, a `constants.ts`: each is reasonable on its own, and
 * together they are the end of the pattern, because the next person copies whatever they find.
 *
 * So a file matching no entry in the catalogue below fails, by name. Adding a shape costs one line
 * here, and writing that line is the point: it is the moment to ask whether the shape should exist
 * at all, rather than the moment it becomes invisible.
 *
 * Nothing else in this suite covers this. `store-location.spec.ts` rules on store FILENAMES — it
 * does not sweep the whole folder, and a stray file passes it.
 *
 * ── Where this came from ─────────────────────────────────────────────────────────────────────
 * This catalogue used to live in `scripts/module-docs/shapes.ts`, where it rendered the **Files**
 * table on every module page and, as a side effect, enforced this rule. The generator is gone and
 * the module pages are written by hand; the rule was the half worth keeping, so it moved here
 * where rules live. The one-line description is kept even though nothing renders it any more —
 * see above for why.
 *
 * See: docs/theory/modules.md
 */

import { describe, expect, it } from 'vitest';
import { existsSync, readdirSync, statSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { enabledModules } from '@/modules';

const MODULES_ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), '../../src/modules');

/** One entry: the pattern a module-relative path matches, and what that file is. */
interface FileShape {
    /** Matched against the module-relative path, e.g. `views/Cart.vue`. */
    match: RegExp;

    /** One line, present tense, describing the file's job. */
    what: string;
}

/** Ordered most-specific first: the first match wins. */
const FILE_SHAPES: readonly FileShape[] = [
    {
        match: /^module\.ts$/,
        what: 'The manifest — the only file the application loads directly. Declares the name, routes, navigation entries, response schemas, dependency edges and locales.'
    },
    {
        match: /^index\.ts$/,
        what: 'The public barrel: the only surface a sibling module may import.'
    },
    {
        match: /^routes\.ts$/,
        what: 'The domain’s route records, spliced into the localised route tree. Each carries its own `meta.access`.'
    },
    {
        match: /^store\.ts$/,
        what: 'The Pinia store: this domain’s state, and every call it makes to the generated client.'
    },
    {
        match: /^stores\/.+\.ts$/,
        what: 'One of several Pinia stores, for a module that has more than one. `store.ts` is the usual shape.'
    },
    {
        match: /^response-schemas\.ts$/,
        what: 'One row per endpoint this domain calls, pairing a method and path pattern with the Zod envelope its response is validated against.'
    },
    {
        match: /^schemas\.ts$/,
        what: 'Form schemas for this domain, built on the generated request schemas rather than hand-written beside them.'
    },
    {
        match: /^domain\/index\.ts$/,
        what: 'The domain barrel.'
    },
    {
        match: /^domain\/.+\.ts$/,
        what: 'Pure client-side rules over plain data — no store, no component, no axios.'
    },
    {
        match: /^views\/.+\.vue$/,
        what: 'A routed screen. Reads its store, renders, and holds no fetching logic of its own.'
    },
    {
        match: /^components\/.+\.vue$/,
        what: 'A component this domain owns. Published through the barrel when a sibling mounts it, internal otherwise.'
    },
    {
        match: /^composables\/.+\.ts$/,
        what: 'Reusable reactive logic for this domain — the tier between a store and a component.'
    },
    {
        match: /^locales\/.+\.json$/,
        what: 'This domain’s translation dictionary for one language, loaded as its own chunk.'
    },
    {
        match: /^guards\.ts$/,
        what: '`demo` only. The route guards that keep the showcase out of a production build.'
    },
    {
        match: /^provided\.ts$/,
        what: '`demo` only. The sample data the showcase renders, so no screen invents its own.'
    },
    {
        match: /^dictionaries\.ts$/,
        what: '`locales` only. The runtime override merge — server rows layered over what the app bundles, key by key.'
    },
    {
        match: /^types\.ts$/,
        what: '`admin` only. The shapes the dashboard assembles that no endpoint answers with directly.'
    },
    {
        match: /^use-realtime-observability\.ts$/,
        what: '`realtime` only. The composable a screen uses to subscribe to that stream and unsubscribe on unmount.'
    },
    {
        match: /^tests\/e2e\/__snapshots__\/.+\.png$/,
        what: 'A committed visual-regression baseline.'
    },
    {
        match: /^tests\/e2e\/.+\.cy\.ts$/,
        what: 'Cypress suite — the screens, in a browser.'
    },
    {
        match: /^tests\/.+\.spec\.ts$/,
        what: 'Vitest suite — the store, the routes and the rules, in isolation.'
    }
];

/** Every file under `directory`, as paths relative to it, sorted. */
const walk = (directory: string, base = directory): string[] => {
    if (!existsSync(directory)) return [];
    return readdirSync(directory)
        .flatMap((entry) => {
            const full = path.join(directory, entry);
            return statSync(full).isDirectory() ? walk(full, base) : [path.relative(base, full)];
        })
        .toSorted();
};

/** Every module-relative file path, paired with the module it belongs to. */
const filesInModules = (): { module: string; file: string }[] =>
    enabledModules.flatMap((appModule) =>
        walk(path.join(MODULES_ROOT, appModule.name)).map((file) => ({
            module: appModule.name,
            file
        }))
    );

describe('the module file vocabulary', () => {
    it('describes every file a module folder holds', () => {
        const unknown = filesInModules()
            .filter(({ file }) => !FILE_SHAPES.some((shape) => shape.match.test(file)))
            .map(
                ({ module, file }) =>
                    `src/modules/${module}/${file} matches no shape. Add one line to FILE_SHAPES describing it — or reconsider whether the file belongs in a module at all.`
            );

        expect(unknown).toEqual([]);
    });

    /**
     * The guard on the guard: an empty sweep would satisfy the rule above by checking nothing,
     * and a broken `walk` or an emptied registry looks exactly like a clean codebase from here.
     */
    it('is sweeping the files it is meant to be sweeping', () => {
        expect(filesInModules().length).toBeGreaterThan(100);
    });
});

tests/unit/infrastructure/i18n/locale-ov.source:
import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';

/**
 * Runtime locale discovery and the override tier — `src/infrastructure/i18n/locale-overrides.ts`.
 *
 * The property every test here defends is the same one: **none of this may ever be load-bearing**.
 * The bundled `src/locales/*.json` is the floor, and every function below must degrade to it — so
 * each resolves, never rejects, and the app is fully usable when all of them return nothing.
 *
 * The second property is the merge itself: overrides win PER KEY and the merge is DEEP. A shallow
 * one would let a single edited string delete every sibling under its group, which is the failure
 * this tier is most likely to ship with and the one nobody would report as a merge bug.
 *
 * `@api` is mocked at the network boundary; everything else is real.
 */

const getLocalesMock = vi.fn();
const getLocaleMessagesMock = vi.fn();

vi.mock('@api', async (importOriginal) => ({
    // The generated const objects are not network calls — the module under test may compare
    // against them, so the real ones have to survive the mock.
    ...(await importOriginal<Record<string, unknown>>()),
    getLocales: () => getLocalesMock(),
    getLocaleMessages: (locale: string, parameters?: { tenant?: string }) =>
        getLocaleMessagesMock(locale, parameters)
}));

const { fetchRemoteLocales, fetchLocaleOverrides, mergeRemoteLocales, withLocaleOverrides } =
    await import('@/infrastructure/i18n/locale-overrides.ts');
const { supportedLanguages } = await import('@/infrastructure/i18n');

/** `supportedLanguages` is module state shared with the app-wide instance. */
let snapshot: string[] = [];

/**
 * A capability row as `GET /locales` publishes one.
 *
 * The endpoint answers CAPABILITIES, not bare tags: `tenants` says whether the API can answer in
 * that language (`api`), whether a dictionary can be downloaded for it (`app`), or both.
 *
 * @param tag - the language tag
 * @param tenants - which tenants have words in that language
 * @returns the capability row
 */
const capability = (tag: string, tenants: string[] = ['demo-be', 'demo-fe']) => ({
    tag,
    name: tag,
    nativeName: tag,
    direction: 'ltr',
    tenants,
    source: 'both'
});

beforeEach(() => {
    vi.clearAllMocks();
    snapshot = [...supportedLanguages];
    getLocalesMock.mockResolvedValue({
        data: { locales: [capability('en'), capability('it')], default: 'en', fallback: 'en' }
    });
    getLocaleMessagesMock.mockResolvedValue({ data: { messages: { greeting: 'Ciao' } } });
});

afterEach(() => {
    supportedLanguages.splice(0, Number.POSITIVE_INFINITY, ...snapshot);
});

describe('fetchRemoteLocales', () => {
    it('returns the languages the API reports', () => {
        return expect(fetchRemoteLocales()).resolves.toEqual(['en', 'it']);
    });

    /**
     * Both tenants belong in the switcher, and they are different offers — the frontend translates the
     * interface, `api` translates what the API says. A language with one and not the other is
     * half-usable, which is a state a person chose and not one to filter away: see the note on
     * `fetchRemoteLocales` about why nothing here reconciles the two sides.
     */
    it.each([
        ['downloadable only', ['demo-fe']],
        ['answerable only', ['demo-be']],
        ['both', ['demo-be', 'demo-fe']]
    ])('keeps a language that is %s', (_label, tenants) => {
        getLocalesMock.mockResolvedValue({ data: { locales: [capability('es', tenants)] } });
        return expect(fetchRemoteLocales()).resolves.toEqual(['es']);
    });

    it('drops a language that claims no tenant at all', () => {
        getLocalesMock.mockResolvedValue({
            data: { locales: [capability('en'), { ...capability('es'), tenants: [] }] }
        });
        return expect(fetchRemoteLocales()).resolves.toEqual(['en']);
    });

    it('returns an empty list when the API is unreachable', () => {
        getLocalesMock.mockRejectedValue(new Error('network down'));
        return expect(fetchRemoteLocales()).resolves.toEqual([]);
    });

    /**
     * An older API, or a different one entirely — these boilerplates are meant to be recombined,
     * so a counterpart without the endpoint is a supported configuration, not a fault.
     */
    it('returns an empty list when the API does not implement the endpoint', () => {
        getLocalesMock.mockResolvedValue({ data: undefined });
        return expect(fetchRemoteLocales()).resolves.toEqual([]);
    });
});

describe('fetchLocaleOverrides', () => {
    it('returns what has been edited for that language', () => {
        return expect(fetchLocaleOverrides('it'))
            .resolves.toEqual({ greeting: 'Ciao' })
            .then(() => {
                // Named tenant: the API builds THIS frontend's dictionary, never another client's.
                expect(getLocaleMessagesMock).toHaveBeenCalledWith('it', { tenant: 'demo-fe' });
            });
    });

    it('returns nothing rather than rejecting when the fetch fails', () => {
        getLocaleMessagesMock.mockRejectedValue(new Error('network down'));
        return expect(fetchLocaleOverrides('it')).resolves.toEqual({});
    });

    /**
     * A 404 is the ordinary answer for a language nobody has edited, and for a deactivated one.
     * Both mean the same thing to a client, which is why neither is treated as a failure.
     */
    it('returns nothing when the API has no such locale', () => {
        getLocaleMessagesMock.mockResolvedValue({ data: undefined });
        return expect(fetchLocaleOverrides('kl')).resolves.toEqual({});
    });
});

describe('mergeRemoteLocales', () => {
    it('adds a language the API offers and this build does not bundle', () => {
        getLocalesMock.mockResolvedValue({
            data: { locales: [capability('en'), capability('es')] }
        });

        return mergeRemoteLocales().then((added) => {
            expect(added).toEqual(['es']);
            expect(supportedLanguages).toContain('es');
        });
    });

    it('adds nothing twice, however often it runs', () => {
        getLocalesMock.mockResolvedValue({ data: { locales: [capability('es')] } });

        return mergeRemoteLocales()
            .then(() => mergeRemoteLocales())
            .then(() => {
                expect(supportedLanguages.filter((locale) => locale === 'es')).toHaveLength(1);
            });
    });

    it('leaves the bundled languages alone when the API is unreachable', () => {
        getLocalesMock.mockRejectedValue(new Error('network down'));

        return mergeRemoteLocales().then((added) => {
            expect(added).toEqual([]);
            expect(supportedLanguages).toEqual(snapshot);
        });
    });
});

describe('withLocaleOverrides', () => {
    it('layers what has been edited over what was bundled', () => {
        getLocaleMessagesMock.mockResolvedValue({
            data: { messages: { greeting: 'Ciao dal database' } }
        });

        return withLocaleOverrides('it', { greeting: 'Ciao', farewell: 'Addio' }).then((merged) => {
            expect(merged).toEqual({ greeting: 'Ciao dal database', farewell: 'Addio' });
        });
    });

    /**
     * A language this build ships no file for. The overrides ARE the dictionary, and everything
     * they do not carry is left for `fallbackLocale` to answer key by key.
     */
    it('is the whole dictionary for a language the bundle does not have', () => {
        getLocaleMessagesMock.mockResolvedValue({
            data: { messages: { navigation: { home: 'Inicio' } } }
        });

        return withLocaleOverrides('es', {}).then((merged) => {
            expect(merged).toEqual({ navigation: { home: 'Inicio' } });
        });
    });

    it('still returns the bundled copy when the overrides cannot be fetched', () => {
        getLocaleMessagesMock.mockRejectedValue(new Error('network down'));

        return withLocaleOverrides('it', { greeting: 'Ciao' }).then((merged) => {
            expect(merged).toEqual({ greeting: 'Ciao' });
        });
    });
});

