/**
 * @module
 * Unit tests for the device-sessions store — the list, and revoking one entry — mocking only the
 * transport and keying answers by request URL, same pattern as `profile.spec.ts`.
 */
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';

import { useAccountSessionsStore } from '@/modules/account/stores/sessions.ts';
import { orvalMutator } from '@/infrastructure/http';
import { wireModulesIntoCore } from '../../../../tests/support/unit/wire-modules.ts';
import {
    orvalEnvelope,
    parseOrvalFixture
} from '../../../../tests/unit/infrastructure/http/orval-fixture-schema.ts';

wireModulesIntoCore();

/**
 * Responses per endpoint, consulted by the mocked transport below and reset in `beforeEach`.
 */
let responses: Record<string, unknown>;

vi.mock('@/infrastructure/http', () => ({
    orvalMutator: vi.fn((config: { url: string; method: string }) => {
        const key = `${config.method?.toUpperCase()} ${config.url}`;
        return Promise.resolve(parseOrvalFixture(config.method, config.url, responses[key]));
    })
}));

/**
 * Every request URL handed to the transport, in order.
 */
const requestedUrls = () =>
    vi.mocked(orvalMutator).mock.calls.map((call) => (call[0] as { url: string }).url);

beforeEach(() => {
    setActivePinia(createPinia());
    vi.clearAllMocks();
    responses = {
        'GET /account/sessions': orvalEnvelope({ sessions: [{ id: 's1', current: true }] }),
        'DELETE /account/sessions/s1': orvalEnvelope()
    };
});

describe('useAccountSessionsStore', () => {
    it('revokeSession reloads the list it changed', () => {
        const store = useAccountSessionsStore();
        return store
            .fetchSessions()
            .then(() => store.revokeSession('s1'))
            .then(() => {
                expect(requestedUrls().slice(-3)).toEqual([
                    '/account/sessions',
                    '/account/sessions/s1',
                    '/account/sessions'
                ]);
                expect(store.sessions.map(({ id }) => id)).toEqual(['s1']);
            });
    });

    it('a sessions payload without the list reads as no sessions', () => {
        // `sessions` is required by the real contract, so this exact payload is impossible
        // against it — it bypasses `parseOrvalFixture` on purpose to pin the store's OWN defence
        // for that state, same as `addresses.spec.ts`'s book-less case.
        vi.mocked(orvalMutator).mockImplementationOnce(() =>
            Promise.resolve({ success: true, status: 200, message: 'OK', data: {} })
        );
        const store = useAccountSessionsStore();
        return store.fetchSessions().then(() => {
            expect(store.sessions).toEqual([]);
        });
    });
});

src/modules/demo/tests/guards.spec.ts.source:
/**
 * @module
 * Demo router guard — `src/modules/demo/guards.ts` — mocking `@/infrastructure/i18n` directly
 * (translations aren't loaded yet when this guard runs), while leaving Pinia real.
 *
 * A teaching guard, scoped to the Playground route, but two of its properties are real Vue Router
 * concerns rather than demo details:
 *
 *   1. It must return `undefined`. Vue Router 4 treats *any* returned value as a navigation
 *      instruction — returning `false` would block every route, and returning an object would
 *      redirect. The docblock calls this out explicitly ("Returns nothing ... to let the
 *      navigation through"), and it is the single thing most easily broken by an edit.
 *   2. It must not throw when translations are not yet loaded. A `beforeEnter` runs before
 *      `localeChoice`, which loads the dictionary in `beforeResolve`, so `t()` is being called
 *      against an i18n instance that has no messages — the guard exists partly to demonstrate
 *      that this is survivable.
 *
 * Pinia is real here, not mocked: the point being demonstrated is that stores *do* work inside a
 * guard, and a mocked store would demonstrate nothing.
 */

import { asStub } from '../../../../tests/support/stub';
import { beforeEach, afterEach, describe, expect, it, vi } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';
import type { RouteLocationNormalized } from 'vue-router';

/**
 * Stub for `i18n.global.t`, returning the key unchanged — the guard's own point is that `t()` may not have real messages yet.
 */
const translateMock = vi.fn((key: string) => key);

/**
 * Stub for `i18n.global.locale`, boxed like the real ref so `.value` reads work.
 */
const localeRef = { value: 'en' };

vi.mock('@/infrastructure/i18n', () => ({
    i18n: {
        global: {
            get t() {
                return translateMock;
            },
            get locale() {
                return localeRef;
            }
        }
    }
}));

/**
 * The guard under test, imported after `vi.mock` above so its own `i18n` import resolves to the stub.
 */
const { exampleGuard } = await import('@/modules/demo/guards.ts');

/**
 * The real store — proving from inside the guard that Pinia (unlike i18n) needs no mock.
 */
const { useDemoStore } = await import('@/modules/demo/store.ts');

/**
 * Builds a minimal route stub carrying just the fields the guard reads.
 */
const routeTo = (path = '/en/products') =>
    asStub<RouteLocationNormalized>({ path, name: 'products', params: {}, query: {} });

/**
 * Holds the per-test `console.log` spy so `afterEach` can restore it.
 */
let consoleSpy: ReturnType<typeof vi.spyOn>;

beforeEach(() => {
    setActivePinia(createPinia());
    vi.clearAllMocks();
    // The guard logs on every navigation by design; silenced so the suite output stays readable
    // and so the resilience e2e spec's "no console noise" rule is not confused with unit output.
    consoleSpy = vi.spyOn(console, 'log').mockImplementation(() => {});
});

afterEach(() => {
    consoleSpy.mockRestore();
});

describe('exampleGuard', () => {
    it('returns undefined so the navigation is allowed through', () => {
        // Not `toBeFalsy()`: `false` is falsy too, and returning `false` from a Vue Router guard
        // aborts the navigation — i.e. would break every route in the app.
        // eslint-disable-next-line @typescript-eslint/no-confusing-void-expression -- the assertion IS that the guard returns undefined (allows the navigation)
        expect(exampleGuard(routeTo())).toBeUndefined();
    });

    it('increments the counter store, proving stores are reachable from a guard', () => {
        const store = useDemoStore();
        expect(store.count).toBe(0);

        exampleGuard(routeTo());

        expect(store.count).toBe(1);
    });

    it('accumulates across navigations rather than resetting', () => {
        const store = useDemoStore();

        exampleGuard(routeTo('/en'));
        exampleGuard(routeTo('/en/products'));
        exampleGuard(routeTo('/en/cart'));

        expect(store.count).toBe(3);
    });

    it('feeds the target path into the translation call', () => {
        exampleGuard(routeTo('/en/orders/42'));

        expect(translateMock).toHaveBeenCalledWith('generic.loading', { load: '/en/orders/42' });
    });

    it('survives translations that are not loaded yet', () => {
        // The documented lesson of the guard: it runs before the dictionary is loaded, so `t()`
        // may return the raw key. That must be harmless, not fatal.
        translateMock.mockImplementation((key: string) => key);

        expect(() => exampleGuard(routeTo())).not.toThrow();
    });
});

